/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020304-7","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"厚生委員会","time":"午前１０時０６分～午後２時１９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件抜き出しています。","topics":[{"id":"topic-01","title":"第２２号議案、品川区生業資金貸付条例および品川区応急小口資金貸付条例の廃止に伴う貸付金債権に係る償還金等の減免等に関する条例を廃止する条例","agenda":"第２２号議案、品川区生業資金貸付条例および品川区応急小口資金貸付条例の廃止に伴う貸付金債権に係る償還金等の減免等に関する条例を廃止する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この制度そのものは、もう既に条例がなくなっているということなので、この条例に反対するものではないんですが、ちょっとお聞きしたいんですが、この廃止されるときに、この生業資金というのが中小企業対策等、低所得者対策の二つの側面があるということで議事録をちょっと読ませていただいたんですけれども、現在これにかわるような制度というのがどういうものがあるのか。","respondent":"黒田生活福祉課長","answer":"低所得者等、その時点での内容としましては、一般金融機関から融資を受けることが困難なものに対し、独立の生計を立てるために必要な資金を貸し付けるということでしたので、その生業資金等の一部が生活福祉資金で、一部が中小企業のほうの制度に移行したですので。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのところに、世帯更生資金制度というのが受け皿としてあるのでということで書かれているんですが、これは今でも実際にこの制度というのはどうなっているのか、ちょっと教えていただきたいんですが。","respondent":"黒田生活福祉課長","answer":"世帯更生資金というのが社会福祉協議会で、その当時は世帯更生資金でございましたが、現在はそれが生活福祉資金と一本化されてあります。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この制度そのものは零細業者の暮らしと営業を守るために本当に大事な役割を果たしてきたということで、その廃止された後も中小の方からは５０万円あれば何とか助かるというふうなところで生業資金復活という要望がずっと長い間出されてきたと思うんですが、この制度そのものが品川区が２３区で初めて廃止したというふうなところになったと思うんですけれども、そういうところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"２番目の第２３号議案、品川区母子生活支援施設条例の一部を改正する条例","agenda":"２番目の第２３号議案、品川区母子生活支援施設条例の一部を改正する条例","exchanges":[{"speaker":"鶴副委員長","kind":"質問","question":"そのたびに、建てかえは不可能だと当時の総務部長等の答弁がありましたが、いろんな創意工夫によって、今日建てかえが可能となった。そういうことについては、当然その直営と社会福祉法人営では職員の処遇、今度は職員ですよ、そこに入所している人ということではなくて、違うわけですけれども、何かアドバイスというか注文をつけることが可能なのですか。その点をお聞きしたいんですが。","respondent":"谷田部児童課長","answer":"これは請負契約の一種でございまして、私ども区がこういう施設をこういう内容で運営してほしいという、いわゆるそのお願いに対してそれを完成させるというのが民法上の契約になってございまして、委託する私どもとしては。","id":"exchange-004"},{"speaker":"鶴副委員長","kind":"質問","question":"そうすると、この施設のありよう、例えばそのあんしんセンターにしても、本体の母子生活支援施設の事業も含めて、この社会福祉法人がその任に当たる、こういうことになるわけでしょうか。","respondent":"谷田部児童課長","answer":"４月１日に仮施設の運営を先行してまず委託をする。それから９月には新しい施設ができますので、そちらの施設全体も福栄会のほうにそのまま委託をするということで、今回４月１日から仮施設の運営を先行して委託するです。","id":"exchange-005"},{"speaker":"鶴副委員長","kind":"質問","question":"よくこの社会福祉法人等に委託しますと、即に短絡的というんでしょうか、サービスの低下につながるんだとかいう論調が必ずと言っていいほど起きてくるんですね。この社会福祉法人だとかというところに運営をお願いすることによって、それを当該自治体が直営で運営するよりもメリットがある。利用者にとってもメリットがある。そういうことのないようにお伺いしておきたいというふうに思います。","respondent":"谷田部児童課長","answer":"これはあくまでも母子の自立を支援する施設ですから、いろいろ相談事があったり、それからなるべく社会に復帰できる体制をとっていくというようなことで、通常の、役所で言えば８時半から５時１５分までの勤務では不十分だということで、やはり２４時間体制で処遇をしていく。","id":"exchange-006"},{"speaker":"鶴副委員長","kind":"質問","question":"例えば障害者住宅２戸も併設されることになっておりますね。そうすると、ここの部分はじゃあ障害福祉課の人の担当に、住宅課じゃなくてなるんですよということになるのか、そういういろいろ機能が違うんですけれども、でも、すべてのことについてはこの社会福祉法人に委託するんですよということになるのでしょうか。そこらあたりのことの進め方というのはどういうふうになるんでしょうか。","respondent":"谷田部児童課長","answer":"母子生活支援施設の管理運営を福栄会のほうに委託します。それで、母子保護の実施というのが児童福祉法第２３条ですけれども、いわゆる母子を保護するかどうかの決定といいますのは、いわゆる福祉事務所が持ってございまして、これは母子相談員、児童課に置いてあります。","id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問","question":"わかりました。福祉事務所ですね。それぞれのセクション。生活保護が必要かどうかということについては生活保護がやる。そうすると、この新しい施設に入居した人たちはどういう認識で、例えば相談業務というのは全く社会福祉法人ではやらないのですよということでいいわけですね、これは。管理運営ですから。これは老婆心に終わればいいがなというふうには思っているんですが、いかがでしょうか。","respondent":"谷田部児童課長","answer":"副委員長のおっしゃるのはもっともなことだと思います。特にこういう母子生活支援施設に入所される方については、さまざまな状況を背負って入所されるという実態があります。そういう中でいかに自立に向けた支援がこの施設の中でできるかどうか。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"要するに福栄会が委託をされて、収入をどこから福栄会として得て、当然運営していくわけですから、お金をどこかからもらわなきゃいけない。それが一つ。それから、それがどういう項目で福栄会のほうにお金が行くのかということと、それから、補助金という形では多分出ていないと思うんですけれども、そういうようなものがあるかというようなこと、あと、委託方法について教えていただければと思いますので。","respondent":"谷田部児童課長","answer":"３点目の委託の方法ですけれども、まず、今年度中に１４年度を通した基本協定を結びまして、福栄会のほうも定款変更等、それから東京都、それから厚生労働省に届け出する関係がありますので、まず基本協定書を先日結びまして、それをもとに福栄会のほうでは準備に入っていく。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"委託料の算出基準といいましょうか、それがどういうふうな数字で組み立てているのかということを、これは難しいですけど、簡単にお聞かせください。もしそこまでわかるものがあったら、ある程度具体的に教えてほしいんですが。だから、直営でやるのも委託料の数字も出てくるわけじゃないですか。となれば、その差額がどれぐらいでしょうかということも、もしわかれば教えてくださいということです。","respondent":"谷田部児童課長","answer":"委託料の算出ですけれども、こういう施設というのはほとんどは人件費になります。それで、仮施設から９月以降をにらんで、私ども職員配置というのは国の最低基準、いわゆる国が支弁費として区のほうに来る算定で私どもは組んです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、福栄会への委託ということなんですが、なぜ福栄会という社会福祉法人なのかということを１点お聞かせいただきたいんですが、福栄会にこういう母子生活支援施設に対しての経験というか、そういうふうなところがあるのか、どうしてこの社会福祉法人を選んだのかについて、１点お聞かせいただきたいと思います。","respondent":"谷田部児童課長","answer":"そうしますと、そういう各施設ごとに職員を配置するというわけにはまいりませんで、それぞれが連携をとりながらやっていくということで、そういう意味では職員の配置も柔軟に対応できる、それから新たなニーズに対応できるというのが。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その児童虐待というと本当にかなり今問題になっていて、複雑なところで、本当に専門家のいろいろと支援というか、そういうふうなのが必要とされるところだと思うんですが、ここら辺のところについてはどうなっていくのかというところをちょっとお聞かせいただきたいんですが。","respondent":"谷田部児童課長","answer":"品川区子育て支援センターの一つの仕事として、児童虐待等防止連絡協議会、これを設置する予定です。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この児童虐待等防止連絡協議会というのは、今までは児童相談所が中心になって開いてきたという経過になっていたと思うんですが、今度はここの家庭あんしんセンターが中心になって、そこに事務局を置いてということで、ここが中心になって開いていくということになっていくと思うんですが、こういうところの児童虐待とかという、こういうふうな問題に関しては本当に難しいというか。","respondent":"谷田部児童課長","answer":"今回、母子生活支援施設の条例の改正案をお願いしてございまして、母子生活支援施設での直営、公設民営等々私どもでご紹介はできますけれども、児童虐待防止の関係は、これは今回条例の審議には直接は関係ないので。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは母子生活支援施設の条例ということですけれども、これは全体の家庭あんしんセンターの施設概要の５事業がすべて福栄会に委託されるということでの条例というふうなことではないんでしょうか。改めて、ほかのところはほかのところで条例という形で出てくるのかどうか、ちょっと教えていただきたいんですが。","respondent":"谷田部児童課長","answer":"今回条例改正をお願いしていますのは、品川区母子生活支援施設条例というのが西五反田の仮施設のことを指しています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それ以外のところは、また新たに条例という形で出てくるんですか。","respondent":"谷田部児童課長","answer":"今回、年度の中で仮施設、それから新しい施設ということでちょっと複雑な事業展開をするということと、新しい施設がたくさんまた９月に入るということで、今回仮施設の運営を条例改正をお願いして、それから、新施設の新たな条例というのは第２回定例会でご提案申し上げるべく。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"わかりました。ちょっと私はこれ全体のかなというふうなところで勘違いをしていた部分がありましたので、その点についてはわかりました。改めて、このひまわり荘の母子生活支援施設、この体制が、福栄会になったときに職員体制がどういうふうになるのかということについて、お聞かせください。","respondent":"谷田部児童課長","answer":"現在の仮施設での運営は、施設長が１人、それから母子指導員が１人、それから少年指導員兼事務員が１人、それから調理員等で１人、それで嘱託医を１人置くということで５人で体制を組む。これは国の支弁費の計算による職員体制で行っていくです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"現在は５人職員がいるというふうに思っていたんですが、現在の体制と今度の体制の違いについて、ちょっと教えてください。","respondent":"谷田部児童課長","answer":"現在、嘱託医を除きまして６人で担当しています。ただし、そのうちの１人はですね、新施設の改築担当ということで別途つけてありますので、実質的には同じ数だです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"現在は６人で、１人は新施設のということで５人ですよね。そうすると、嘱託医を含めて５人なんですか。","respondent":"谷田部児童課長","answer":"その中に改築担当が１人おりますので、実質的に５人です。ただし、これは１８世帯での計算でございまして、新施設は２０世帯になりますから、２０世帯の今度、加算分というのが出てまいりますので、そのときにはまた人数が変わってまいります。","id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"簡単なことなんですけれども、この条例が母子生活支援という形で母子になって、子育てとかいろいろこれから入ってこようかと思うんですけれども、父子家庭というのもあるんで、その辺のところは男女共同参画時代と言われているときに、どうしてそこで母子だけというふうにとってくるのかなという懸念があるんだけれども、父子家庭も非常に子育てには悩んでいろいろなご苦労をされているので。","respondent":"谷田部児童課長","answer":"今年の９月に新たに設置するのは品川区家庭あんしんセンター子ども未来館ということで考えてございまして、家庭の安心ですから、それは母子家庭だろうか、父子家庭だろうが、さまざまな対応をしていくというイメージで、そのような名称を考えているです。","id":"exchange-019"},{"speaker":"須藤委員","kind":"質問・要望","question":"いろいろな施策をやっていただいて、母子も父子もという形ではなくて、やはりこういう時代ですから、父子家庭も、僕らがいろいろな相談を受けるときに、現在ではいろいろな手当の仕様がなかなか今ないんですね。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"嶋委員","kind":"質問・要望","question":"今回のひまわり荘が定員が２０世帯なんですが、今まで１８世帯、仮設におりますが、そのまま移行する場合、そうすると残りが２世帯しかないということなんですが、区としてはどのぐらいのパーセンテージ的に部屋を空けておかなくちゃならないかと思うんですが、そこら辺のお考えをお聞きをしたいことと、それからあと、今回２４時間体制ということであるんですけれども。","respondent":"谷田部児童課長","answer":"そうでなければ意味がないだろうというようなご指摘だと思いますので、私どもその辺は役所の開庁時間外にそういうような状況があった場合にも対応せざるを得ない状況には来ているというふうに思ってありますので、その辺は施設の空いている状況等々判断いたしまして。","id":"exchange-021"},{"speaker":"嶋委員","kind":"質問・要望","question":"それと、あと先ほどシェルターとしてははっきりおっしゃってはいません、緊急保護用ということなんですが、短期と言いますが、区側としては短期はどのぐらいの目安として考えていらっしゃるのか、およその目安を教えていただきたいと思います。","respondent":"谷田部児童課長","answer":"これが、１週間、１カ月、半年というようになった場合には、緊急保護の性格からちょっと外れますので、その場合には母子保護の実施をして母子生活支援施設のほうに入所をしていただくなり、それから生活保護が必要であれば、生活保護をかけて、居宅での処遇だとか。","id":"exchange-022"},{"speaker":"船波委員","kind":"質問","question":"今のご説明で、母と子が別々の場合は別のところでというような感じのご説明がありましたけれども、それではドメスティックバイオレンス対応はどうなるんでしょうか。","respondent":"谷田部児童課長","answer":"これはあくまでも児童福祉施設ですので、今船波委員がおっしゃっているのは、例えば女性が夫や恋人の暴力によって帰来先がない場合に、この施設で緊急保護ができないかどうかという趣旨のご質問だと思いますけれども、その辺につきましては、私ども相談員がおりますし。","id":"exchange-023"}]},{"id":"topic-03","title":"３番目、第２４号議案、品川区立児童センター条例の一部を改正する条例","agenda":"３番目、第２４号議案、品川区立児童センター条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"今のご説明の中で、現在改修工事を行っているというご説明がありましたので、質問をします。ということは、現在はここに子どもは行っていないんでしょうかということが一つ。それで、その条例の審議の最中より前に改修工事を行うということについては、何というか、ちょっと議員としてどうなのかなという素直な思いもありますので、その辺の見通しとか考え方について、教えていただければと思います。","respondent":"谷田部児童課長","answer":"これは、私ども保護者会の中で、保護者の方の要望といたしまして、３月になって工事が早く終わった段階、いわゆる３月末までかかる予定ですが、ただ３月には八潮北学童保育クラブの中で卒会式を行ってほしいという要望を受けてあります。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"頭では今の話を聞いて理解はしていますよ。ただ、例えばこれから同じような状況が出てきた場合に、そういう保護者の要望とか、それから地域の方々の要望は、それはあって当然ですよ。でも、だからといって、そういう立ち入り許可という名目で、じゃあ議会の先にそういうふうなことをしていいんでしょうかという疑問はついて回りますので、そのことはぜひご理解をしていただきたいと考えています。","respondent":"谷田部児童課長","answer":"１０月に行いました八潮と八潮北学童での合同の保護者会です。７時１０分に開催いたしまして、７時２０分に終わった、要は１０分間で終わったわけですけれども、その中でも幾つかご意見が出ました。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それからあと、ここの所管ではありませんけれども、将来すまいるスクールとかですね、いろんな、ここの八潮の地域の特性でもありますので、そんなことも含めて大きな視野で検討していってくださいということを要望しておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"嶋委員","kind":"質問・要望","question":"一つお聞かせいただきたい。先ほどの今の流れの中で北の名前を残してほしいという意見があったようですが、この４月からの新しい統合した後のネームは決まったんでしょうか。もし決まったら教えていただきたいと思います。","respondent":"谷田部児童課長","answer":"八潮児童センターは八潮地区のシンボル的な児童センターです。本体そのものの名称は変更する考えはございませんが、今八潮北学童のお子さんだけのクラスをたしかシリウスという学童保育クラブの愛称を使ってやっているというふうに私は伺っています。","id":"exchange-027"},{"speaker":"嶋委員","kind":"質問・要望","question":"それとあと、あそこは児童センターは図書館も併設をされているということで、いろんな一般の人が出入りをするという、特に冬場は家を持たない方たちがあそこに居住している場合もあるので、そういう意味では、地域的にはちょっと子どもさんの安全を心配している方もいらっしゃるので、そういう点はどのように考えていらっしゃるかお聞かせいただきたいと思います。","respondent":"谷田部児童課長","answer":"お子さんの安全は、日常的には確保する方向で職員にもよく言ってございまして、統合したから特別にこういうことをしろということは特段指示はしてございませんが、基本的には子どもの安全確保が第一ですよということは当初から言ってありますので。","id":"exchange-028"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"その中で気になる点を幾つか確認をしておきたいんですけれども、この跡地の約５００平米の施設と品川総合福祉センターとの関係はどういう形になるのでしょうか。要するに貸与、品川区が品川総合福祉センターに貸与する。貸与するとしたら有償なのか無償なのかを含めまして、どういう関係になるのか、まずお聞かせいただきたいというふうに思います。","respondent":"日下部障害者福祉課長","answer":"これを受けまして、品川総合福祉センターがこの新施設の設置運営の主体になる。簡単に言いますと、民設民営の施設としてこれから運営をしていく、こういう内容です。","id":"exchange-029"},{"speaker":"鶴副委員長","kind":"意見","question":"要するに、この更生施設は、今お話がありましたように民設民営、これは否定しませんが、品川区のこれは要するに行政サイドから見ましたこういった知的障害者の通所更生施設ですね。民間と直営の場合もあろうかというふうに思いますが、今回民設民営に品川総合福祉センターが手を挙げられたということは歓迎いたしますが、品川区とのかかわり合いというのは今後どうなっていきますか。","respondent":"日下部障害者福祉課長","answer":"区のほうといたしましては、基本的にこれは法律に基づく施設になりますから、こちらに入所者、まずは２０名で出発いたしますけれども、現行では措置という形をとっておりますけれども、一応区のほうが実際にそちらの施設の利用者、これについてですね、措置の調整をいたしまして。","id":"exchange-030"},{"speaker":"鶴副委員長","kind":"質問","question":"いわゆるわかくさ荘ですね。そうすると、今まではですね、品川区が最初建てた施設ですから、水道、光熱等の配線も一体となっているんじゃないかと思うんですよ。全部の施設が。","respondent":"日下部障害者福祉課長","answer":"そういった点からすれば、期間の設定につきましてはこれから具体的に詰めることになりますが、基本的には３０年程度、この辺が目安になるんではないか、このように考えております。","id":"exchange-031"},{"speaker":"鶴副委員長","kind":"質問","question":"無制限なら無制限でもそれは構いませんよ。でも何かの場合には、ちゃんと公有財産ですから戻してくださいよというようなことをやっぱり覚書なら覚書、協定書なら協定書、無償貸与の契約条件というか、そういう中でそれはうたっておくべきことではなかろうかと、こういう点を一つ思うんですね。この点どうですか。","respondent":"日下部障害者福祉課長","answer":"ですから、更新に当たって、その施設が施設としての機能が従来その間きちんと運営をされてきたかどうか、その辺も含めて、しっかりその時点で検証した上で見直しをしていく、それを更新条項として盛り込んでいく、そのような形になってまいります。","id":"exchange-032"},{"speaker":"鶴副委員長","kind":"確認","question":"それで反対された会派の人がいるんですよ。え、そんなもんかなと。あんしんセンターという二つの機能。これはここの民間の品川総合福祉センターのほうに直に行けば事が済むようになるのか、あるいはやっぱりその措置については、そこに通うか通わないかのことについては行政府である品川区の当該の所管課が、担当する課が行うんですよ、こういうことに、どういうふうな仕組みに流れがなるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"区との連携といいますか、関係ですけれども、まず今年の４月に開設ですけれども、来年の４月以降は、この措置制度が変わります。それで、開設から１年間は、少なくとも従来どおりの措置制度ということで進めてまいります。","id":"exchange-033"},{"speaker":"船波委員","kind":"質問","question":"統合された後の八潮学童のほうは在籍者数９７人という予定になっているみたいですけれども、それでは、その子どもたちを見る職員の方々はどうなっているんでしょうか。八潮北でその子どもたちの対応していた方が、今度からは八潮学童勤務になるということなんでしょうか。","respondent":"谷田部児童課長","answer":"職員の数で言えば、八潮北の職員を、数はそのまま八潮のほうに移して、一定程度安定的になるまで私どもはその人数は確保して、１４年度は運営するように準備しているです。","id":"exchange-034"},{"speaker":"船波委員","kind":"質問","question":"１５年度以降は、その八潮学童の子どもの数に応じてというふうになるんでしょうか。","respondent":"谷田部児童課長","answer":"１５年度以降の人員体制というのは１４年度の状況を見ながらやっていくわけですので、その中でお子さんの数、現在でも八潮は随分減ってきていますので、この傾向がどこまで続くのか、下げどまるのかどうなのか、その辺はまたその年度年度のお子さんの状況を見ながら。","id":"exchange-035"}]},{"id":"topic-04","title":"４番目の第２５号議案、品川区プールの管理に関する条例の一部を改正する条例","agenda":"４番目の第２５号議案、品川区プールの管理に関する条例の一部を改正する条例","exchanges":[{"speaker":"鶴副委員長","kind":"質問","question":"現在ですね、品川区には称するところのプールというのは何カ所あるんですか。民間を含めて。民間が幾らで区営、直営が幾らというふうに。","respondent":"田中健康課長","answer":"区内の施設、４番目で表現していますが、ちょっとこれは申しわけありません、書き方が悪うございまして、いわゆる許可を必要とする民間プールは１８カ所、それから学校プールは６７カ所、合わせまして８５カ所が区内にあるこの対象となるプールの数です。","id":"exchange-036"},{"speaker":"鶴副委員長","kind":"質問","question":"ごめんなさい、資料をいただいていることを失念しておりました。その１８カ所が大体この条例で今回言うところの対象になりますよね。それで、今までにこういった経営者がかわるとか、あるいは相続をしたというような事例は起きたんですか。起きていなかった、あるいはこれからは起きる可能性があるという前提に立って、こういう詳細な条項を３条の２として加えた、こういうことでしょうか。","respondent":"田中健康課長","answer":"この相続、それから会社の合併、分割というのは、平成１２年の商法改正によりまして、地位の承継がいろいろな事業について行われるというような内容で起こった事象です。","id":"exchange-037"},{"speaker":"鶴副委員長","kind":"質問","question":"それでちょっと関連してお尋ねしておきたいんですが、ここの中に、新しく例えば遊泳を通じて感染のおそれがある感染症という文言が加わりました、伝染性疾患という言葉からそういうふうに文言がかわったわけですが、ちなみに、これはこれであれですけれども、プールというのは、プールの水質の基準というのは、これは厚生労働省令ですか、で、そこはどうなっているのかということと、現状ですね。","respondent":"大沢品川区保健センター衛生課長","answer":"それで、管理者、いわゆる経営者はこれを毎月１回やるものとか、毎日やるものとか、そういうふうに規定をしまして、こちらでも監視をしている、そういうところです。","id":"exchange-038"},{"speaker":"鶴副委員長","kind":"質問","question":"まだ、これは後で資料でその５項目等についてもいただければありがたいなと思うんですが、今までに、例えばこういうプールによって、特に水を飲み込む場合もあるでしょうが、眼鏡をかけていないから、どっちかというと鼻、目、耳ぐらいに入るんでしょうか、毛穴からはなかなか。いろんなばい菌じゃないですけれども、菌はどうするのか。というようなことが起きたというような報告があるんでしょうか。","respondent":"青山品川区保健センター所長","answer":"したがって、主としてプール熱と言われる咽頭結膜熱の問題になってまいります。","id":"exchange-039"},{"speaker":"鶴副委員長","kind":"意見","question":"そのプール熱と称する咽頭結膜熱ですね。これは何が原因で起こるのか。その水質、そのプールの水に含まれる薬品が原因で消毒等をやりますね。薬品でそういう結膜熱になるのか、要するに疾病というか疾患、それが起こる原因は何なのかということなんですね。","respondent":"青山品川区保健センター所長","answer":"要するに塩素があるからとかというようなことで起こるわけではなく、病原体があって、それがプール水を介して感染していくというようなことがあって、それでここで遊泳を通じて感染のおそれのある感染症というものを禁じているところです。","id":"exchange-040"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"もう１点お伺いします。それで、そのプールでそういうふうな目の疾患を部分的であったとしても起きた場合に、当該施設の経営者の責任だとか、そういうことが求められるようなことはない。そういう仕組みにはまたなっていないということでしょうか。心配ないんだと。","respondent":"青山品川区保健センター所長","answer":"これは品川区のプールの管理に関する条例の中で、プールにおける公衆衛生および安全の確保に関し、次の各号に掲げる措置を講じなければならないというのが第５条にございまして、その中で、今までは伝染性疾患にかかっている者、その他を入場させないこととなっております。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"大変な実態でありながら、なぜ区の当初見込みの１２％という実態だったのか。今回の提案では、下のところに今回の共産党区議団の提案ということで書いてありますけれども、1)に関しては所得階層第２段階ということは区の現行の制度と全く一緒なんですが、2)の年間収入は１２０万円としました。活用できる資産を有しないものというところですけれども、これについて、今回の提案では５００万円にしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"伊藤委員","kind":"確認","question":"この件は、私ども自民党のほうにもたしか２月の末ぐらいにお話がありまして、それから何回かいろいろご説明をいただきました。それで何点かお伺いしたいんですが、一つはこういう条例を出す場合に、いわゆる理事者、区長とか助役等々との調整が必要になってくると思いますけれども、当然なさったと思いますが、その区側の説明はどうだったのかということをお聞かせをください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうふうなところで、予算の詳しいところも審査の中に入れるべきだというふうなことであれば、予算特別委員会の審査そのもののルールのところを変えていくというふうな手続が必要になるんじゃないかと思うんですが、ここのところでは条例そのものの審査ということでやるというふうなことのルールというふうになっていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私が聞きましたのは、区長に申し入れをして、どういうことだったでしょうか。その経過、結果をお知らせくださいということを聞いていますので、そのことを教えていただきたいのと、それから条例だけ審査ということですけれども、事前に私ども党のほうに、例えば共産党のほうから、こういう全体の予算はこうですよと、それから対象人数がこうですよと説明があったんでしたら話は別ですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"理事者との調整ということでは、理事者に対しては、こういうふうにこういう条例を提案をいたしますという、そういうことで、理事者のほうからそれは賛成だ、ぜひやってくれとか、反対だというふうな、そういうことで意思表示がされた、そういうふうなものではなくて、調整というか、そういうふうなことを出しますという、そういうふうな申し入れで行いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問","question":"私の質問の仕方が申しわけなかったんですけれども、その総額とか人数がわからない条例を今審査しろという話ですから、それはちょっと理解できないということを意見を述べします。数字だけ。そのほうが、むしろいろいろ条例案ではなくて、具体的な社会経済情勢の変化に十分に対応できると思っているんですけれども、そのことについていかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"規則を変えるというふうなところでは、議員の規則改正の提案権というふうなのはありませんので、議員の提案権というふうなところで条例にかえるということで、こういうふうに今回の条例提案になったものです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問","question":"それは話はわかりますけれども、内容は規則で対応できる話なんですよ。数字を変えるだけですから。であったら、共産党なりが区長あたり理事者と十分相談して変えれるでしょうという話なんです。だから、それをわざわざ条例ではなくて、理事者と共産党の話し合いの中で変えなかったんでしょうかということをお伺いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そのことについては、共産党がこういうふうな提案をしたから、理事者が、じゃあわかりました、即やりましょうということになるという問題ではなかったために、議員提案ということで今回の条例提案になったわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"伊藤委員","kind":"提案","question":"そうすると、今日の提案の趣旨としては、この条例を各会派の同意で可決をしていただいて、それをもって規則の改正を改めてお願いするという形なんですね。そういうふうにとらえましたけれども。もしそれが難しければ、はじめから一人でやったほうがいいのではないかという意見を最後に述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"須藤委員","kind":"質問","question":"理事者のほうにご質問させてもらいます。介護保険の意義というのは、どういう意義で介護保険制度が発足したんでしょうか。それから、この介護保険制度を運用するに当たって、国のほうから各保険者、いわゆる市区町村にいろいろな通達、こうしたほうがいいというようなお話があったと思うんですが、その辺についてお聞かせ願いたいと思います。","respondent":"早津高齢福祉課長","answer":"収入のみによって一律に判断をしないようにというのが２点目です。それから、３点目は減額した保険料の分については一般財源を投入しないように、保険制度の枠内で行うようにという３点です。","id":"exchange-052"},{"speaker":"須藤委員","kind":"質問","question":"今お話があったように、みんなで支えるということが基本になると思うんで、こういったような減額をしてくることによって、そうすると、下がった分はどこかにしわ寄せが行くんだろうというふうに、みんなで支えるというような考え方から行くと、どこかへしわ寄せが行くというふうに考えますけれども、理事者のほうはいかがでしょうか。","respondent":"早津高齢福祉課長","answer":"保険料をある層の方に減額をすれば、それは別な方のほうに上乗せされてくる、こういう構成です。","id":"exchange-053"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、先ほど国のほうから、いろいろ減額をしていく場合に一般財源からは出しにくいよというようなお話があります。後は運用で、規則のところでできるというふうに踏まえてあるのを、なぜあえてここで条例化してくるというふうな考え方を持ってきたんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"というのは、やっぱり本当に区民の中にはこの保険料負担が大変だというのが本当にいろんなところから声が聞かれていまして、しかもこの第２段階というのは、住民税すべて世帯全員が非課税という、そういう方ですから、それでなおかつ収入も預貯金もというふうなところで、大変な生活を余儀なくされているという、そういうふうな方に対して、やはり減額の対象を広げたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"須藤委員","kind":"質問","question":"我々も人生５０年という話ではなくて、人生８０年時代というような形になってきたら、区民、市民もいわゆる自分のライフ生活というのを８０年という形で置いて、生活設計をつくっていくというのがここずっと言われてきている中での介護保険制度になっていると思うんですよね。ですから、そういった意味から言って、ある程度のどうしようもないというところは、昨年規則のところで対応してもらった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"鶴副委員長","kind":"提案","question":"１,０００人見込んでいたのか、１,２００名なのか。こういうことですけれども、なぜ、どういう理由でその１４４名にとどまったというふうに詳細には分析されているわけですか。どういう条件が厳しかったからですか。この点をお聞かせください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それと、あとは３００万円という預貯金というふうなところも、さっきも言いましたように、高齢者というと病気をたくさん抱えて、いつどうなるかわからないという不安をたくさん持っているわけですけれども、その中で医療保険が次から次へとこういうふうに負担が増えて、なおかつ今度の改悪でさらに増えるというふうなところでは、負担がかかるというのは本当にみんなが大きな不安として持っているために。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"鶴副委員長","kind":"質問","question":"私がお尋ねしたのは、どうして、１４４名に終わったことについて、条件が厳しいからというふうにおっしゃったけれども、そういう条件が厳しいのはどことどこがどう厳しくてということを分析されているんですかと聞いたのですよ。だから拡大できないかというふうに思われたんでしょう。それは不都合なことなのかどうか。現実に合わないことなのかどうかを含めて、ちょっと説明していただけませんか。","respondent":"早津高齢福祉課長","answer":"当初、収入基準というのは、収入については捕捉できますけれども、貯蓄のたぐいについては、区はもちろんだれにもわからないことですので、そちらのほうが一体どのくらいの、３００万円という一定私どもとしては余裕のある数字というふうに考えてありますけれども。","id":"exchange-059"},{"speaker":"鶴副委員長","kind":"質問","question":"先般、本会議の説明によりますと、ある８０歳の高齢者の例をとって、ご説明がありました。ところで、低所得者というのはどういうことを言うんでしょうか。あるいは要保護者、生活保護でいうところの要保護者とか、通常一般に言うところの低所得者というのはどういうことを言うのか。説明していただけませんか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"低所得者というのは、それぞれのところでの基準というふうなのはさまざま掲げているところが違うんですが、例えば品川区の訪問介護の３％に負担を軽減している方はありますけれども、それはもともと介護保険制度が始まる前までは無料で受けていた方が、介護保険が始まってからも３％で受けられるというふうな、そういうふうな制度に品川区が拡大してやっていますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"鶴副委員長","kind":"質問","question":"もっと正確に言いますと、現行の介護保険制度の中におきましても、低所得者に対するいわゆる負担能力の弱いというか、低い方々に必要な配慮というのは行っているわけですね。したがって、現行で言うですね、介護保険制度で言う原則的なその低所得者というのは、どこのところを指してそういうふうに言っているのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今回の提案についての低所得者という考え方は生活保護基準です。これをベースにして考えたのが、今回の基準です。それまでの区の提案というのは、それ以下に、それに達していないという状況だったので、生活保護基準まで引き上げるということで考えたのが今回の提案の中身です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"鶴副委員長","kind":"質問","question":"その介護保険制度で言うところのこの低所得者という定義というのは、要するに市町村民税の非課税世帯のことを原則として低所得者というふうに位置づけているというふうに私は思っておるんですが、どうですか。理事者に聞きます。","respondent":"早津高齢福祉課長","answer":"第１段階が生活保護世帯および老齢基礎年金受給者、第２段階が世帯全員が住民税非課税というような形での５段階が出ておりまして、それはおのずと収入の差が反映された制度です。","id":"exchange-064"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、減額とか減免というのはですね、必要な人には講じなければならない措置ではありますけれども、やはり根拠が大事だというふうに思うんですね。生活保護法で言うところの要保護者ですね。これはどういう概念ですか。生活保護法に基づいてお話ししていただけませんか。","respondent":"黒田生活福祉課長","answer":"ですから、収入が少なくても預貯金がある方は要保護にはなりません。","id":"exchange-065"},{"speaker":"鶴副委員長","kind":"提案","question":"何で公的な、もしあなたたちの友人だったら、ああ、高齢者の住宅に住んだらと、８０歳を超えているわけだから、あるいは都営住宅なら都営住宅に申し込んだらどうなのという、本当だったら、生活がそんなに苦しいんだったら、ポケットマネーを出してあげられないわけだから、そういうアドバイスだってできるではないのかなというふうに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが東京都の試算でも２１５万円もするわけですから、そして、私も今相談を受けていますけれども、入院したら差額ベッド、もう本当に１日１万８,０００円、これだと差額ベッド代だけで５４万円になるんですね。もうこれが当たり前。そういうふうなところの現実からすれば、やっぱり貯金せざるを得ないという、そういうふうな状況になっているので、こういうふうに５００万というふうなことで考えました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、貯蓄となると、同じ調査によりますと、高齢者世帯の３７％が３００万以上貯蓄をしている。母子世帯では７３％が１００万以上の貯蓄をしているというふうに基礎調査ではあらわれてありますが、貯蓄はいざというときに大切なことですから、それはいろんな工夫をして、あなた方がおっしゃったように、食うもの食わずに切り詰めてという人もいるかもしれません。高齢者を含めて。","respondent":"黒田生活福祉課長","answer":"今年度につきましては、大人の方が１７万９,０００円というのが葬祭扶助です。そのほかにプラスされるものは１万円ちょっとありますけれども、通常１７万９,０００円というのが基準です。","id":"exchange-068"},{"speaker":"鶴副委員長","kind":"提案","question":"例えば提案の説明によりますと、療養病床を２年すると月２０万前後かかる。それで、本会議でも日々の生活を切り詰めて貯金をせざるを得ない状況を聞きますというふうなことで、提案理由の説明の中に挿入をされておりました。今の説明でも２０万。この月２０万というのは、普通差額ベッドを除いて、普通の今のですね、医療制度の仕組みから見ますと、本人負担というのはどういう状況ですか。","respondent":"黒田生活福祉課長","answer":"先ほど私漏らしましたが、収入につきましては、貯金は生活保護を受けているときに、申請の段階で１０万円を割った段階で、生活保護の対象にしています。","id":"exchange-069"},{"speaker":"鶴副委員長","kind":"提案","question":"特に今度は所得の低い人ということで、老齢福祉年金の受給者等につきましては１万５,０００円。一般は３万７,２００円ですか、ほかにもいろいろな援護措置がありますよね。いきなり月平均２０万もあるかって、えー、そんなかなともうびっくりするじゃないですか、その数字だけ聞くと。ね。区の斎場を利用したら６万じゃないですか。区民斎場、平塚橋会館を利用したらもっと安いですか。どうですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"予算に関して一緒に審議をしたいということであれば、やはりルールそのものをちょっと検討していただいたほうがいいんじゃないかなというふうに思うんですが、予算の考え方としては先ほども申しましたし、予算の総額は、そこの本会議のところで申しましたけれども、予算の総額、これは対象者は先ほども言いましたように７,７５２人に、これは収入ベースだけで考えたものですから、その点で言えば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"鶴副委員長","kind":"質問","question":"それを減額して充てればいいじゃないか。わずか８２５円じゃないのと言うかもしれないけれども、その不公平というのは、ほかの人は保険料を納めている人、それを何かいろいろなことで基金に積み立てている、次の施策を充実させるために、今までの説明によると、そうだ。ほかの人の理解を得ることができるのかどうかということはどういうふうにお考えですか。それぞれの区分によって納めている人がいますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところを踏まえてやっていますので、そのことについては、ぜひ取り消しをしていただきたいと思います。それに対して１４４名という、こういう実数の数字ですから、品川区のもともとの考え方、基本的にはこの考え方でいっているということです。それで、基金の額もかなりの基金が積み立てられているという状況ですから、考え方としては品川区のこの考え方と全く同じです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"鶴副委員長","kind":"質問","question":"全く同じですか。共産党の考え方も区の考え方と全く同じだというふうにおっしゃっていたけれども、全く同じですか。","respondent":"早津高齢福祉課長","answer":"基準の考え方にしましても違っておりますし、私どもは、減額したものは保険料の中で。基金を取り崩すということではございません。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この６５歳以上の方の保険料の徴収というふうなのがされているわけですけれども、それはこちらのほう、区が提案されたその予算に対して修正をするという考え方なので減額というふうな形になりますけれども、品川区が区はそういうふうな予算の提案権があって提案をするわけですから、そこのところでは区が当初から見込むというふうな形で今回は予算化されていますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"鶴副委員長","kind":"提案","question":"よく理解できないんですよ。同じだとおっしゃっているんですけれども、そうは思えないんですが、もっと提案者にわかるように説明していただけませんか。","respondent":"早津高齢福祉課長","answer":"区の予算では、保険料をこの措置を行うことで保険料の減が見込まれる。しかしながら、それは歳入として確保した上で、歳出のほうも必要な歳出が確保できる、こういう考え方です。基金のほうを取り崩してという措置を講じているわけではございません。","id":"exchange-076"},{"speaker":"鶴副委員長","kind":"質問","question":"違うということはわかりました。それで、５００万の資産を仮に持っている人を、それは低所得者と言うでしょうか。共産党というのは、あーすごいなと、そういう生活実感なのかというふうに思ったりするんですが、５００万の資産があって、そういう人たちまで本当に税金でもそうですけれども、あるいは保険料でその中から補い合って助けていかなければならない状況なのかとなると、いかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"５００万というふうなところについては、先ほどからなぜ５００万にしたのかというところで話をさせていただいているとおり、やっぱり社会保障が次から次へと負担が増やされるという中で、本当に負担が増大している、そして、その５００万というその金額も、これだけあればもう十分という、そういうふうな状況ではないという、そういう状況になっていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"鶴副委員長","kind":"質問","question":"よくのみ込めないんですが、私なんかはやっぱり貧しい生活をずっとやってきたせいか、なかなか理解できない部分があるんですが、今低所得者の新たな生活支援システムをどうあるべきかということについて、鋭意、厚生労働省がプロジェクトをおやりになっていることはご存じですね。はいとおっしゃいましたので、どういうふうな検討をしているんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"船波委員","kind":"質問","question":"ですから、保険料がこれだけ減って大丈夫だと区が思った部分にはまだ余裕があるわけですけれども、その余裕の部分で、もう少し軽減の恩恵を受けられる人を増やそうだとか、そういうふうには考えなかったのか、その余裕の部分に関してはどうしようというようなスタンスというか、方針はあるんでしょうか。","respondent":"早津高齢福祉課長","answer":"数字がいろいろ出ておりますが、私どもとしては、まず１,０００人ぐらいの見込みというようなお話をさせていただきました。","id":"exchange-080"},{"speaker":"船波委員","kind":"質問","question":"品川区がその負担軽減の措置をやってあげようという対象としては、この保険料軽減措置の条件である年収だとか預貯金、土地その他の不動産の所有とか、そういったことがある一定のレベルであると判断したということですけれども、そのレベルに関しては、では、それはもう決まってしまったもので、今後検討というか、変化する余地というか可能性はどうなんでしょうか。","respondent":"早津高齢福祉課長","answer":"現在のところ特段考えてはございませんが、例えば収入の基準について、９６万円というのは、生活保護基準の１類、２類というものを参考にしていますので、そちらが改定されたとすれば、それは検討のきっかけにはなるだろうなというようなことは考えてあります。","id":"exchange-081"},{"speaker":"船波委員","kind":"確認","question":"わかりました。その低所得者の方の負担を軽減するための措置としては、いろいろ説明を伺って理解しましたけれども、今後その介護保険をまた見直すという時期には保険料をどうするかというのも一つの検討事項としてあるわけですよね。その辺をちょっと確認だけ。","respondent":"早津高齢福祉課長","answer":"保険料の改定時期には、議論の可能性としては、もちろんその場というのはあります。","id":"exchange-082"},{"speaker":"嶋委員","kind":"質問","question":"年間２０４万の収入があって、プラス５００万の資産があるということは、普通考えて、裕福とは、もちろん収入からすると、５００万の預貯金があるということは、ある程度低所得者というと、普通一般庶民感覚では、ちょっと私たちは考えられないんですが、そこら辺は、皆さんはどういうふうに考えられたんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"２０４万というのは、給与収入でも年金収入でも非課税となる、そういう収入のベースになっています。この家賃分というのは最高で７万円までということで、実額ということで考えていますので、生活レベルとしては１カ月１０万円というレベルで、家賃を除くと生活の部分では１０万円というふうなことなので、やはり低所得者というふうに考えました。家賃があるなしで大きく支出額が変わるというところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"嶋委員","kind":"意見","question":"月額１７万円で家賃７万円と言ったら、相当いい生活をできる状況がある。もちろん裕福ではないかもしれないけれども、普通一生懸命皆さん生活保護を受けないで頑張っている方は、この中で十分やっていますので、ちょっと私は何回も申しわけないんですが、庶民感覚ではないです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"鶴副委員長","kind":"意見","question":"さっき聞き漏らしちゃったんですけれども、共産党というのは温かい心の持ち主なんだなと、月７万まで家賃を認める。生活保護法で言うところの家賃扶助の最高基準というのは幾らでしたっけ、生活保護基準に準じてとおっしゃっているから。","respondent":"黒田生活福祉課長","answer":"今年度につきましては、１人世帯ですと東京ですと５万３,７００円、２人以上ですと６万３,８００円です。","id":"exchange-086"},{"speaker":"鶴副委員長","kind":"質問","question":"他の制度から見ましても、これは非常に不公平であるという感は否めない。こういうことを認めるといろいろなところに矛盾が出てきますね。このことについてはどういうふうにお考えでしょうか。鈴木委員。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、かなり今住宅事情が品川区は大変ですから、全国ベースから比べてもかなり家賃というのが高いというのが実情としてあると思いますので、最高で７万円まで、実際に入っている家賃ということで、入っているその家賃で計算されるわけですから、７万円まですべての人に見るというものではありませんから、実額ということで７万円というのは最高ということで考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"鶴副委員長","kind":"意見","question":"なるほど、そういうところで準拠されたのかなというふうに思いますが、理事者に聞きたいんですけれども、例えばどうしても生活が困窮して保険料が払えないという人については相談に乗る、そういう機会というのはあるわけでしょう。条例が。条例で細かく規定しなくても。","respondent":"早津高齢福祉課長","answer":"お支払いの方法等についてのご相談等は応じます。現に第２段階に属している方であれば、区の条例の適用のための手続等のご紹介をしたりとかというようなことはやってあります。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけですけれども、先ほど鈴木委員から対象者の数字が７,７５２名と出ました。この方々の資産調査はしていないですよね、その確認だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"資産調査というか、これはその予算を、この対象者をどうやって出してきたかということではなくてですか。一人一人の資産調査というのはもちろんできませんから、そういうふうなことはもちろん７,７５２人の資産調査はしていません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270319?Template=document&Id=3010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":53252,"voices":180}},{"id":"h14-20020304-8","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"建設委員会","time":"午前１０時０８分～午後３時０２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"会社更生法の中身というのは、あまりよくわからないんですけれども、１件、１件了解が得られたらというその話の中身というのは、例えば下請けが入っていますよね、それで仕事をしてもくれないとなるかもしれませんと、そういうのをある程度さばいて、管財人が入って仕組みができたらということなんですか。そこのところをもう少し詳しく。","respondent":"北村下水道河川課長","answer":"口頭で聞いていますのは、個別のそれぞれの現場とかいろいろなものを調書という格好で報告して、そこで管財人のほうで審査して、では、この現場は始めていいですよということになれば再開できるというようなことだと聞いています。","id":"exchange-001"}]},{"id":"topic-02","title":"の１、議案審査に移らせていただきます。 (1)、第２７号議案、品川区みどりの条例の一部を改正する条例","agenda":"の１、議案審査に移らせていただきます。 (1)、第２７号議案、品川区みどりの条例の一部を改正する条例","exchanges":[{"speaker":"上山委員","kind":"質問","question":"最初に、こういう形で屋上緑化をやろうということで、区が推進することだと思うんですが、全体的なこの計画の目標というんですか、どういうふうにしたいとか、そういうような考え方の基本みたいなものがあれば、この２点をお尋ねしたいんですが、いかがでしょうか。","respondent":"松代道路公園課長","answer":"２点目の目標ですが、これは非常に難しいところでございまして、先ほど言いましたように、平成６年にみどりの条例というものをつくりまして、接道部緑化等を進めてまいりました。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問","question":"屋上で使っていない部分が、区面積の３％、２,０００haで、これはここに書いてある話ですけど、緑化すれば、２０年近く前の水準に戻せると。今後、ヒートアイランドとかいろいろ言われていまして、集中豪雨もそういうのに影響されているんじゃないかと言われている中ですから、いろいろな意味でも、効果が期待できるんじゃないかと思っています。ちょっと教えてください。","respondent":"田平建築課長","answer":"ただし、地域地区だとか、敷地面積などいろいろな制約があるので、モデルで考えておりますのが、敷地１,２００m2、商業地域で、そこの指定容積率が４００％、日影規制なしという地域地区で考えた場合、市街地住宅総合設計制度というのがありますけれども。","id":"exchange-003"},{"speaker":"上山委員","kind":"質問・要望","question":"最後に要望なんですけれども、今度、初めての屋上緑化に対する助成ということで、屋上等緑化助成要綱の制定とありますけれども、助成額は整備に要した額の２分の１で、１件当たり３０万円で、年間１０件ということで、計算すると３００万円ぐらいだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"屋上緑化ということで、非常に賛成です。特に公共施設の総合庁舎、中小企業センターなどで、一般の人にＰＲも努めてもらいたいという意見も、私は言ったんですけれども、その場合の安全上の問題とか、屋上ゆえにやっぱり風が強いということで、高木だと倒れちゃうとか、砂が飛ぶとか、そういういろいろな条件も、ある意味で悪いところがあると思うんです。その辺の研究といいますか、教えてください。","respondent":"松代道路公園課長","answer":"ただ、いかんせん予算が限られておりますので、非常にその辺が厳しいと思うんですが、その範囲の中で、できる限り参考にしていただけるようなものをつくっていきたいと考えているところです。","id":"exchange-005"},{"speaker":"沢田委員","kind":"提案","question":"今のに関連するんですけれども、どういう植物を植栽するか。屋上というのは過酷な環境ですよね。それからもう一つ、今ちょっと上山委員のほうからあったんですけど、実態的に効果というのはどれぐらいあるのか。私も提案したし、各党が屋上緑化と言って生まれた産物で、それは大歓迎するんですけど、実際にはどの程度の効果があるのか、何かデータみたいなものがあったら教えてもらえないですか。","respondent":"松代道路公園課長","answer":"それとやはり、高木といいますのは、非常に加重もかかりますし、風の影響を受けますので、その辺のところが非常に難しいと思うんですが、その場合は、施工上でどうなのか。中木程度でどういったものが適しているのか。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"助成制度で、１件当たりの上限が３０万円ということが出ているんですけれども、対象としては、マンションだとか、会社のビルだとかを問わず、それから規模も問わずということなのか、もう少し詳しく説明してもらえればと思います。それと、３０万円固定というのが、小さなビルでも、大きなビル、マンションでもとなるとどうなのかなというのがあるんで、そこら辺をもう少し教えてもらえますか。","respondent":"松代道路公園課長","answer":"当然、３０万円に満たない部分も、ある場合は十数件になろうかと思いますし、どのぐらいの申請で、どのぐらいの内容で来るのかまだつかめません。今後は、そういったものをよく見極めながら対応してまいりたいと考えているところです。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"まあ、走り出しながらきちんとしたものにということで、よく理解できます。先ほど言った、区が率先してやろうというのは、これは非常に大事だと思うんですが、同時に、例えば再開発で建った建物だとか、あるいは研究機関だとか、私立学校みたいな、公立と民間との中間あたりにあるものなんかについても、区が率先してやると同時に、ご指導をいただきたいと思うんですけれども、そこら辺はいかがでしょうか。","respondent":"松代道路公園課長","answer":"加えて、そこの屋上にもぜひお願いしたいということは当然なことでして、指導できる立場、もしくはお願いする立場でやっていきたい。幼稚園も含めて、そういう機会等がありますれば、準じて、ぜひお願いをしていきたいと考えているところです。","id":"exchange-008"},{"speaker":"本間委員","kind":"質問","question":"実際に、かなり大規模な建物に対する助成だと思います。建築物の屋上、壁面、ベランダという部分で、屋上に関して言えば、例えば普通の芝と人工芝がありますが、私ども、屋上で人工芝の部分は、現在も大きな規模の会社の屋上によく見ることができ、そこで何かやったりしているのを見るわけですけれども、人工芝はどうなのかということ。すみませんが、現段階で、一つ、二つ具体的な例を教えてください。","respondent":"松代道路公園課長","answer":"そういったイメージで、私どもは考えておりますし、相談にみえた方には、ぜひ、そういった今あるものをご提案したいと考えているところです。","id":"exchange-009"},{"speaker":"本間委員","kind":"質問","question":"実は、私がかつてお世話になっていた建物は４階建てなんですけど、やっぱり屋上にそんなような草花が置いてあったんです。先ほど、維持管理がどうのと言いましたが、時代の進歩と共に新しい技術が出てきているんだろうと思います。しょっちゅうそういうことがありますものですから、維持管理にお金がかっているということですが、この辺の限界については、どういうふうにお考えでしょうか。","respondent":"松代道路公園課長","answer":"それをあえて屋上にというわけですから、これはもう環境面でも非常に厳しいものがございまして、かつ、手間がかかるようなことになりますと、ずっと継続した緑の状態が保てないということがありますので、なるべく手をかけない状態で。","id":"exchange-010"},{"speaker":"辻委員","kind":"質問・要望","question":"私、ちょっと確認させていただきたいんですが、改正（案）の中で、先ほど、課長から説明をいただいたいんですが、改正（案）の括弧の中で、新たに１,０００m2以上のものは、それをつくる際に義務づけが始まったと考えていいんですか。この規則でやるときに、１,０００m2以上を超えた場合の２０％ということですか。ちょっとその辺を含めて、教えてください。","respondent":"松代道路公園課長、田平建築課長","answer":"先ほど申しましたように、そういったものすべての内容を精査しまして、屋上がある、なし、屋上設置が可能、なしといったことで、屋上緑化をした場合はどの程度というものをある程度想定しまして。確認申請の前の手続きですが、この緑の条例を遵守するための実行性ですけれども、私としては、確認申請を受け付ける前段で、緑のセクションに設計事務所が出すわけですけれども、具体的には指導を受けてくると。","id":"exchange-011"},{"speaker":"辻委員","kind":"確認","question":"ところが、屋上緑化になってくると、それはちょっと意味が違うんですね。この部分というのは生き物ですから、さまざまにやらなきゃいけない。普通のビルとか区役所では、屋上に上がって人が出入りできるというのは、限られた鍵で、安全確認というのをやっていると思うんです。４月２９日あたりに広場でやるんじゃないですか、植木を。その辺、どう今後やられるように考えているんですか。","respondent":"松代道路公園課長","answer":"当然、受ける方については温度差がありますから、そこには、なるべく費用をかけたくないんだという方もいらっしゃると思います。そういった方にも対応できるようなものを、先ほど言いましたような形で提案をしていければと思っています。","id":"exchange-012"},{"speaker":"辻委員","kind":"質問","question":"そういったときに、２割をどう確保するかといったら、私道部とか、壁面とかという形で確保していく必要が絶対にあると思うんです。そういう中で、なおかつヒートアイランドをどうするかということになると、屋上緑化したそばに室外機をつけて、ばんばん熱風を外に出しているんじゃ、何のことかということになると思うんです。最後に、要綱等ができましたら、またぜひ、教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"横山副委員長","kind":"質問・要望","question":"さっき壁面だとか、地上の飛ばしというような話がありましたが、私は、多分そっちのほうがたくさんいくと思うんですけど、これでいくと、とがった建物というのはすごく制約を受けますよね、デザイン的に屋上がないわけですからね。そうすると、それはやっぱり壁面で求めるのかと思ったら、地上面でというようなお話があったから、それはそれでいいんですけど。幾つかの質問にちょっとお願いします。","respondent":"松代道路公園課長","answer":"小学校、中学校等については、まだ具体的には進めませんが、まず第一に、できれば１０月１日の施行の前に、総合庁舎の屋上を少しでも早くごらんいただけるように取りかかってみたいと思っています。","id":"exchange-014"}]},{"id":"topic-03","title":"議案審査(2)、第２８号議案、品川区手数料条例の一部を改正する条例","agenda":"議案審査(2)、第２８号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"それと、４番なんですが、ちょっと高いかなという気がするんですけど。新しく取るわけですよね。実際には、宅地開発の際に、真ん中を通して道路にするということなんですが、さっきのあれじゃないんですけれども、平成１２年度でどれぐらい件数があったのか。","respondent":"田平建築課長","answer":"４番についてですか。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"４番について、適用件数というんですか、実態がどれぐらいなのか教えてもらいたい。","respondent":"田平建築課長","answer":"実は、４番の建ぺい率の許可制度は、法律は確かに改正されておるんですけれども、先ほど、若干説明申しましたが、壁面線の指定をしたり、条件があります。ですから、法律が施行されてから約１年ぐらいしか経ってないんですけれども、実態として、件数は１件もございません。","id":"exchange-016"},{"speaker":"上山委員","kind":"質問・要望","question":"それは何らかの形でやらなきゃいけないと思うんですけれども、何か啓発も含めて、こういう周知もやると言っておられますけれども、その辺もあわせて、よくやってもらいたいというのが１点で、これは要望です。ほかにもしあるのかどうか、ちょっと確認したかったんで、そこら辺をちょっとお願いします。","respondent":"中村交通安全担当課長","answer":"今回、天王洲のほうも、一応、臨海線のご協力をいただいて設置される。これは、今後、管理は区のほうになる予定になっていますけれども、そういう意味では、鉄道事業者にご協力をいただいているということです。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"例えば、国立予防衛生研究所のあたりに公団なんかが建っていますよね。あそこには、駐輪場の計画がなかったんですか。あったら、教えてください。","respondent":"中村交通安全担当課長","answer":"現在の段階で、具体的にそちらのほうに駐輪場について整備するという予定はございませんけれども、それぞれ住宅だとか、そういうものができましたら、それぞれお願いするという形で進めていきたいと思います。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"要望だけ。要するに長者丸のほうなんですよね。上大崎二丁目のほうから来た人が、駅を超えてこちら側に来て、また駅に戻るというのはなかなか困難なことだと思うんです。これはもちろん前進だからわかるんですけど、何かの機会に、小規模でもいいから、こちら側にもつくることをぜひ検討していただきたいということだけ、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"辻委員","kind":"質問","question":"今回、東急とＪＲがやっていただくということで、前々から周辺に駐輪場の場所がなかったということで。先行きまた、今、沢田委員が言ったように、目黒のほうの関係から言えば、補助１８号線のほうにも、ちょっとバス停があるＪＲ脇をですね、利用したらいいんじゃないかと、我々も考えているんです。ここの放置自転車の整理というのは、今までどういう形でやられているんですか。","respondent":"中村交通安全担当課長","answer":"今回、緊急雇傭対策のほうの事業に入れていただいておりますので、その中でこらちのほうについても進めて、駅周辺にとめられないようにということで実施する予定になっております。","id":"exchange-020"},{"speaker":"辻委員","kind":"質問","question":"今度、東急の撤去自転車を置く場所というのは、それはどんな地点になるんですか。東急の高架下か何か使って。","respondent":"中島街路事業担当課長","answer":"その時点で、山手通り沿いの高架下について一定の整備の計画をしていますので、その中に駐輪場を設置するということで要望していまして、放置自転車については、その奥に一時保管所の設置を予定をしているです。","id":"exchange-021"},{"speaker":"辻委員","kind":"確認","question":"禁止区域でやっているのは、そういう動きだというのはわかるわけです。そこらに放置している自転車を東急のほうに持って行って、放り込むわけにはいかないし、いきなり八潮に持っていくか、あるいは東急の不動前のところに持って行くかということしかないということになれば、東急の新しくできたところの利用価値というのも、改めて確認するような方向でできないものだろうかということです。","respondent":"中谷まちづくり事業部長","answer":"今後計画する駐輪場の中に、保管所機能を持てないだろうかというご指摘だと思うんですが、私どもも、そういうことも検討いたしました。というのは、今回、東急とＪＲに７３０台を設置していただいて、開設するまでの交渉が非常に難航いたしました。","id":"exchange-022"},{"speaker":"築舘委員","kind":"質問","question":"だけれども、その場合に、禁止区域とか、警告のビラとか、撤去とか、これは目黒区と協力体制なんですか。費用の面とか、いろいろどういうふうになっているんですか。","respondent":"中村交通安全担当課長","answer":"撤去等についても、目黒区内のものについては目黒区のほうで実施していただく、品川区内については、私どものほうで実施するというような予定になっております。","id":"exchange-023"},{"speaker":"築舘委員","kind":"意見","question":"わかりましたけれども、そうすると、撤去するということになりますと、それぞれいろいろあると思うんですね。今は、放置自転車というのが７５０台ぐらいで、昔、聞いたことがあるんですけれども、もう要らないということで放置した自転車が意外と多いんじゃないかと思うんですね。通学、通勤、買い物とかで、そのまま乗っていくという割合の調査というのは、目黒駅ではわかりますか。","respondent":"中村交通安全担当課長","answer":"今のご質問の、それぞれの割合の調査といいますか、こちらについては実施してはございません。ただ、あの駅に置かれている台数等からすれば、かなり通勤、通学等に使われている自転車が多いんじゃないかと考えています。","id":"exchange-024"},{"speaker":"築舘委員","kind":"質問・要望","question":"そういう意味では、放置禁止区域を指定して、警告、予防のためにお知らせをすることは徹底していただきたいということはあると思うんです。こういう場合に、禁止区域に置かないで、ちょっと禁止区域じゃないところに置いちゃうというようなケースがやっぱり出てくるんですか。結果的に、正直者はばかを見るというようなことがあるかどうか、その実態を聞かせていただきたい。","respondent":"中村交通安全担当課長","answer":"当区の場合は、撤去がいつという公表はしていませんので、いつあるかわからないということで、場合によれば、昨年の大井町駅、大崎駅あたりは、新しく駐輪場を開場したときには、前日、撤去を実施したということもやりましたので、その辺のところで。","id":"exchange-025"},{"speaker":"上山委員","kind":"質問","question":"全体とすれば、自転車はやっぱり環境に優しい乗り物だと思いますし、使い勝手もいいものだと思いますし、健康にもいいと言われていますけれども、そういう意味から、鉄道事業者への要請というのはされているんですか。そこら辺はどんな感じなのか、ちょっと教えていただければありがたいんですが、最後にすみません。","respondent":"中村交通安全担当課長","answer":"放置自転車法の中では、鉄道事業者の責務というのは、行政のほうから、駐輪場の設置の協力が求められた場合に、場所の提供だとか、そういうことで協力してくださいというような形になっていますので。","id":"exchange-026"},{"speaker":"沢田委員","kind":"意見","question":"もう一度、全体計画と、現在の進捗状況はどうなのかということをお尋ねしたい。それから、前に聞いたかと思うんですが、忘れちゃったんで申しわけないんですが、これはなぜ下流部のほうからつくっていかなかったのか。できたところから流し込むとか、あまりにも工事期間が長いんじゃないかと、いろいろ意見が出ているんですけど、ちょっとそこら辺を説明していただけますか。","respondent":"北村下水道河川課長","answer":"そういう中で、基本的には、１年ないしは２年かかるかというような期間でもありますので、あえてここで無理に暫定貯留をかけて、また余分な工事費を投入するよりも、全体の竣工を急いだほうが得策ではないかということで、今のところ、この工事に関しては。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"今、聞き落としたのかもしれませんが、最終的に供用開始は何年ですか。","respondent":"北村下水道河川課長","answer":"平成１６年度完成予定ですので、平成１７年夏から使えるかと思います。","id":"exchange-028"},{"speaker":"辻委員","kind":"質問","question":"基本的に、３ページの断面図で見ると、かむろ坂のほうで雨水がためられて、水をカットして流すんですが、目黒川の水位との落差というんですか、この辺の流れから言っちゃうと、水位がすべて出せればいいんだけど、ほとんどとまっているときと、目黒川のためにためておくような、一時的な放流を待つという感じですか。その辺の考えというのはどうなんですか。","respondent":"北村下水道河川課長","answer":"ですから、目黒川の水位が上がってしまうと流せないということではありません。","id":"exchange-029"},{"speaker":"辻委員","kind":"意見","question":"そういうことで、技術的には。五反田の橋のところを通るんですが、低地部で一番大変だというのは、実は、もう少し上のほうですね。ＮＴＴのほうとか、今の谷山橋ですよね。その辺の水というのは、上からカットされるからということもあるわけですけれども、それは今後の課題としてお願いしたいということです。ちょっと、水圧を何とかということを。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"先ほど説明されたけど、この中で、環状７号線の外側は低中層で、内側は中高層で、センター・コア再生ゾーン、環状６号線の内側は高層住宅だと。そうすると、環状７号線は中高層で、品川区の大半のところで高層住宅になる。そういうものはいかがかということと。まだ基本方針だから、そこまではフレームはつくってないかもしれないんですけれども、そこらがもし示されていたら、教えてもらえますか。","respondent":"伊佐都市計画課長","answer":"ただ、この考え方の中に、レジュメの１章の(2)の中の３点目で、的確かつ厳格な規制を実施する一方で、活力も図っていきたいということで、全部、例えば用途地域の指定を一斉に上げていくという考え方に立っているものではございません。","id":"exchange-031"},{"speaker":"沢田委員","kind":"意見","question":"だから、これだけというんじゃなくて、２０１５年までにどういう東京をつくるのかという全体像が示された中で、用途地域をどうするかということ。ただ、この問題だけで言えば、それはわかりますけど。だけど、環状７号線の内側に、品川区では密集住宅や低層で危険なところがある。この間も言ったんで、ちょっと意見だけ述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"上山委員","kind":"質問・要望","question":"私も、これを見てわからないところを教えていただきたいんですが、今度、資料をいただきましたけれども、きょうの報告などでも、沢田委員も触れたんですけれども、土地利用の云々とありますけど、品川区の位置関係は大体センター・コア再生ゾーンのようなところに当たる、全部じゃないと思うんですけど、そういうような気がするんです。ちょっとよくわからないけれども。","respondent":"伊佐都市計画課長","answer":"前回、ご説明いたしましたが、品川区の三つのゾーンの考え方ですが、まずセンター・コア再生ゾーンは、先ほど申しましたように、中央環状線の内側という位置づけですので、品川区で言えば、環状６号線の内側という感じで計画素案が出ていますので、環状６号線の内側が。","id":"exchange-033"},{"speaker":"上山委員","kind":"意見","question":"私が言っているのは、全体をどうするのかは別ですよ、ただ、一部そういうこともやりながら、片方でどんどんってどこまでかわかりませんけれども、センター・コア再生ゾーンのような形で、高層ビルなどがどんどん増えるとなると、せっかくやろうとしているのに悪いんですが、齟齬というか、自己矛盾みたいな感じもしなくはないんです。ちょっと意見だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"辻委員","kind":"意見","question":"３ページ目の「安全で健康に暮らせる生活環境の形成」ということで、新防火地域という考え方が示されたんですけれども、防火と準防火の間ということでしたが、なぜこういう考え方が出てきたのか。その辺の効果だけど。要するに、木造住宅密集地域というのは、今、さまざまなことをやっていますが、なかなか難しい部分がある。その辺の考え方は。","respondent":"伊佐都市計画課長","answer":"今回、新防火地域というのは、これは土地利用答申の前の都市づくりビジョンの中でも出されている考え方なんですが、ご指摘のとおり、今の防火地域と準防火地域のちょうど間ぐらいの位置づけの制度を、都として新しくつくるべきと提案をしているものです。","id":"exchange-035"},{"speaker":"辻委員","kind":"質問","question":"全国どこに行っても、大なり小なり、木造密集地域というのはあるんでしょうけど、特に人口が集中しているいわゆる都市部ですね。効果があるから、こういう答申が出てきたんでしょうから、実質、今、木造の建て替えができるんだったら、防火の面から見れば、鉄筋でかちんとしてやればいいけど。新しい建築技法から言えば、何かの方法もあるとか、その辺も含めて、考えが出ていると思うんです。","respondent":"田平建築課長","answer":"ですから、今回の用途地域の見直しにあわせて、これが法制化されるかどうかはわかりませんけれども、そうなった暁には、そういうことも一つの手法として、東京都の場合には検討していかなくちゃならないかなと思います。ただ、十分に建物は建てられると思うんですよね。","id":"exchange-036"},{"speaker":"辻委員","kind":"質問","question":"密集地域での事業というか、メンテナンスがあるじゃないですか。安全というか、そういう面で見れば、１戸ずつでも構わないわけですね。今回、こうやっているけど、抱えている内容は、同じことが言えて、品川区に落ちてきたときに、じゃあどうするかということが起こったときに、やっぱり法改正というか、あるいは規制とか、そういうものががちんと出てないと、同じことが起こるんじゃないかなと思います。","respondent":"伊佐都市計画課長","answer":"これまでの基本方針は、ほとんど用途地域の見直しのための方針であって、なかなかそういった実現可能性も踏まえた新しい制度の提案というのが出てきたのは今回初めてですので、注視していきたいと考えております。","id":"exchange-037"},{"speaker":"上山委員","kind":"質問","question":"今回、品川区に便利になったと思うんですが、予定の利用というんですか、こういう道路というのは、一般的にどのぐらい需要があるのか。あるいは、そういう裏付けが何かあってやられたと思うんですけれども、今回はどれぐらいの交通量を見込んでいるのか。もしその辺がちょっとあれば、教えていただけたらと思うんですが。","respondent":"伊佐都市計画課長","answer":"今回の臨海工事に環境アセスメントが行われてございまして、臨海トンネル部分での交通量は、１日２４時間で２万９,０００台です。","id":"exchange-038"},{"speaker":"築舘委員","kind":"質問","question":"開通式典につきましては、４月１０日と書いてあるんですけど、これは我々もあれですか。","respondent":"伊佐都市計画課長","answer":"大変失礼いたしました。４月１０日の開通式の招待状がまいってございまして、区から、区長、助役、正副議長、正副建設委員長を行かせていただきます。","id":"exchange-039"},{"speaker":"辻委員","kind":"質問","question":"以前は、沈埋トンネルのところで、一般道路がぷつんと切れているんですね。あの計画はまだ生きているんですか。要するに、湾岸道路は有料になっているわけですね。あそこまでは一般道路がずっとそこまで行って、ぷつんと切れてそれっきりになっている。それは、もうこっちができたからなしになるのか。やっぱりそれはそれとして、将来計画は持っているんでしょうか。だから、その辺がどうなのか。","respondent":"伊佐都市計画課長","answer":"国道３５７号線の一般道路としての通行につきましては、国土交通省で検討中です。東京都のほうからも、強く働きかけてありますし、これは大変重要な幹線であるとして、整備を進められているということで、検討中ですということです。","id":"exchange-040"},{"speaker":"横山副委員長","kind":"質問","question":"今まで、何かこういった分筆された土地があったわけじゃないんでしょ。これまでの経過なんだけれども、こういった特殊な買い方をされて今日まできているんだけれども、その情報は、私道に接道したいから売ってほしいということで品川区の希望なのか。それとも、向こうで、こうすると便利ですから庭先を買ってくださいときているのか。そこら辺のところを、ちょっと教えてください。","respondent":"浜脇住環境整備課長","answer":"先ほど、平成１２年度の部分について、本来ならば平成１３年度に整備すべきところだったんですが、平成１３年度の１２月にこれが買えたものですから、工事につきましては、７０m2の分と一緒に、来年度早々にやるように設計を開始したところです。","id":"exchange-041"},{"speaker":"横山副委員長","kind":"意見","question":"大体、経過はわかりました。端を買ったときに、この話がセットであったんでしょ。ここを買って、またそこに接道が欲しいからということじゃなくて、そういう理解をします。私道の右側がすごい密集地なんですね。そして、今言われるように、一緒の工事でやっていかれるということなんで、それも了解しておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"上山委員","kind":"質問","question":"今回、こういった街路整備うんぬんかんぬんでやる、これは当然いいかと思うんですが、ちょっとお尋ねなんですけど、利用する側は約３割割引きになるんですが、不動産業者側というんですか、これはいわば負担する形になるんですか。手数料が少なくなるということでよろしいんですか。","respondent":"浜脇住環境整備課長","answer":"この間、たまたま役員の方とお話をしたんですけど、今でもやっぱり、通常、一般の方が不動産屋に一歩入るのは、相当勇気が要るということだそうです。そういった中で、こういったシールを張って、安心ですよということでのメリットはありますと、協会のほうは考えてくれます。","id":"exchange-043"},{"speaker":"沢田委員","kind":"質問","question":"改正についてというよりも、今までずっと細街路の整備をやってきた実績なんですけれども、大体、延長でどれぐらいになって、それが品川区全体の細街路のどれぐらいを占めるのか、もしわかったら、教えてもらえますか。","respondent":"田平建築課長","answer":"区内の総延長は、まだこの１０倍ほどあります。まだこの先、今のペースでいきましても、１００年かかるという話になりますけれども、おかげさまで、まちの中を見ますと、相当セットバックした建物が目につくかなと思います。","id":"exchange-044"},{"speaker":"上山委員","kind":"確認","question":"前に説明を受けたかと思うんですけど、数字のことでもう一度お願いしたいんですが、今度、区営住宅としてつくるということで、住宅の戸数が４６戸で、うち障害者向け４戸ですが、この４６戸というのは、既存の三棟の戸数より増えているのかどうか、そこら辺を確認したかったのが１点です。そこら辺との関連。","respondent":"田村住宅課長","answer":"３点ほどのご質問なので、私のほうからお答えします。既存の住宅は、４２戸です。現実に、もう建替えの話があったときには、既に３７世帯になっていました。","id":"exchange-045"},{"speaker":"上山委員","kind":"質問・要望","question":"は要望にしたいと思うんですが、一つは、今回、こういう形で区への移管ということで、もとと比較しても、４戸ぐらい増える形になるかと思うんですが、今後、ほかにこういうような話があるのか、ないのか。あれば、教えていただきたいと思うのが一つ。特に最初のところで、もしあれば。","respondent":"田村住宅課長","answer":"建替時移管は２３区で初めての事業になるので、新たに追加で東京都のほうから住宅の移管というお話は、今のところ具体的にはございません。","id":"exchange-046"},{"speaker":"辻委員","kind":"質問","question":"３階に集会室があるから、４階の屋上、それから、２階飛ばして６階の屋上。要するに下の階がついてきますよね。公共の施設を２５０m2で見たときに、約１,０００m2近くあるわけですから、どれぐらいの。緑化条例の担当から見たときに、認定を受けるといったときに、どうだと。事業部なんかで、共通に検討していかないと、事業部でやった意味がないんじゃないかと思いますけど、いかがですか。","respondent":"田村住宅課長","answer":"ただ、屋上でも機械を置いたり、室外機を置いたり、どうしても置けない部分は当然除きますけど、建物の６階の屋上そのものは、太陽光熱を一応検討している最中なので、有効面積から除かれているということなので、かなりの率で、区で新条例なりには。","id":"exchange-047"},{"speaker":"辻委員","kind":"質問・要望","question":"太陽光も使い、そういうものに対するモデル的な事業としてやっていただきたい。こちらも、やる以上、新しい建物ですし、区はせっかく取り組むんですから、それなりに最大限、こういう形でやっていくんだと。要するにそういうことを考えて、数学的に、どのぐらいの費用がかかるのかとか、設計段階から、そういう体制で、緑化条例に生かしてもらいたいなと、これはぜひお願いしたいと思います。これは結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"沢田委員","kind":"質問","question":"二つあるんですが、１ＤＫがこうしてできるというのはめずらしいし、単身用というのは、非常に狭き門で、ある意味ではいいというか、おもしろいというか、期待があるんです。あるいは、戻り入居の方は１けた台と言いますけど、既存の家賃と荏原市場跡地の家賃と、戻ったときの家賃。今後、屋上緑化を進めていく上での見通しになると思うんで、わかったら教えてもらえますか。","respondent":"田村住宅課長","answer":"ですから、特別平米単価を、屋上緑化分何がしという形で出しているのではなくて、既存の工事費の中で屋上緑化も工夫してやるという考え方です。","id":"exchange-049"},{"speaker":"沢田委員","kind":"質問","question":"だけど、新しいから、多少上がるんじゃないかと思うんですけど、いろいろほかもあるからあれかもしれないけど、所得は変わらずに、実際に同じ面積で移った場合に、やっぱり１割とか２割とか上がるんじゃないかと思うんですけど、その辺の大体の見当があったら教えてほしい。それから、屋上緑化というのはそんなに金がかからないものなんですか。","respondent":"松代道路公園課長、田村住宅課長","answer":"屋上緑化の平均単価ということですが、午前中もちょっとお話ししましたけども、設計条件によって多少違ってまいります。新築の場合ですと、今回の場合はまさに新築ですが、ある程度上に加重がかかることを想定してつくる。それで、やはり居住水準も上がりまして、同じ１ＤＫでも、当然、平米数自体が広くなっていますので、経過措置はありますので、あくまで予想ですけれども、おそらくは今よりは若干高くなる可能性はあると思います。","id":"exchange-050"},{"speaker":"辻委員","kind":"質問","question":"大井伊藤町住宅の都営住宅というのは２ＤＫですか、１ＤＫですか。","respondent":"田村住宅課長","answer":"現在は、１ＤＫが２３.２４m2で３６戸、３Ｋ、４０.３２m2が６戸、合わせて４２戸です。","id":"exchange-051"},{"speaker":"辻委員","kind":"質問","question":"先行き、募集するわけですよね。帰りたいという方もいらっしゃるでしょうし、残った分を募集するんだけど、このときは、どっちを募集するんですか。単身で募集するんですか、それとも所帯で募集するんですか。区民住宅ですから、年齢は関係ないですよね。今回、たまたまのチャンスなんですが、かといって、単身に絞っちゃうというのももったいない感じもするし、その辺は、今後どういうふうにしていくのか。","respondent":"田村住宅課長","answer":"辻委員からご指摘のとおり、型別供給ということで、実際も間取り等、平米数も東京都とも調整しながらやっております。募集は、具体的にはこれから決めていきますが、１ＤＫ、３５m2前後というのは、１人から２人世帯の募集を考えているところです。","id":"exchange-052"},{"speaker":"辻委員","kind":"質問・要望","question":"要望だけ。ある程度バラエティにとんだような形で、やっていただければと思います。単身の方にも、やはり希望を与えられるように。都営住宅、区営住宅というのは所帯用という意識で、非常にがっかりする人が多いので、少しでも。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"上山委員","kind":"質問・要望","question":"少し先だったと思うんですが、今年の夏ぐらい、西品川一丁目の区民住宅が今工事中ですけれども、来年ぐらいから入居できるか、もう少し先だったか。あるいは、まだほんとうにこれからなら構わないんですが、どのぐらいの時点で発表するつもりでいらっしゃるのか、その辺をちょっと教えていただきたいと思うんですが。","respondent":"田村住宅課長","answer":"先ほどもお話のあった、フラット家賃とか、あるいは実際の近傍家賃の算定というのは、今現在、作業を進めていまして、４月ぐらいまでには決めないと、募集の申し込みのしおり等の配付だとか、ＰＲ等がありますので、今、検討している最中なので。","id":"exchange-054"},{"speaker":"沢田委員","kind":"質問","question":"長引いて申しわけないんですけど、１点だけ、東五反田二丁目のオーバルコートのところの区道が、少し段差ができて高くなっているんですよね。あそこの近所の人が、二、三人自転車ですべって転んだのを見たと言うんですよ。建設委員会で行ったときにちょっと言ったことがあるんですけれども、何であんなになっちゃったんでしょうか。事故が起きる前に、早く改善したほうがいいと思うんです。","respondent":"松代道路公園課長","answer":"ちょっと、今、私、場所が確定できないものですから、すぐに調査をしまして、状況等をお知らせします。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/923086?Template=document&Id=3712#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":65968,"voices":178}},{"id":"h14-20020304-9","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"文教委員会","time":"午前10時08分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"条例整備は都道府県から当該区市町村ということですけれども、これは今の東京都の条例と全く変わらないということなのですか。","respondent":"久保田学務課長","answer":"私どもの独自条例ですので、条文の書き方とか、「てにをは」というのは私どものオリジナルですけれども、基本的には今まであった条例を継続するという意味合いがありますので、東京都の条例をほぼ参考にしてつくったです。ですから金額等においても変わりはございません。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"もう１件ですけれど、この公務災害の発生件数、最近では１０年間発生したことがなくて、品川区では全くないというのですけれど、例えばどんなことがあったのですか。","respondent":"久保田学務課長","answer":"過去に一番近いところで発生したのが平成２年というふうに聞いてあります。このときには林間学校の実施に伴う保健衛生指導のために学校に来たところ、正門のそばの盛り上がりのところで足を取られて転倒して負傷した、こういうケースがあります。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問","question":"学校医とか学校歯科医の決め方というんでしょうか、薬剤師も。こういう決め方というのはどこでどういうふうに決めるんでしょうか。それから何人ぐらい学校医がいるのか。それぞれ学校ごとというか、５８校、そういうのだと思うのですけれども、トータルを薬剤師も教えていただけますか。","respondent":"久保田学務課長","answer":"学校の学校医等が何人いるかということなのですけれども、それぞれ学校医、これは内科、それから耳鼻科、眼科、それから歯科、それから薬剤師ということで、合計５人掛ける５８校です。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"学校から医師会に相談して、医師会で協議して決めるということですか。教育委員会のかかわり方というのはどういうふうな。どういうふうに学校医さんって決めているんですかと言われて、私もどうやって決めるのだろうなというふうに思って、かなり積極的にそれにかかわっている人もいるので、決め方とか手順とか、もう少し規定とか何かあるのかなと思って。","respondent":"久保田学務課長","answer":"それから今新しくということになるんですけれども、当然これは学校のほうと学校医のほうは常に綿密な連絡体制をとっていますので、やはりその本人がどうもいろんな事情で学校医のほうをやめたいなり、あるいはというような場合には私どもにそういう情報が来ますので、私どもと。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"規則みたいなのはないんですか。基準とか規則とか。","respondent":"久保田学務課長","answer":"規則ではないんですけれども、要網的なものは私ども持っております。教育委員会規則で一応そういう任命をすることになっていますので、それを受けて私ども要網的なものは持ってあります。","id":"exchange-005"},{"speaker":"高星委員","kind":"質問・要望","question":"一つだけ。これにかかってくるのは具体的な何かあったときの補償の関係ですから、そっちのほうが必要なんだろうというふうに思うんですけれど、今の桜井委員との関係でちょっと教えてもらいたいんだけれど、結局各学校それぞれ５人、そしてそれが５８校ということだったんですけれど、これは何も同じ人が幾つもなったらだめだというわけじゃない。","respondent":"久保田学務課長","answer":"関係ございません。それは全く学校のほうで独自にやっている、この薬剤師会とは全く違うものです。やっていただくことに当たっての報酬ですけれども、これは月々それぞれ薬剤師に決まった報酬をお支払いしている状況でお仕事をやっていただいているです。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この条例的にはわかったんですが、この条例が区に変わってきたことによって補償額の財源的なものというのはどこから。どこかの保険か何かに入っている分からこれ補償額が出てくるんですか。","respondent":"久保田学務課長","answer":"これが市町村になったということで、特別交付税の措置の予定というふうにはなってあります。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると例えばさっきちょっと出させてもらったんですけれど、保険みたいなものは一切なしの、そっくりこういう案件が起きたときに区の持ち出し、財調の財源かもしれないけれど、区として持ち出してというふうに考えればいいわけですか。","respondent":"久保田学務課長","answer":"私ども区としてもそういうような考え方で行きたいというふうに考えております。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"先ほどの説明の中で、ほぼ都の参考で金額的にも同じだというご説明があったんですけれども、参考までに伺いたいんですけれども、教職員の方の公務災害の基準などと比べるとどういう割合なのかなと。特に補償基礎額とかこの辺の算定の仕方で何か額とかがあるのかどうかを教えていただきたい。","respondent":"久保田学務課長","answer":"この件の細かいところは、じゃ国家公務員といくら違うのかというのは、これは非常に難しい問題でして一概にはお話はなかなか難しいんですけれども、そんな感じで受け取っていただければと思います。","id":"exchange-009"},{"speaker":"桜井委員","kind":"質問","question":"今の説明の後段ですけれど、前段はこれはもちろん理解しているんですけれど、狭まった理由というのは何なのでしょうか。","respondent":"鷹倉庶務課長","answer":"冒頭に申し上げたとおり、国家公務員の介護休暇制度との均衡ということなんですけれども、恐らく実質的に考えられるのはということですけれども、これから話題にするんですけれど、社会に説明していく中で、かなり範囲が広がるんではないかということで若干制約された。","id":"exchange-010"},{"speaker":"桜井委員","kind":"質問・要望","question":"現在、この現状も老齢で取得というのかしら、活用されているというのかしら、そういう事例というのはありますか。それで例えばこういう事例の方がこのことによってだめになっちゃうとか、例えばですよ。ちょっとわからないんですけれども、少し具体的な事例があれば教えていただきたいんですが。","respondent":"鷹倉庶務課長","answer":"私どもの方、これ幼稚園教育職員、調べてありますので、１２年度からですが、今のところ調べたところ該当者はなかったですので。区全体の中では総務委員会でやっていると思うんですけども、そちらの中ではいろいろ事例があるのかなと思われます。","id":"exchange-011"},{"speaker":"桜井委員","kind":"質問・要望","question":"それから二つ目では、この進め方の問題でちょっと説明いただきたいんですけれども、一般公表した後、現場で日野とか一日野とか二日野とかＰＴＡの皆さん対象にとか、あるいは町会の連合会ですか、そういう地域の皆さんからもかなりある日突然聞かされた話ですから一体どういうことなんだという意見が出たと聞いているんですけれど、その辺の進め方についても私は問題があると思っているんです。","respondent":"若月教育長、鷹倉庶務課長","answer":"まだまだいっぱい課題はあるわけですが、大きな一つの方策として小中一貫というものが子どもたちのための大事な方策の一つと、こういうふうに私たちは考えて、今回の実施に踏み切ったと、かように考えているところです。公募はどうかというお話でございましたけれども、今回具体的な当該校のところということで考えてありますので、学校のＰＴＡの方、あるいは町会の方、この方々が一番身近な方々。","id":"exchange-012"},{"speaker":"桜井委員","kind":"質問・要望","question":"だからいろんな形でやっぱり広く公募という区民の声を聞けるそういう体制を私は検討すべきだというふうに率直に思いますし、この準備委員会というのは公開になっていくんでしょうか。連携についてはね。だからいろんな関係者の声、あるいは教育委員会の考え、それはやっぱりきちっと説明をにして、あの意見を聞くという、そういうことをやって、ぜひやっていただきたいと思うんですが、いかがでしょうか。","respondent":"若月教育長、鷹倉庶務課長","answer":"ですから私たちはそのさまざまな考えられる範囲の方策で今それに取り組んでいるわけでありまして、例えば委員がご指摘のように、６・３制という今の日本の学区制を何かするんじゃないかとかいうようなご指摘があったわけですけれども。公開問題がございましたけれども、プラン２１推進委員会もそうですけれども、一切情報公開で対応しているです。","id":"exchange-013"},{"speaker":"桜井委員","kind":"質問・要望","question":"やはりそれは区民の大事な子どもたちを教育していくわけですから、少なくとも個人の教育ということについてどういうふうに教育委員会は考えているのか。だから私は教育長がそういう情熱を持ってやろうというならば、教育長主催でもいいですよ。だからそういう形をぜひ私は取っていただきたいと思うんです。そういうのはぜひやっていただきたいと思うんです。それについてだけもう１点聞いて終わります。","respondent":"指田教育次長","answer":"地域に対する説明会、われわれも一番関心といいましょうか、丁寧にやっていきたいという気持ちは持っています。したがいまして、プレス発表前に実は私と庶務課長と２人で各学校を回りました。","id":"exchange-014"},{"speaker":"川西委員","kind":"質問・要望","question":"ですからそういう点では公聴会がいいのか、どういう組織がいいのかわかりませんが、もう少し幅広く意見を聞いてもらえる場が、検討委員会を進める段階で必要だというふうに思います。ですからそういう点ではそこの利用者、今利用している人かどうかは別ですよ。今わかる範囲では学力以外の効果というものはどこに一貫校の中にどういう効果があるのか聞かせていただきたい。その三つぐらい。簡単でいいですよ。","respondent":"鷹倉庶務課長、若月教育長","answer":"検討メンバーの関係で特に施設検討部会のところをもう少し幅広くできないか、こういうお話。その中でもう一度準備委員会としての小中一貫校の効果とか期待するものとかといったようなものを検討していただいて、これらをまたまとめてその都度ご提示していきたいと、こんなふうに考えておりますので、よろしくお願いいたします。","id":"exchange-015"},{"speaker":"川西委員","kind":"質問・要望","question":"議論をする気はありません。さっき傍聴などについての公開がご答弁あった……。これ学校選択。一言だけ要望を申し上げておきたいのは、非常に一貫校に対する期待が今の小学校の保護者とか、さっきおっしゃった幼稚園の保護者は将来を見るときにあると思うんです。できるだけニュースは的確に伝えてほしいというふうに思いますので、よろしく。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"例えば日野中のＰＴＡだとか、９日に。大体の内容を聞きたいということ。３１か２あるんですね。各町会長にどういうようなものが行っているかというと、Ａ４のペラ１枚なんですよね。それを聞いたら「こういうのが回ってきただけですよ」、こういう話だったもんですから、ちょっと役員会の中でどういうような話をされたのかということをちょっとお聞きしたい。なかったらそれはいいですけど。","respondent":"指田教育次長","answer":"したがって、ただそうは言ってもということでもって、一貫はできないかもわからないけれど、連携というものは追求していきたいと、こういう話は私させていただきました。","id":"exchange-017","title":"町会・自治会支援"},{"speaker":"高星委員","kind":"質問","question":"済みません。私も然るべき予算委員会の中でちょっと質問を考えているものですから、余りここでやるつもりはないんですけれど、どっちにしても今、二日野の校長先生が小学校の校長会の会長だと。質問になりませんけれど、今の議論、さっき言った地区委員会で次長が拒否をしたのかどうかわからないけれども、その辺のいきさつだけちょっと聞いて私からは終わりたいと思います。","respondent":"指田教育次長","answer":"私どもは根本はお話し合いを拒否しているわけでもありません。その今の日野、後半に行く話の大崎第一地区にこれから行きますよというのをわざわざ私のほうから会長にお話をしたんですね。言わなきゃ、黙っていればわからなかった話で向こうに行ったかもわかりません。","id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"わかりました。だけれど現実的には地元はどうなるよと。だからこれは私も昔から言っているんだけれど、小学校は実際上は今の５年生、今の４年生から全部絡んでくる話となってくるわけですから、将来的にはさっき言ったように各小学校の基礎的な、今はだから１学年十何人しかいない学校に３クラスも子どもが行くということは、もともとの子どもは最初から行っちゃうという話にもなるわけですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問・要望","question":"戸越台中学校が複合化されるときも相当な騒ぎが起きましたね。やはり今出ている議論の中にもありましたように、私は統廃合論者ですから、統廃合ですよと言えばそうだと言いたいんですけれども、ここは統廃合ではないという中でも．やはり二つの学校、必ずそういう意味では地元からの反対の声というのは出ると思いますので、その辺はしっかりとカバーして説明をしていただきたいと思います。","respondent":"指田教育次長、山岡スポーツ協会次長","answer":"ただ、基本姿勢としてはやはり１人でも多くの方にご納得いただけるような形でもっての説明会というものはやっていきたいなというふうに思っております。それが基本姿勢であります。ですから一回り大きくしていただきたいというのは考えております。それは今後の検討課題です。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"その中で小学校と中学校が一貫校ということで二つの学校ですよね。３クラス、４クラス想定しているわけですから。そうすると学校の体育館というのは別につくるわけですか。","respondent":"鷹倉庶務課長","answer":"基本的に別というふうに、今のところ一つの考えを持っています。","id":"exchange-021","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"３クラスというと小学校は１２０人まで、中学校は１６０人までということですけれど、最低１２０名、小学校のクラスとして、あるいは１００名まで一緒に入学した子どもたちそのものが中学校を卒業するまで一緒ですよというのだろうか、あるいは小学校を卒業した過程で一貫校の教育を受けてみたいから新しい学校に行きたいという人が入る枠があるのか、そのような進め方というのはどうなんですか。","respondent":"青木指導課長、富田教育改革担当課長","answer":"そこでやはり選ばれる学校という形でそれぞれの保護者や子どもたちが学校をどういうふうな形で選ぶのかということも含めてまた今後カリキュラムの編成と絡めて検討課題にしていきたいというふうに思っております。小学校に入学した児童がそのまま中学校に進むのか、あるいは中学校段階での募集が入ってくるのかですけれども、これも検討部会の中で具体的には論議し検討していくことですが、現時点で考えられることといたしましては、小中一貫校。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。私もそのような気がするんですけれど、先ほど高星委員も言われましたように、そうなってくると、ことし二日野は１２名ですから、１２という数字を取られたらしいですけれど、１２名しか小学生がいないところに１００名からの小学生が増えるわけですよね。中学の学区は違いますけれども、御殿山は一番近いですから、それらも含めてやっぱり十分に話し合う必要はあると思いますね。","respondent":"指田教育次長","answer":"したがって決意につきましては議会、それからあと執行機関、それからそれが一巡となりながら同時に区民のご意見や何かもお受けいただき、同時に説明もしていきたい、このように考えております。","id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その点、１点と、あともう一つは説明会のことなんですけれども、次長から丁寧にやっていきたいということもあったので、本当にそのようにやっていただきたいなと思いますけれども、この間地域でいろんな会なんかあったときに、とにかく地域の人もそうだけれども、親の声を広く聞いてほしいんだというところで、さっき公聴会はしないということなんで。","respondent":"青木指導課長、鷹倉庶務課長","answer":"これは小中連携のみならず、プラン２１の推進校はすべてにわたって１年間を振り返ってそれぞれの学校の評価と、それから教育委員会からいろいろと指導、助言をしてきておりますので、教育委員会からの評価も出しています。説明会、丁寧にということ、それからあまねく広くです。今回９日あるいは１３日に日野中あるいは二日野に行ったわけですが、このときには役員の方、会長、副会長、そして書記、会計、監査もいらっしゃるところもあります。","id":"exchange-024","title":"町会・自治会支援"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"済みません。これはやっぱり全教員のものにしていただきたいな。もっと本当にもまれたものというか、いろんな方の意見が入ったものにしていただきたいなと思うんですね。とにかくこのプラン２１始まってからいろんな取り組みがあるんだけれども、一つ一つがやっぱり十分説明されてわかってこそ本当に選択になると思うんで、そこに本当に心砕いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"何点かちょっと教えてください。小学校１年から中学３年まで９年間ということで考えていった場合、生活の場所が必要になってくる。小学校１年と６年でさえ随分違うと思うんですね。当然受け入れてもらえるののかどうかというのがまず大前提だと思うんですけれど、そこら辺をどう考えていくのかなというのが２点目。全部先々の問題になってくると思うんですけれど、基本的な考え方を教えていただきたい。","respondent":"青木指導課長、鷹倉庶務課長","answer":"それから２点目の、９年間一貫したカリキュラムの中で他校から転入するということが非常に難しいのではないかというご質問ですけれども。体育館側からそういう要望が出てきますし、先ほど説明しました施設検討部会、学校のほうですね。安全管理の面とすり合わせしながら立地の問題等々いろいろ具体的に検討していく必要があるかな、こういうふうに考えております。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もう一度確認ですけれども、中学校が転校生も中学校で受け入れていただけるという点。","respondent":"久保田学務課長","answer":"転校生の問題ですけれども、これはまた一つの検討課題ではあると思いますけれども、基本的には品川の場合には学校選択を基本に置いておりますので、その親御さんが小中一貫を受けたいのか。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"転校というのも、逆にいうと品川区の人間はわかるけれど、地方から来た場合、ほかから来たときに、その流れというのは余り理解できない部分もあると思うから、近くだとどうしても入ってしまうと思うんですよ。ある程度自分の実例的なんですけれど、中学校あたり自分の行っているところはある程度進んでいた学校だったんですね、授業形態が。そういうケースもあったので。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"桜井委員","kind":"意見","question":"素朴な疑問ですけれど、例えば西側の学区にいて、それで一貫校を希望しますよね。だけれど例えば抽選になっちゃって。抽選。だから今までの学区域の子どもたちは優先じゃないわけでしょ。これから検討というのはあるにしても、でも今の教育長の話だと、全区、今４ブロックあるけれども、それも学区を外すみたいな話もあるようなんですが、現実に。今後の検討課題、戸越台中はちなみにどうなるのか。","respondent":"久保田学務課長","answer":"そこのところもやっぱりこの準備委員会の中で十分に議論していきたいというふうに思います。","id":"exchange-029"},{"speaker":"桜井委員","kind":"意見","question":"それでさっきから私、構成メンバーを言っているのは、この準備委員会の中にＰＴＡ、中学校ＰＴＡ連合会長、校長会、１年ですよ、任期がみんな。任期が１年でしょう。そうしたらこの流れでいくと、学識経験者と教育長の考え方でまとまっちゃいますよ、この準備委員会の構成は。今までの委員会もそうですよ。そうでなければ……。というふうに思います。","respondent":"指田教育次長","answer":"当然学区域の問題というのは検討する最優先課題だろうと思っています。できれば夏までの間には結論を出したい、こういうように思っています。そうしませんと、少なくとも来年度、要するに平成１５年度入学希望を取りますね。","id":"exchange-030"},{"speaker":"高星委員","kind":"意見","question":"準備委員会の中に小Ｐ連、中Ｐ連の会長が入っているけれど、実際本当にかかわってくるのは、小学校の、特にあの辺を中心にした小学校の５年生ぐらいから具体的にかかわってくるのよ。［「３年生ぐらい」と呼ぶ者あり］だからその辺までも視点をその辺に置いてやらないと、聞いたらまだ小学校だけでやっているのは二日野だけでしょう。反対のしようもない第二日野小学校でやっている。そういうことになる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"川西委員","kind":"提案","question":"これはご答弁要りません。今、教育長、あるいは次長の答弁を聞いていたと思いますけれども、この地区を統合可能だと、施設の有効利用、八潮団地の活性化、教育に関係ある施設だとか福祉施設、何でもいいですけれども、もっといろんな人が出入りするような地域に活性化していくということをご提案しますが、もしご意見があったら聞かせていただきたい。今計画されています。予算委員会で質問しませんから。","respondent":"指田教育次長、鷹倉庶務課長","answer":"この間、私どもも率直にプラン２１を進めていくに当たって、統廃合を前提にしたものではないということははっきり申し上げてきております。そういう中において、昨年度でございましたか、松澤委員の本会議答弁だったと思います。これはそれぞれ学校につきまして、個別の学校改築検討委員会というような形のものを立ち上げていきたいなと思ってありますけれども、その中で、具体的にこの学校についてはこういう校舎を建てたいなという話が出てこようかと思います。","id":"exchange-032"},{"speaker":"川西委員","kind":"質問","question":"１点だけ。これはいつごろ検討委員会を立ち上げていくかという検討はどの程度まで進んでいるのか、されているのか、伺います。","respondent":"鷹倉庶務課長","answer":"基本的に、小中一貫の場合はああいう形で考えさせていただいているわけですけれども、通常の学校改築の場合については予算が通ってからというふうに基本的には考えてあります。","id":"exchange-033"},{"speaker":"川西委員","kind":"意見","question":"簡単な事務的なことです。改めてこの表を見ますと、台場小学校はなぜ２０番なのか。ブロックが違うでしょう。","respondent":"久保田学務課長","answer":"これは行政順というんですか、通常私どもはそれぞれの学校に番号を振ってございまして、台場は２０番目ということになってあります。これでやると、もう一つブロック別に出せばよかったんですけれども、今回は一覧に出させていただきました。","id":"exchange-034"},{"speaker":"桜井委員","kind":"質問","question":"数字上でしか出てこないから、そこは何とも言えないんですけれども、例えばですね、１３、１４年を比べてみますと、学校名をちょっと言うのはあれですから、小学校で言えば８番、それから１３番、１５番、それから１７番、それから２４番、あと３６番というところが１３年、１４年で共通した傾向が見られますよね。それで、逆にプラスというんでしょうか。いかがでしょうか。","respondent":"久保田学務課長","answer":"それは率直に言って１２番目の大井第一小学校ですが、やはりこれは学校選択が始まる前から指定校変更でもって大井第一に来る傾向が強かった学校でございまして、その傾向がやはり学校選択の中で、数字は大きくなったんですけれども、その傾向が継続しているということで。","id":"exchange-035"},{"speaker":"桜井委員","kind":"質問・要望","question":"そうすると、今の説明だと、従来の流れが若干加速している部分というんでしょうか、従来の傾向がそのまま続いて、若干場所によっては加速化しているという理解でいいのかどうか。選択制のねらいというのは。親が選択したことはそうなんだけれども、そういう制度をつくったのが、この間も言ったように教育委員会ですから。その小学校から。教育長が言う小中連携をとなれば。いかがでしょうか。","respondent":"久保田学務課長","answer":"これがまさにプラン２１を目指しているところであるというふうに私は思っておりますので、ほかの学校についても、教育委員会としましては、減っているところに対しての支援策なり、あるいはその数の増減ということではないですけれども、そういう面で委員がおっしゃられるように。","id":"exchange-036"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、そういう点では、私はもう少し総括という、ちょっと言葉としては正確かわかりませんけれども、到達点というか、教育委員会としての、この間、前回のときはシンポジウムをされて、学務課長のほうから一定程度の報告はいただいてありますけれども、ぜひそれをお願いしたいし、それから、さっきお話ししたかなり現象として少なくなっている部分、あるいは多くなっているところというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"高星委員","kind":"意見","question":"中学で３学年しかないわけでしょう。それで、こんな数字になっちゃって、どうするんだと思って、これ。だから、これから先、こういう子どもの数で、その辺の将来的なことをどう考えているのか、ちょっと取り組むべき課題は取り組む課題としてきちんと整理して出していかなきゃ、恐れず議論していかなきゃならない時代が来ているんじゃないかなというふうに思うんだけれども、この辺のところをどう、考え方。","respondent":"指田教育次長","answer":"決して我々は避けて通るというふうには思っていませんし、言うべきときにはきちんと言わなくちゃいけないと思っていますが、今の時点においては、この間からもお話、あるいは今日の冒頭でもお話ししましたように、その統廃合の問題については。","id":"exchange-038"},{"speaker":"高星委員","kind":"意見","question":"そういうことだと思うんだよな。ただ、従前からも僕なんかが言ってきているのは、学校と地元の関係、これは一番重きを置いていたことは事実だよね。極端なことを言ったら、私も口が悪いから言うんだけど、将来的に学区域の統廃合を議論するときでも、教育長はいないかもわからないんだからさ。だから、そういうことも含めて、やっぱりどうも順序が逆のような気がしてならないんです。","respondent":"指田教育次長、若月教育長","answer":"改革が緒についたというふうなところで、まだ３年目という段階において、先ほどの冒頭のところへ戻れば、やはりもう少し時間的なものというものをいただきながら。したがって、もうしばらくみんなで悩み、そしてみんなで考える、そんな時期も私は必要なんじゃないだろうか、こう思っているところですので、ひとつご理解のほどをよろしくお願いをいたします。","id":"exchange-039"},{"speaker":"高星委員","kind":"質問","question":"今のわからなかったことを。じゃあ、そこのところに営々として今まで語ってきた住民を代弁して、区民を代弁してみんなで話し合ってというところで、与えられた選択肢の中から選ぶしかないじゃないですか。だから、だれの英知が結集された方針なんですかというのを言いたくなっちゃうんですよ。〔「小中一貫ですか」と呼ぶ者あり〕それも含む学校改革のやつ。総体的に。","respondent":"若月教育長","answer":"何かそのお話を伺っていると、私が１人でものを考えて、私が１人でものを進めているような受けとめ方をされて非常に心外であります。はっきりと申し上げますけれども、英知と言ったのは、学校現場は今さまざまな取り組みをしています。","id":"exchange-040"},{"speaker":"高星委員","kind":"意見","question":"２人でやっていたんじゃどうしようもないんだけれども、じゃあ、最後に一言。だから、これの一連の関係、例えば先ほどの話で、１３の小学校からある中学校に来ている。そんなことを言ったら。だから、そういうときに本当に区民と十分に話し合った、あるいは学校関係者、ＰＴＡも含めていろいろな事前に議論をしたという経過がないもんだから、だから僕はやっぱり心配するわけ。","respondent":"若月教育長","answer":"確かにＰＴＡのお話は私もよくわかりました。ただ、今進めているさまざまな教育改革についてですね、確かに校長によって温度差があることは間違いありません。","id":"exchange-041"},{"speaker":"松澤委員","kind":"質問","question":"裏側の中学校なんですけれども、私も理論的には高星委員と同じように中学校が１クラスでいいのかなというのはすごく感じているんですね。その中でちょっと見ますと１８番ですよ。あの時にはゼロになっちゃったらどうするんだというふうなお話をしましたけれども、この９人という数字をどんなふうにとらえているのか。その９人という数字の重さをどのように考えているのかをお聞きしたいと思います。","respondent":"久保田学務課長","answer":"それに対しまして、学校関係者はそれこそ毎日対象者の家庭を訪問したりして、ぜひとも学校の取り組み、あるいは今後の方向性というものを説明しながら、南中でもう一回やってほしいということで熱意を向けて傾けたところですけれども。","id":"exchange-042"},{"speaker":"松澤委員","kind":"質問","question":"指導が。そういうような問題を聞いて、私もその子に会ったことがないので、僕１回ちょっと会ってみようかなと思っているんですが、そんなことで子どもが減っていく。小学校６年間教育されて中学に来るんですよ。そうじゃないですかね。そんなときで、小学校の子どもたちの教育というか、しつけというか、そこらから問題がしてくると思うんだけれども、その辺はどう考えているんですか。","respondent":"青木指導課長","answer":"それで、教育委員会も、これからもそうしたそれぞれの学校の課題にこたえて取り組めるような、そうした状況をつくっていけるように支援してまいりたいというふうに考えております。","id":"exchange-043"},{"speaker":"松澤委員","kind":"質問","question":"これからのでなくて、小学校のああいう段階から。いや、だから、その課題の子が中学に来て、今のそういうふうにするんだというのはわかったんだから。小学校の間はどういうしつけや教育をしたんですか。","respondent":"青木指導課長","answer":"今後も小学校の指導に生活指導主任たちを通してまた考えていきたいというふうに思っております。","id":"exchange-044"},{"speaker":"松澤委員","kind":"質問","question":"子どもたちは中学を選べますけれども、学校は子どもたちを選べないわけですから、そういう子どもたちが来たときに、ああ、よし、じゃあこの子どもたちを３年間うちの中学校で一生懸命教育しようと、理想ではありますけれども、そのような環境があればいいわけよね。ちょっとその辺の応援体制というのは今後やっていけるんでしょうか。","respondent":"青木指導課長、若月教育長","answer":"学校とよく連絡をとり合って、指導主事、学校経営指導員、そうした指導課のスタッフでサポートしていきたいと思います。そこで、その部分についての研修は従来から続けているところなんですが、これはなかなか実感として問題が起きないだけに小学校の教員には伝わりにくいという大変難しい部分はあります。","id":"exchange-045"},{"speaker":"高星委員","kind":"質問・要望","question":"学童クラブというのは、例えば今日来ないけれどもどうしたのという形になるじゃないですか。すまいるの関係では、登録してあるんだけれども、来ないけど、例えば学童クラブだったら、来ないと子どもを探すじゃないですか。だけれども、ここではその辺の扱いはどうなっているんだったかなと思って、ちょっと悪いんだけれども教えていただきたい。登録したけれども、来ないと。","respondent":"富田教育改革担当課長","answer":"参加につきまして、しているかどうか大変心配であるという親御さんにつきましては、親御さんのほうから問い合わせをしていただけばお答えをしますという対応を今のところしています。","id":"exchange-046"},{"speaker":"高星委員","kind":"質問","question":"あいつどうしているかな、こうしているかなと、それはそういうことはそれぞれの指導員の皆さん方が協力してやっているんだろうというふうに思いますけれども、具体的なそのようなところで問題が起きたようなことはありませんでしたでしょうか。その辺のところの細かいところで申しわけないんですけれども、これから先、やって１年だからいろんな、最初の１年ぐらいいろんな問題が出てくる。","respondent":"富田教育改革担当課長","answer":"帰る時間がわからないですとか、３時帰りの予定だったけれどももっと遊んでいたとか、そういったことが重ねてございまして、その辺についてはやはり親と子のその辺のルールづくりといいますか、その辺が基本だというふうに思っておりますので、また参加しているはずだけれど。","id":"exchange-047"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この辺、指導員とか講師の方のこと、あとその指導員、講師はボランティアということなので多分無報酬だろうなと思うんですけれども、その辺、指導員のところの待遇というか、報酬のところを聞かせていただきたい。","respondent":"富田教育改革担当課長","answer":"すまいるスクールの場合は１４年度から特にそうなるんですけれども、学校の放課後の平日の部分と、学校がお休みの土曜日の部分と、その役割といったものが若干異なってくるのかなというような認識をしておりまして、放課後の部分につきましては学年ごとの勉強会ですとか。","id":"exchange-048"},{"speaker":"飯沼副委員長","kind":"質問","question":"一つはパソコン教室なんですけれども、１回６０名近く、すごく好評で子どもたちが喜んでいると聞いたんですけれども、講師、アシスタント募集というのに応募された方が、アシスタントという意味で、講師の方がいらっしゃって、ご自分は手伝い的に応募したんだけれども、実際行ってみたら、２人いたんだけれども片一方の方がやめられて、結局１人で全部責任を負っているというお話をちょっと伺ったんですね。","respondent":"富田教育改革担当課長","answer":"初めにご指摘の、ないところというのは、こちらで抜けている月という意味ですか。","id":"exchange-049"},{"speaker":"飯沼副委員長","kind":"意見","question":"例えば、だから毎月１回とかじゃなくて、ない月もあるのかなという。その辺がなぜかなという。","respondent":"富田教育改革担当課長","answer":"これは表のつくりとして、こういう１表にまとめてしまいましたけれども、当初の趣旨といたしまして、英会話、パソコンにつきましては、保護者の方もお子さんも希望が多いですから、毎月定型的にやっていきたいというのが基本ですけれども、その他につきましては。","id":"exchange-050"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"パソコン教室については、本当に子どもたちがすごい喜んで参加しているということなので、ぜひ内容を充実させるという意味では、本当に学校の先生のところとか、あと専任の方全体を見ていらっしゃる方のご意見なんかも十分取り入れて、担当者が悩まないように工夫をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"桜井委員","kind":"質問・要望","question":"小中一貫にしようかなと思ったんですけれども、それはまた予算委員会がありますので。佐藤弥二郎議員の「学校経営と外部評価について」から、外部評価の問題で１点、明日質問をさせていただきたいと思います。これは文教委員会に正式に報告のない中身でありますので、改めて聞きたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/207072?Template=document&Id=4430#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":63681,"voices":139}},{"id":"h14-20020304-5","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"総務委員会","time":"午前１０時０４分～午後５時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件抜き出しています。","topics":[{"id":"topic-01","title":"第１４号議案から第１６号議案までは職員の勤務に係る議案でありますので、一括審査いたします。 それでは、(1)の第１１号議案","agenda":"第１４号議案から第１６号議案までは職員の勤務に係る議案でありますので、一括審査いたします。 それでは、(1)の第１１号議案","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"今回から金額を書かないということですけれども、どんどん金額が下がっているという事実があるわけですけれども、私も勉強不足で、伺いたいんですけれども、これからまた株が上がってくるわけですですね。そういうところの何か上がってくるとか、そういうことになっているんですか。","respondent":"太川総務課長","answer":"先ほど改正の理由といたしまして説明をさせていただきましたけれども、証券の額面が、どこどこの会社が１株幾らということで決めてありますと、これにつきまして、設立時には定款にそれを書いておかなければいけないということであります。","id":"exchange-001"},{"speaker":"北野委員","kind":"質問","question":"初歩的なことでお伺いしたいんですけれども、書類の報告書を作成し、提出しなければならないということですけれども、提出というのは、どこあてに提出するのか。そこのところがわからないんです。","respondent":"太川総務課長","answer":"これは区長が区長に提出するです。","id":"exchange-002"}]},{"id":"topic-02","title":"の第１２号議案、品川区同和対策資金貸付条例を廃止する条例","agenda":"の第１２号議案、品川区同和対策資金貸付条例を廃止する条例","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"事業振興資金は昭和６２年度以降、生業資金が昭和６３年度以降新規貸付を行っていないということですね。それ以降は貸し付けを行っていないということですけれども、申し込みはなかったんですか。","respondent":"阿部人権啓発課長","answer":"申し込みもございません。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"申し込みがないというのは、品川区のところで実際に今、同和事業の相談員を置いているんですけれども、今回から相談員２名から１名ということになっておりますけれども、それ自体も置いておく意味が改めて問われるんじゃないかと思うんです。実際に昭和６２年以降、生業資金は昭和６３年以降申し込みもないというのは、実態として品川区がそういうのは必要ないと。実際問題、法律も終了ですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"北野委員","kind":"質問","question":"この貸し付けを受けるための手続きはどういうふうにされているのか、ちょっとお伺いしたいと思います。","respondent":"阿部人権啓発課長","answer":"そうしますと、審査会というところで、貸し付けをしていいかどうか、これは区長の附属機関ですので、審査会のほうで審査いたしまして、区長に、例えば貸し付けするのが適当であれば、そのような報告をいたします。その報告に基づいて貸し付けをするです。","id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"期間としては、審査の結果が出るまでというのはどのぐらいだったんでしょうか。結局、こちらのほうに移った場合と、どっちが利用しやすいかという部分の判断が必要かなと思います。","respondent":"阿部人権啓発課長","answer":"生業資金につきましても、貸付限度額は８０万円ですけれども、社会福祉協議会のほうは１４１万円ですので、貸し付けの金額が大きくなるというようなメリットがあるというふうに考えてあります。","id":"exchange-006"}]},{"id":"topic-03","title":"の第１３号議案、品川区職員定数条例の一部を改正する条例","agenda":"の第１３号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"定数の減ということで、直接的なあれはないかもしれないんですけれども、職員構成、年齢別というか、よくピラミッド型のものが、今はビヤダル型というか、いわゆる下が細くて、真ん中がふくらんでくるという形、品川区の職員構成は、おそらくそういうことになるだろうと思うんだけれども、一番うしろの４ページの２番の表で、ここ３年ぐらいの新規採用の数は分かりますか。","respondent":"古川人事課長","answer":"平成１４年度は、最終的な確定は、平成１３年度中に一定の採用の事務手続きを行ってございまして、事務職につきましては１０名ぐらいということ、保育士につきましては１２名、保健婦を１名、こういう状況でございまして、一定の内示・内定がありますが。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"意見","question":"今まで再雇用というのが定数の外側のカウントだったんですけれども、再任用が今度の４月１日から始まりますね。今言われた平成１３年度末の１２０人余りの方々の中から再任用をしていくということで、それが、退職はされるんだけれども、定数からは外れないわけですよね。どういうふうにカウントするのか。我々は定数をどういうふうに把握しておけばいいのか、その辺を聞かしてくれませんか。","respondent":"古川人事課長","answer":"こういった形で一定の配慮をしていく必要があります。平成１４年度に向けての採用に当たりましての事務手続きは大体の感じですけれども、申し込みが６５人です。このうち選考していますけれども、若干不採用もあります。その者を除いた人員を採用する予定で今進めているです。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、週４０時間で、定数の中の１人という考え方で、２０時間だと、２人で１人ということにするという考え方というふうに、定数の中には、実際の数より多い人が働くということになるよという理解をしておけばよろしいんですか。単純に定数が１００だとしても、１１０人いる職場もありますよという考え方でいいですか。","respondent":"古川人事課長","answer":"４０時間を１と考えますと、単純に申し上げますと、２０時間ですと０.６人、時間数で捉えますとそういう形になります。我々が考えておりますのは、配分定数につきましては、条例定数の中には短時間は組み込んでございません。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、週４０時間の人だけが定数条例の範囲の中にカウントされて、それ以外の方は、再任用という制度に変わったけれども、再雇用と人数の定数に係る部分は同じですよという、それは法的にはいいんですか。","respondent":"古川人事課長","answer":"しかし、短時間につきましては、同じ一般職ではありますが、条例定数による管理ではなくて、別途管理という位置づけになっております。法的に問題はございません。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問","question":"とすると、各区市町村でやっている人員の見直しとか、職員数をもう一度考え直すというところで、こういう表を対象にして見ているときに、抜けてくる、僕らは、再任用というのは全部定数に入ってくるんだという認識をしていたものだから、そういうところの数も言っていただかないと、議論をしていくときに、こっちのものが１００人ぐらい再任用として短時間の人がいるんですよということも。","respondent":"古川人事課長","answer":"今のご意見はもっともだと思います。再雇用のときは一定の判断の中でこれも対象になった。今のご意見も踏まえまして、最終的には４月以降人数の勤務形態すべて固まりますので、その辺の考え方については皆さんにご報告できるというふうに考えてあります。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そうすると、定数条例とか関係ないとすれば、予算上は非常勤というか、どういう形をとるのかわかりませんけれども、品川区でも可能だというふうに理解しておきたいなと思うんです。これからのことだろうと思うので、区民の方のニーズも多様になってきているし、仕事そのものもきめ細かさが要求されたり、専門が要求されるので、その辺もぜひお考えに入れておいていただきたいと、お願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"本来ですと、両方を兼ね合わせて判断する必要があろうかと思うんですが、職員費単体の数字は出ておりますけれども、それらと兼ね合わせた数字というのはつかんでいらっしゃるのかどうかというのをお聞かせいただきたいと思います。","respondent":"古川人事課長、市岡企画財政課長","answer":"それをどこにどうですけれども、職員費につきましては、先ほどのご説明のとおり、予算・決算の中でで毎年の傾向については把握できるわけですが、今の部分につきましては、個別の問題として。そういう意味では、職員費の減に対応する委託料が幾ら増えているというふうな捉え方はしておりませんが、予算編成の中では、今まで職員がやっていた仕事をアウトソースにするものについては編成の中で一つずつ検証しております。","id":"exchange-013"},{"speaker":"田中委員","kind":"意見","question":"行政評価ということの、より詳細な分析、見方といいますか、増えてくるかと思いますので、単に職員数を減らすということに対する評価だけではなくて、総合的、評価的に、人件費は減ったけれども、逆に委託費が結果的には前年よりも費用が増えた、かかってしまったなどということがあってはいけませんので、そういう観点からの評価のできるような仕組みづくりをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"土井副委員長","kind":"質問","question":"今のお話を聞きながら、逆の話なんですが、国民年金の委託の問題で、ここで事業がそっくりなくなったといいますか、減少をしたということで、保険年金課で１７名の減ですが、実際上このうちの何人がどんな形なのかという、全部がそれでないのかもしれませんので、減というのは、さまざまなそのほかのこれに係わる事業の中であったのかもしれませんので、その辺をお伺いしたいということ。","respondent":"古川人事課長","answer":"一般的ですが、保険年金課の保険事業係や保険料係での事務は年金事務廃止・縮小ということで、こういったものが法定受託事務でしたが、この関係で全体で圧縮された部分が１７ということでございまして、保険年金課は配分定数上は８６人で、全体的に幾つかありますけれども。","id":"exchange-015"},{"speaker":"土井副委員長","kind":"質問","question":"今の話の全額というのは、標準見積もりで何人分だからということではなくて、現実に区に働いている、そこに従事をしている皆さんのパターンでしょうか。それとも具体的にこちらのほうから１７人が、これに従事しています、これには退職金等も含めてこういうふうな人件費がかかっていますよ、それを全額やってくださいというスタイルなのでしょうか。","respondent":"市岡企画財政課長","answer":"ただ、その分は財調の中で財源不足額を調整するという形をとっておりまして、そういう点では各区ばらつきがありましたけれども、品川区の場合はちょうどこの間、国民年金に係る職員の定数を何人減らすかというところで、各区の対応がいろいろある中で。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"それはもちろんそうなんだけれども、比較ということを考えるときは、もともと同じような、アウトソーシングにしたらどうなったということを比較しなければ行政評価にならないわけですから、そういうものもしっかりと取り組み、その答えをひとついただきたい。","respondent":"市岡企画財政課長","answer":"もう一方、これは同じ形で、同じ業務を外注するようなことは私どもは考えていないわけですが、全体として業務の執行の効率化、あるいは同じコストで、より高い成果を生むにはどうしたらいいか、こういうふうに業務の見直しを進めているわけでございまして。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"それで結果的に効果が上がれば、それは大変なことなんですから、そういう単純な比較が最初になければだめですよということを言っているわけで、そのほかに付加価値が出てくれば、その付加価値をどう評価するかは別問題で、コストの部分で縮減されたということは、業務委託の最大の理由ではないかと思います。そこのところがちょっと答えが明確でなかったから、聞いたわけです。","respondent":"市岡企画財政課長","answer":"全く同じ業務を外注しても、全く単純に同じようにできるのであれば、委員がおっしゃられるとおりだと思います。私どもは、ほんの少しそれを拡張して考えているです。","id":"exchange-018"},{"speaker":"塚本委員","kind":"質問・要望","question":"前向きのことは前向きとして答えればいいと思います。もう１点、具体的に定数を変えていったということの考え方を聞きたいんです。結果を効率的に組み替えようという考えで、明確にできていると言いますけれども、こういうことをするんだということの背景として、どういうふうにやっていくか、どういう考え方なのか、聞かしていただきたいと思います。","respondent":"本間総務部長","answer":"一番の問題といたしまして、今まで所管でやっておりました設計管理につきまして、法令上の建築士等の有資格者が行うものとされている部分で、人材の確保が非常に難しいという点と、所管課からの執行で行っている、こういう現行の業務体制が。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"事業部制を導入したことによって、現場に即したような設計なり管理監督ができるようにしたということです。その割には現場に異動した人は少ないように思うんですけれども、そのほかにも実際にはもう少し分かれているのか、それとも見えないところにそういうことが起こっているのかということをお聞きしたいと思います。","respondent":"本間総務部長","answer":"その理由といたしましては、例えば教育委員会に配置しておりましても、現在大規模な修繕がありますので事務量が非常に多くなってありますが、将来的に考えた場合には、実際の定数にプラス過員で当面配置して、その実態に合わせたほうがいいという判断から。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"施設課のところが０になって、経理課に１２人プラス、庶務課が２プラスというふうに伺ったんですけれども、例えば施設課ですと、今までも設備工事の進行の管理だとか、技術的な指導とか、そういうのをやってきたんですけれども、そういうような実態はどうなるのかなというのがちょっと心配なんですけれども、ほかにも課内のほかのところに属さないものをこれまでやってきたということなんですが。","respondent":"岡田施設課長","answer":"それ以外の経理課でやる部分は教育と児童課のほうに行くという話が先ほどありましたけれども、児童課のほうは保育園と児童センター関係、この辺のところを完結している。それ以外の部署については、従来どおり経理課に残ります施設部隊に執行委任を受けて実施する。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"こういう機能というのは実際どういうふうになっていくのか。特にこれからＰＦＩの導入、この間新しいやり方が導入されたんですけれども、そういうところが果たしてどうなっていくのか、教えていただきたいと思います。","respondent":"岡田施設課長","answer":"これからも経理課に残る部署の部分が、仕様とか、あるいは単価、もろもろのところは調整して、各事業部のほうにいく、こういう連携をとりながら統一していく、このような考えです。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"施設設計、管理事務が民間委託にいくんだと。事務事業評価の一覧を見ますと、これに基づいたものだというふうなお話だったので伺ったんですけれども、これが民間委託の方向にいくというようなところ、実際問題、例えばＰＦＩもつくったもの、これをまた管理をするのも民間で委託するということになるんですか。","respondent":"本間総務部長","answer":"今までも大規模なもの等は民間委託していたわけですが、民間委託をこれからは一層一歩踏み込んで進めますけれども、そういう技術的な調整とか、指導業務につきましては、経理課に残るベテラン職員、１級建築士、有資格者できちんとその部分については対応をしていくというのが。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問","question":"民間委託化の方向というのと、ベテランを配置しておるという話と、ピンとこないところがあるんですけれども、一応今の説明で聞いておきます。ひまわり荘の件もあったんですけれども、ひまわり荘は社会福祉法人の委託だけというお話だったんですけれども、ひまわり荘のところの中身では、児童虐待の相談なども受けることになるというふうに聞いているんですけれども、それは確かですか。","respondent":"古川人事課長","answer":"児童課の２人増やしていただいたということについても、その中で考えるというふうに聞いております。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"所管が違うので、余り細かく聞けないかと思いますけれども、心配なのは、児童虐待、かなりプライバシーのところに突っ込んでいかなければいけないんですね。それが民間委託という前提でいくというのがどうしても私は解せないんですけれども、これ以上突っ込んでもしようがないのですが、そういう心配が実際にはどうなのか。そういうことで何か知っていることがあれば、お伺いいたします。","respondent":"古川人事課長","answer":"民間委託でというご質問ですけれども、全国的に公設支援施設、民間医療法人が、２４時間体制も含めてということでありますと、ほとんどが民間、社会福祉法人で実施しているのが現状です。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"意見","question":"実際にこういうふうになっているから。今回、二葉保育園が増設になるんですけれども、全体で見ると、保母がこの部分が増えるのかどうなのか、どういうふうになっていますか。","respondent":"古川人事課長","answer":"ただいまお尋ねの保育園につきましては、今回増減はございません。さまざまな事業が実施される中で、人事異動等の中でやるというふうに考えております。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、新しく認可保育園をつくるけれども、保母全体を変えないということになると、その中の保育士を変えないということになると、どこから持ってきてそこに充てるか。要するに、ほかのところに影響が出てくるということになるわけですか。","respondent":"古川人事課長","answer":"そういう中で新たな認可保育園に対する従事保育士につきましては、今３７園ありますが、その中での保育士の全体の調整を図りながら、新しい実施園での体制を考えております。基本的には人事異動の中で考えると、こういうふうに考えてあります。","id":"exchange-027"},{"speaker":"三上委員","kind":"質問・要望","question":"そういうことで、そういう再任用制度がどういう仕組みできちっと採用されていくのか、なぜ採用されないのかということについても、ある意味、全然訳がわからないような形で我々も見ているんです。そこのところを簡単でいいですから教えていただきたいと思います。特に組合に関係している方もいらっしゃるので、今までそういう質問が出なかったのでしょうけど、お伺いいたします。","respondent":"古川人事課長","answer":"しかしながら、能力が把握できるであろう場所といいましょうか、それの関係もあります。そういう中で勘案いたしまして、申し込みが６５名という状況でございましたが、最終的に６名不採用ということで、５９名の採用の考えを持っております。","id":"exchange-028"},{"speaker":"三上委員","kind":"意見","question":"そうすると、再任用をお願いしたいと希望する方たちは、基準ということを明確に受け止めた理由ということとしていいですね。","respondent":"古川人事課長","answer":"基本的な採用に当たっての選考基準は、すべての職員に申し込みの時点で明らかにする。採用の経過については、これは具体的に申し上げることはできませんが、採用に当たっての基準は示しております。","id":"exchange-029"},{"speaker":"三上委員","kind":"意見","question":"所属長から一言だけ、だめだったとか、何とかというような、結果があると。採用されなかったとかということで、冷たいじゃないかとかというようなことを、内容がどうだとか、ニュアンス的に私は受け止めたわけですけれども、決してそういうふうな形でその人に対して冷たい扱いをしたということではないというふうに受け止めていいのかな。","respondent":"古川人事課長","answer":"実際の選考の基準に沿って行っており、それから、現に職員を指導課が採っている立場の指導という中で、その状況も聞いているわけですが、所属長の対応できる範囲でそれぞれに対する不採用者については一定の配慮はしているというふうに考えてあります。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問・要望","question":"職員を減らすというのが大前提で、さっきの心配な点は、例えば施設のところのノウハウとか、どうなっているんだろうなというのが心配ですし、また、保育園のほうも、ほかのところから集めると、ほかのところがまた減ってくるということになるわけですから、かなり現場のところも大変だという声があります。減らすというのが前提というのはどうしても納得できない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"内容的なことでなくて申し訳ないんだけれども、第１４号議案の第６条に、「特別の勤務を命ずる」というのがありますね。この、特別な勤務というのと、第１６号議案に特殊勤務手当というのがあります。片方は「特別の勤務」、片方は「特殊勤務」とありますけれども、つまり第１４号議案の「特別な」というのは、何に当たるんですか。","respondent":"古川人事課長","answer":"当然夜間に勤務するわけですけれども、仮眠等のための準備期間、こういうものを保有することはできますよということで、特別の勤務を命ずるというのは、必要な休憩時間を与えることができる、こういうふうになってあります。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"こっちは時間を与える。特殊勤務手当のほうは時間ではなくて、お金を与えるという形なんだけれども、基本的に第１４号のほうに該当する仕事については、手当というのは最初から盛り込んであるんですよという考え方でいいのか、あるいは第１４号議案のほうの特殊勤務というのに、時間を与えていくという、特殊勤務なんだから、時間は必要だというような話にはならないですかね。","respondent":"古川人事課長","answer":"先ほどの特殊勤務手当で申し上げますと、例えば年末年始の勤務等の場合には巡視も該当できるとあります。ですから、本来の業務に付随している報酬的なものは、特殊勤務手当で対応するですけれども、これは時代とともに傾向が変わってきているかと思います。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問・要望","question":"第１６号議案のほうから伺います。特殊勤務手当が改正になっておりますけれども、これは２３区で考え方がばらつきがあるのかどうかということが一つ。それから、平成１２年で１億７,７００万円のところが４０％減となっておりましたが、私は年俸制で表示しろという願いを持っておるんですけれども、それから比べると何％に当たるのか。そのところの削減効果というのをどういうふうに見ているのか。","respondent":"古川人事課長","answer":"これは支給対象となる職場、それから、対象者については年に１回、事前に申請をとり、承認をし、その中でそれぞれの手当の必要性を毎月とるですので、全体としての事務経費としては関係するところを特定してですので、それほどの事務量ではないというふうに考えてあります。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"２３区の中で品川区は先んじて特殊勤務手当を見直しているということです。その特徴といいますか、この部分の考え方があるかもしれませんが、２３区と比較してのところでお話をいただきたいと思います。","respondent":"古川人事課長","answer":"このときは５％減ということで新聞報道されておりますので、４０％は大規模な見直しだったなというふうに考えます。２３区との比較で言いますと、例えば特定危険の関係に対しましても、２３区ではほとんど区が対象としておりますが、これを今回見直したです。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問","question":"そういうことに対する説明の仕方、この報告も、前からこうありますというだけで、大きく労働条件といいますか、税金を払っているほうの労働条件というものをまるっきり見ないで、それを下のほうの働いている労働条件だけがどんどん変わってくる、よくなるということをどういうふうに考えるかという、そこのところが欠けてくると、我々も立場として説明するのに大変厳しい状況に置かれますので。","respondent":"古川人事課長","answer":"私ども民間と国等の感覚の違いを認識し、必要によっては、運用を厳しくしていく必要があると考えます。法制度上は民間を想定した法律が平成１４年４月１日から施行になるです。","id":"exchange-036"},{"speaker":"塚本委員","kind":"意見","question":"ぜひそうしてほしいのと、それから、資格をとるいろいろな制度が、勤めているところでとるわけですけれども、実態はどんなに変わってきている。官のほうの労働条件は良くなっているが、民のほうの労働条件はむしろ悪くなっていると思いますから、従前どおりの比較をとって、それで良しとするようなことがあってはいけないということだけ申し述べておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"土井副委員長","kind":"質問","question":"今お話がありましたように、第１４号議案、第１５号議案は官民そろっての中身ということですから、ご理解を伴うものということで、いかなる労働組合でもこれは賛成するだろうと思うんです。最後に、そういうこともさまざまあったけれども、その状況を労働組合等も理解をされておるというふうに考えてよろしいんですね。","respondent":"古川人事課長","answer":"一つ一つの問題につきましては、いろいろ考え方の相違はあろうかと思いますが、全体の流れとしてはやむを得ないだろう、こういうふうにご説明があったというふうに私は感じております。","id":"exchange-038"},{"speaker":"土井副委員長","kind":"質問","question":"そして今回はどうなるのか、この条例改正したら、そのときに実施するわけですから、それはそれでいいわけですけれども、今どのようになっておりますか。","respondent":"古川人事課長","answer":"この時点でもかなり見直しがされたと考えていますけれども、その後の変化の中でさらなる見直しが今回実施をする。特に見直しに一定の期間があるわけではございませんけれども、社会環境が大きく変化する中で、必要の都度今後とも見直していきたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"土井副委員長","kind":"意見","question":"そう理解されていれば、なかなか立派な解釈をされたところだなと思うのと、逆に、とんでもないけれども、豪腕でやられちゃったんだというだけの話だと話が違うよというところを、ちょっとどのようになっているのかを聞きたい。","respondent":"古川人事課長","answer":"全体としては、先ほど申し上げましたような中で、この部分については明らかに反対であるということではございません。状況の変化についてはある程度認識している、こういうふうに考えてあります。","id":"exchange-040"},{"speaker":"宮崎委員","kind":"確認","question":"確認しておきたいんですけれども、資料の７ページのところでご説明があった、職員の勤務時間、休日、休暇等に関する条例の中で、１回２,０００円というふうになったんですけれども、私どもも仕事をしているときは割り増しと、振り替え休日ということでいたんですけれども、そのときは１.５倍の賃金ということになっておりますけれども、２,０００円というのはどんなものか。","respondent":"古川人事課長","answer":"現時点では２,０００円が相当であろうというに考えてあります。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問・要望","question":"私はそういう労働対価について、どちらかというと、民の立場を感じているところがあるものですから、こういう特殊勤務手当があったのかという、そのこと自体に、いいんじゃないかなと思いました。組合とのいろいろな感情もあると思うんですが、解釈すれば、当然に必要ではないと思いますので、自分の意見だけは述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-04","title":"の第１７号議案、品川区職員住宅資金融資基金条例の一部を改正する条例","agenda":"の第１７号議案、品川区職員住宅資金融資基金条例の一部を改正する条例","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"お伺いしますけれども、区内在住の職員が何名いて、融資が受けられる希望の人がゼロだというのは、私は限りなくゼロに近いんじゃないかと思うのは、そういった条件がいろいろ、もっと安い状況のお金が借りられる、額も大きいということであれば、そちらにいくのは当たり前のことであって、それを改善しない限り、職員の住宅確保ということについては、自分の家を持つのは品川区に住民税を払ってもらうという。","respondent":"古川人事課長","answer":"確かに利用のしやすい条件がありますが、民間部分で相当の部分を補える中で、当然そこには利子補給というものが入ってまいりますから、その必要性はどこまであるかということで、今回全体を見渡す中で、休止という一定の考え方をしたものです。","id":"exchange-043"},{"speaker":"三上委員","kind":"意見","question":"しかし、職員の定住策ということをどう考えるのか、これについての基本的な考え方を区当局も考えていかなければならないんじゃないかなと思うんです。助役を含めて、品川区内に住んでいる職員は何人いらっしゃるのか。そういう実態を考えたときに、将来、若い人たちが品川区に居を構えられるという、そういったことの選択というものをどう考えるのかということも考えていってもらいたいと思うんです。","respondent":"古川人事課長","answer":"答弁漏れがございまして、職員の区内在住者はどのくらいかというお尋ねですけれども、平成１３年３月時点で１,２６１名、全体が３,３１３人ですので、率から申し上げますと約３０％です。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"質問","question":"たしかこれは職員住宅資金融資の審議会があったと思うんですけれども、こういうところではどういうふうな意見になっているかというと、一番利用されない理由というのは、おそらく利子が高いというところにあるんじゃないかなというふうに想像するんですけれども、区のほうとしては、借りられない原因はどういうふうに考えているのか、そこのところはどうでしょうか。","respondent":"古川人事課長","answer":"そうした中では品川区の７００万円というのは低くはない。こういう中で、しかも利用者がいないという中で、２億数千万円基金として継続する意味は非常に薄い。こういう環境の中で今回休止ということを通じて、基金については、貸付残高に見合った額にするです。","id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど審議会で、希望があったときにいろいろ条件を審議する会というのがあったと思うんですけれども、そこで、問題点というか、指摘されていたんでしょうか。","respondent":"古川人事課長","answer":"融資あっ旋に当たって、審査会が、活用の必要性、あるいは額が妥当であるかどうか、そういったものを審査する機関として設けてあります。平成１２年度、平成１３年度、予算で１回計上いたしましたが、あっ旋件数は０でございましたので、この状況についてのご説明をいたしました。","id":"exchange-046"},{"speaker":"北野委員","kind":"意見","question":"第５条のところに、新たに処分ということをうたっている意味というのは、そこをどういうふうに考えておられるのか。","respondent":"古川人事課長","answer":"今回、基金の額については、予算で定めるですけれども、予算で定める前提が、貸付残高に対する一定の担保という意味合いがありますので、８分の１相当額を納める。","id":"exchange-047"},{"speaker":"北野委員","kind":"質問","question":"そうすると、年々少なくなっていってしまうということというのはありますね。なくなってきたらば、結局廃止ということになるんでしょうか。私自身も、休止ということでは良しとするんですけれども、品川区での定住というところを考えたらば、やはり早過ぎるというんですか、８分の１あれば、増えていけば借りられる金額というのが８倍借りられるということに、原資というんですか、なるんですか。","respondent":"古川人事課長","answer":"預託額の８割相当額を融資の上限ということで定めて、昭和５３年度から制度を、若干改正はございましたけれども、行ってまいりました。現在、融資額の残高が５億１,３００万円以上あります。","id":"exchange-048"},{"speaker":"北野委員","kind":"質問・要望","question":"休止ということは、景気動向が変わっていくんだから、利息がまた上がってきて、先が見えない状態でありますけれども、そのときにはまた復活ということもあり得るんですよね。だから、処分というところでは、ある程度分かりましたけれども、休止というところの時点は先は見えませんけれども、制度は継続していただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"需要がまだないということから、有効に活用するという点ではいいんですが、将来、金融動向が変わった際に、またこれを復活するときの足かせといいますか、本来だと、すぐ復活させたいところが、一般会計に回ってしまったがために、すぐには復活できないなどというようなことが将来的に起こり得るのかどうか、その辺は想定されているのかどうかということをお伺いしたいと思います。","respondent":"古川人事課長、市岡企画財政課長","answer":"現時点では、休止という意味合いは、貸付残高に対します一定の有効利用の問題があります。この制度を復活することは不可能です。廃止を前提に考えているわけではございませんが、休止、廃止を前提に検討を加えていたところです。これは、先ほど来出ているとおり、金融情勢ないしは住宅をめぐる社会情勢が変わったときに、新たな施策として、職員の住宅資金融資あっ旋を再開するということになれば、これはその時点での経済、社会情勢に合った形で。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の金融情勢にふさわしい対応をされたと思いますので、また逆に、休止を決める、復活をするという際も、それが新しい制度になるということで、金融情勢に対する早急な対応をしていただきたいと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"土井副委員長","kind":"質問","question":"もう一つは、基金条例という形での貸し付けの問題については、ここでお休みになるんですけれども、問題は、先ほどどなたかのお話があったように、職員の皆さんが住宅を持ちたいとか、買いたいとかというので、いろいろなご相談をする窓口は休止されては困るので、そこはきちっと、そういうパターンのものがどういうところでやったらいいのかわかりませんけれども。","respondent":"古川人事課長","answer":"広く２３区の中では、区の共済あるいは都の共済、こういう制度をさまざまな角度から検討をしながら、対応しております。そういう意味では、まさに窓口については、職員の相談にはいろいろな形でやってまいりたいというふうに考えてあります。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問","question":"今日は、前副理事長、事務局長が来るのかなというふうに思ったんですけれども、今後、その機会というのはできるんでしょうか。これはお願いしておきたいなと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"意見","question":"今後の推移を見てということなので、期待をしておきたいと思います。この事実経過のところでは、財産運用による収入が低迷していて、有利な資金運用を図るためということだったんですけれども、例えばこれだったら何で黙ってやったのか、そういうことなどが不思議でしようがないんですけれども、そこのところが何でアルゼンチン国債をしたのかというところが、ここからだと見えないんですね。","respondent":"中尾根企画部長","answer":"したがいまして、今まで中国ファンドでやるか、公社債投信等の活用を十分していたんですけれども、さらにという考え方があったということです。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問","question":"アルゼンチンの国について、新聞報道などでもあまり出ていない、全くの言い逃れの方便としか聞こえないんです。資料１７ですけれども、アルゼンチン共和国債、これは銘柄ですね。元金や、実効期間、このときはどういうふうにこれを認識していたのか。アルゼンチンの国が歴史があるとか、ないとかでなくて、ここのところはどういうふうに認識したんでしょうか。","respondent":"中尾根企画部長","answer":"そしてそういう区民のサービスを提供するものとして寄与してきた立場からすると、少なくともより有利な運用資産をというふうに純粋に考えられたというふうに私どもは受け止めております。","id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問","question":"ほかのも事務局長決裁でやっているからいいんだというふうなお話ですけれども、庶務規程のほうでも明確にこうなっているわけですね。だから、よかれと思ったとか、そういうふうな論調なんですよね。よかれと思ったということであれば、何で全体に諮らなかったんだと。そこのところは言っているんですか。","respondent":"中尾根企画部長","answer":"だからこそ一番問題で、この手続き違反は明確だと、このように調査会としては指摘させていただいているということですので、そのようにお答えいたします。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問","question":"何とも気の重いことでございまして、疑問は山ほどあるわけですけれども、考え方を確定しておかないとややこしいことになると思います。そういう立場で対応しようと考えていますけれども、最初に伺いたいのは、財産管理調査会というものの権限、先ほどちょっと触れられましたけれども、どういう権限でもって調べているのかということをもう一回はっきりとお知らせ願いたい。","respondent":"中尾根企画部長","answer":"前項の場合において、必要があるときは、普通地方公共団体の長は当該普通地方公共団体の区域内の公共的団体を通して事務の報告をさせ、書類および帳簿を提出させ、および実施について事務をさせることができる。こういう規定があります。","id":"exchange-057"},{"speaker":"塚本委員","kind":"意見","question":"調査の提言がそういうふうに根拠があるということですが、調査して、改善を命令できるか、あるいはそういう権限があるというのと裏腹に、責任があるからそういうことができるんだということになると思うんですけれども、そういうことに関してはどういうふうに考えられているのか。そういうことの報告があまりないんですね。その件に関して。","respondent":"中尾根企画部長","answer":"第１点目の、法的な関係ですけれども、まずは区としては補助金等も出しているわけですから、そういう事実に対してどうなのかというのを正確に把握をして、その関係でどうかと判断するためにも、やはり調査が必要という考えですから、もともとそこに犯罪があるとか。","id":"exchange-058"},{"speaker":"塚本委員","kind":"確認","question":"財団がどういう行動を起こしたかということは全然見えていないんですね。理事会がこの間２回あったと思うんですけれども、２回の理事会の様子はどのようであったかと、理事会がどういうふうに展開していったのか。だれが理事会を承知しておって、どういう対応をとったのかということに関して、本来、財団が調査して、理事会の中で確認をしなければいけないと思うんです。","respondent":"中尾根企画部長","answer":"それで、今回の経過の中で、これは財団内部の財産運用の問題ということで認識は出発しておりますが、そのことについて財団内部の中で、このことを受け止めてどうしていくのか、責任も含めて決定していくべきというふうに受け止めておりますが、先ほど言いましたように、補助金。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところと、私どもが情報公開でもらった資料で、平成１２年６月２日の理事会の議事録で、質疑があって、その中身が書いてあるんですけれども、ある理事が財産の流動資産の中ではＮＮＦが金利が非常に安いと。ほかの金利がいいのでやったらどうかというふうな質問があるんです。これは平成１２年６月２日の理事会ですけれども、すでにこのときに買っているんですね。平成１２年６月２日の議事録なんです。","respondent":"中尾根企画部長","answer":"要するに、現実的には、「債券」と表現したり、「国債」という表現をしたりしているということが実態で、そういう認識にあったという報告は受けてあります。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問","question":"そういう中身論で、本当のところはどうなんだというのが全くわからないんです。例えばさっきの理事会の議事録で、「さらに安全、確実、有利なもの」というふうに言っているんです。そこのところで、今回は、事務局長の決裁というふうになっているんですけれども、そのときの前副理事長の、当時の事務局長に対しての指示はどういうふうなのがあったんですか。","respondent":"中尾根企画部長","answer":"私は会議録は見ておりませんけれども、もしそういうふうにあったとしても、現事務局長がそういう認識で資金を運用するんだということを述べたにすぎないんだというふうに思っております。","id":"exchange-061"},{"speaker":"宮崎委員","kind":"確認","question":"先ほど矛盾ないんだというふうなお話だったんですけれども、とんでもないと思うんです。確認書のところにもＤＢＢまたはＢＡＡ、以上の債券に比べてデフォルトのリスクが高いんだというふうに言っているんですよ。何で矛盾しないんですか。何で安全、確実なんですか。当時これだけの危ないという資料がありながら、それでも問題ないということなんですか。","respondent":"中尾根企画部長","answer":"今、議事録を読ませていただきましたけれども、ある理事から、「財産目録の流動資産の中にはＭＦは金利が非常に低いので、金利のよい国債を検討されたらどうか」というご質問です。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"質問","question":"私が言っているのは、事務局長は、「安全、確実、有利なもの」という、これをこのままやっていたら、デフォルトのリスクが高いよということを、買ったのかということですよ。言っているのをそのまま当てれば、こんな事態にならないんじゃないですか。安全、確実、有利なものと、口で言っているのと、やっていることが違うでしょう。そうじゃないんですか。","respondent":"濱野助役","answer":"ＭＭＦは利率が低いから、もっと有利な運用をしたらどうかという質問に対する答えだということを認識していただきたいと思います。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"それは全くの言い逃れの、私は詭弁にしか聞こえないですよ。安全、確実、有利と言いながら、デフォルトのリスクが高いということですからね。これは全く言っていることと矛盾している。アルゼンチン債も問題ないんですか、私はアルゼンチン債が、こんなことでなかったら、これから外国債をどんどん買いますよと。今でもアルゼンチン債を購入したということは全然問題ないというふうな認識なんですか。","respondent":"中尾根企画部長","answer":"ただ、結果としてアルゼンチン債というものがこういうふうになって、これがよかったのか、悪かったのかと言われれば、結果としてこういうことに結びついていったことを、今遡っていいという言うわけにはいかないわけでして、そういう意味では、そのときの判断は。","id":"exchange-064"},{"speaker":"土井副委員長","kind":"意見","question":"ここがなぜこんな形のものが決まっているのか、何でこんな形しか決まっていないのかという、どちらも、どう言うべきか、問題があるんですけれども、要するに、その中での公務員、もしくはそれを心がけた皆さんが、そういうところできちっと買わないと決めていれば、買わないんですね。相矛盾をする中身のものが書かれているわけです。","respondent":"中尾根企画部長","answer":"そういうふうに自主的な運営ということになると、区ないしは地方公共団体、国との関係の中で、財政も含めてかなり独立したというものにならないと、いろいろ自主的な運営というものの確保はできない。しかしながら、まるっきり株式会社と同じように、自分たち独立ではできない。","id":"exchange-065"},{"speaker":"土井副委員長","kind":"意見","question":"したがって、変な意味での拘束力みたいな、なぜこんな形のものしかなのかという部分が、聞くところによると、これ自体もさまざまなそういう状況の中で各省庁等々の引き合い、押し合いの中からこんな形にしかまとめ得なかったという、政府内の動きがあっての話だというようにも聞いているんですけれども、それがやはりある意味では一つの遠因というか。","respondent":"中尾根企画部長","answer":"それを統一する形として、したがって、ここの冒頭に書いてありますように、関係閣僚会議、幹事会申し合わせという、そういう申し合わせ事項で統一基準をつくったという性格そのものの中に。","id":"exchange-066"},{"speaker":"北野委員","kind":"質問","question":"指針というものは、判断の一つとなるんですけれども、投資についての考え方というんですか、それはそれぞれ違うであろうし、問題の指摘のようなものもそれぞれの考え方があると思うんですけれども、投資についての考え方というのは、その当時はリスクがあっても、妥当だということで考えてこられたと思いますけれども、今後はどういうふうな形で考えていかれるんでしょうか。","respondent":"中尾根企画部長","answer":"投資についての考え方ですけれども、これは財団が運用する判断ですので、本来あるべきなのは、理事長がちゃんと提案をして、理事会もそのことについて同意をし、評議員会もそういうことを指示していくという関係の中で。","id":"exchange-067"},{"speaker":"北野委員","kind":"質問","question":"今までの話の流れの中で、指針がすごく問題になっていますね。確かにこれがあるから問題だというのは分かります。しかし、これがあるからこそ投資に対しての判断が本当に判断されてやられたのかなというところの疑問が残るんですね。結構個人的な見解というか、そういう部分も多く含まれているようなところもあるように感じるんですけれども、その点については調査の中からどういうふうにお考えでしょうか。","respondent":"中尾根企画部長","answer":"ただし、運用の仕方、ないしはそういう判断そのものについてはいろいろ問題があるし、特に決められた手続き違反は明白であるのでということを指摘をしているということでございまして、そういう姿勢の中で調査の結果をまとめてありますので。","id":"exchange-068"},{"speaker":"北野委員","kind":"質問・要望","question":"品川区の中では、アルゼンチン債が１億６,０００万円ということですけれども、他の自治体でもあるわけですね。そしてまた、アルゼンチンのほうの現状もアメリカが経済を見ていて支援すると報道されているのですけれども、そういう面でどういう動向かというのが分かったら教えていただきたい。","respondent":"市岡企画財政課長","answer":"これは新聞報道等の情報ですけれども、日本全体で額面で約１,９００億円ぐらいのアルゼンチン債が販売されたということがございました。","id":"exchange-069"},{"speaker":"北野委員","kind":"質問","question":"アルゼンチン債の保有期間というのが、平成１５年と１７年ということで、まだありますね。そういう中ではまだ現状のまま現在は進めていく、世界の動向も含めて、このまま持っているというままなんですか。","respondent":"中尾根企画部長","answer":"その点に関して私のほうもどうなのかと考えています。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"大まかな、いつ頃から日本に売りにきて、どの幹事会社にというようなことを、今日でなくてもいいですから、予算特別委員会での審査の過程もあるわけですから、その時点で分かるようにしていただきたい。この背景に、売り手側のほうの証券会社と言ってしまえばそれでおしまいですから、責任をとらない。だから確認書を取るということだというもの。この辺は今でも分かりますか。","respondent":"中尾根企画部長","answer":"それと、アルゼンチン債の格付けというところにまた帰着するということですけれども、その当時いろいろメニューがありましたが、国内でのいろいろな、言ってみれば、区債も含めまして、現在都債なども持っておりますけれども、それから、国債、そういったことの幅広い検討はした。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問・要望","question":"どうしてアルゼンチン債の残高が生じているかということ、判断が適当であるかどうかという点に非常に関心の的があるわけです。その判断の材料がどこにあったかということを知りたい。これは別に不都合な話でないわけですから、その当時どういう保管があった、証券会社でなくても、その当時の資料を調べれば出てくる話ですから、それを調べていただきたいと思います。","respondent":"中尾根企画部長","answer":"現実的に今委員の質問された点については、私どもも資料を持ってお答えできるものがありませんので、この点については、購入して分かる範囲で調査をさせていただきたい。分かった時点で、先ほどの１,９００億円のアルゼンチン債の問題と一緒に提出させていただきたいと思います。","id":"exchange-072"},{"speaker":"林（宏）委員","kind":"質問","question":"基本的なところからお聞きしていきたいんだけれども、出資してある基本財産と、運用資金と、ファンドになるのは２種類あるということで、出資した基本財産は元本は使えないわけですね。さっきお金の流れの表があって、１億円からプラス２億円して３億円になって、元利を増やしていったわけですね。当時２,８００万円から、３年ぐらいは２,０００万円を超えるものを果実が生まれていたということであった。","respondent":"濱野助役","answer":"先ほどの話にもありましたように、平成１０年度でしたか、たしか予算にもかなり満たなかったということがあって、かなりの利回りのいいものを運用しなければ予算額も獲得できないというようなことがあって、こういう高利の利回りの債券を購入したのではないか。","id":"exchange-073"},{"speaker":"林（宏）委員","kind":"意見","question":"片方で、充実していくにはお金が必要だと。そうすると、今言ったように、４００万円とか５００万円では足りないんだと。さっき言ったように、１０年前は２,０００万円からのものが生まれていたわけです。５億円で２,０００万円というと４％ぐらい必要になってくるわけですね。だから、そのぐらいのものは生むように努力せよという話が、区から財団のほうに伝わっていたということはありませんか。","respondent":"中尾根企画部長","answer":"毎年の予算につきましては、まずは補助金の事業との関係、委託金、きゅりあんのお金をどれだけやるのか、特に補助金の関係では人件費が相当部分を占めていますから、そういった事務的な、投資のかかる経常的なもの等で財団との間で毎年ヒアリングをやっておりますけれども。","id":"exchange-074"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、補助金が０になってはやっていけないという中で、自主、独立をせえよということになると、財源はどこからといったら、寄附だけど、このご時世で毎年寄附が望めないわけです。そうすると、つくり出していく財源といったらファンドしかない。自主、独立に向けての活動、行動をするには。そのような議論はされないんですか。予算をつくったり、決算をしたときに。","respondent":"中尾根企画部長","answer":"ただし、今指摘のように、だから、こういう割合でいきましょう、ここのところに抵触したらどうだとか、こういうルールは明確に持っていませんで、実態の中での把握をお互いにはしていて、認識はしておりましたけれども、こうなければならない。","id":"exchange-075"},{"speaker":"林（宏）委員","kind":"質問","question":"角度を変えて聞きます。ファンドの財産運用をすることができる人は、どの役職の人ですか、寄附行為や処務規程にも出てこないんだけれども、だれができるということになっておりますか。","respondent":"中尾根企画部長","answer":"契約の規定については、先ほど言いましたように、事務処理規程がありまして、事務処理規程の別表によりますと、理事長、事務局長、課長、決定権はこの３人しかございません。","id":"exchange-076"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、さっきも言ったように、ファンドから生まれてくる回数が非常に重要な自主財源だと。そうすると、財産運用についてのチームというのはないんですか。５％だ、６％だ」、個人ができる仕組みになっている場合、もちろん理事会を通すという一つの決まりはあるけれども、運用の考え方は個人で決めていけるということですか。","respondent":"中尾根企画部長","answer":"したがいまして、そういう意味からすると、全体の意思をどこで諮っているのかは不明朗ですし、そういうチェック機能を持つために、もともと理事会なり評議員会があるものの、その機能も全く発揮しないでいるという問題点が浮かび上がってくるということで、本来、財団として。","id":"exchange-077"},{"speaker":"林（宏）委員","kind":"質問","question":"制度は分かる。例えば定期的に１週間に一遍、これだけのお金を動かすわけですからね。先ほど塚本委員からも出た、どういうものが出回っている、どのぐらいのリスクがあり、どのぐらいの運用益が生まれる、そんなようなものを相談して運用すると思うんです。個人の１人の発案で、こっちが高いから、こっちにと。これだけのお金を動かすのに、どういう方法を用いてきたかというのは、毎年やるべきだ。","respondent":"中尾根企画部長","answer":"それは実際上そういうふうにやって、この寄附行為どおりに事務をやるとどういうことになるかというと、大口定期だとしても、満期がきて、月を替えて、それを継続しようと、ほかの銀行にやろうと、理事会に諮れということになるんです。","id":"exchange-078"},{"speaker":"林（宏）委員","kind":"意見","question":"一つ考えられるのは、もちろん寄附行為は決められている、国の指針に決められているということで、理事会を通して、国の算定基準、あるいは運用する前に理事会の承認をもらうという形ができているけれども、極論からすると、この４億７,０００万円は区の金なんです。財団を閉じるときは引き揚げるわけです。もう一回きちんと見直していくということの決意みたいなものを聞かしてほしい。","respondent":"濱野助役","answer":"これは今回の調査の中で明らかになりましたし、今後はそういう意味では、４ページの２番にもありますように、区の財団の資金運用について報告を継続的に求める、あるいは出捐金の用途についてチェックしていくということが必要だと言っております。","id":"exchange-079"},{"speaker":"三上委員","kind":"質問・要望","question":"だから、ご本人が認めているように、独断でやり始めたというのは、前助役が初めてなのか、それ以前からもそういう形はあったのか、そこらあたりについても、流れというものが、継続されてきているわけですから、前助役の時代に始まったということであれば、それはまた考え方が変わってくると思いますけれども、そこらあたりのところをお聞かせいただきたいんです。","respondent":"濱野助役","answer":"資金運用の決裁の関係であります。これは財団設立のときは、すでに預金がされていないと登記できないという仕組みでありますから、理事会を開催する前に預金として適正金が入っていて、そして登記をして理事会を開くというような手順だったのではないかなと思います。","id":"exchange-080"},{"speaker":"三上委員","kind":"質問","question":"今まで品川区の指導ということもありましたけれども、この件に関しての所管施設は東京都ですよね。とすると、現段階にあって、東京都とのやりとりというのは、品川区がやっているのか、財団がやっているのか。それについてのどの程度東京都から是正命令、指導とか、そういう部分というのはすでにガンガンきている部分というのはあるんですか。","respondent":"中尾根企画部長","answer":"今回のことについて、監督官庁の都の教育庁のほうから、事実はどうなのかという事情聴取がございまして、それについてお答えはしていますが、その関係について改めて調査をしたいということの向こうから申し出がありまして、明日、財団のほうに行かれて。","id":"exchange-081"},{"speaker":"三上委員","kind":"質問","question":"今回のアルゼンチン債に１億６,０００万円の、しばらくの間果実が生み出されないですね。凍結された以上は。狂ってくるということになるのかどうか。新年度予算をやっている、理事会で検討したんでしょうけれども、そこらあたりが修正されているのかどうかわかりませんけれども、そこらあたりの動きというのはどうなんでしょうか。１年間の事業団の事業の影響というのは当然起きてくるだろうと思うんです。","respondent":"濱野助役","answer":"これに見合って、例えば今までかなりお金をかけておりましたゴアというパンフレットのような募集の冊子がありますけれども、そういうものを中止をするとか、幾つかそれに対応する事業の縮小なり、あるいは仕事の縮小というのは、予算の中で出ております。","id":"exchange-082"},{"speaker":"三上委員","kind":"意見","question":"そこらあたりの問題として、改めて品川区の補助金という部分で、そういう部分が賄われるという形になるとまた困るので、それだけははっきりしておいてもらわなければならないと思います。あくまでもマイナスはマイナスという中から、事業運営をやらないんだと。区民の理解は得られていくわけはないと私は思っておりますので、その点よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"宮崎委員","kind":"質問","question":"報告書を見て、わからないのが、前副理事長、事務局長が、そのときにどういうふうな判断をしたのか、それが全くないですね。私はこの前も話しましたけれども、危険を承知だったのにあえて買ったわけですね。もう一つは、財産管理調査会として、理事長、副理事長、事務局長、当事者の調査はどういう形でやられたのか、ここのところを改めてお聞きしたいと思います。","respondent":"中尾根企画部長","answer":"うしろのほうの、どういう形で調査したのかですけれども、４人の中で分担できるものは分担したり、一緒にやるところは一緒にしたというようなことで、効率的にやろうということでやりました。","id":"exchange-084"},{"speaker":"宮崎委員","kind":"意見","question":"例えば事実経過のところで、より有利な資金運用を図るためというふうに言っておりますけれども、図ることをしなければいけなかったというのは、どういうふうに言っていますか。","respondent":"中尾根企画部長","answer":"それは先ほどもこの資料の一番うしろについておりました、今までの基本財産の運用は、平成七、八年頃から極端に少なくなって、設立当時よりも財産運用の足を引っ張って、きつくなった。そのことを認識されているんだというふうに思ってあります。","id":"exchange-085"},{"speaker":"宮崎委員","kind":"意見","question":"区と、財団との関係で、例えば事務事業評価についていえばスポーツ協会も同じ財団法人でやっていますけれども、この見直し、Ｃのところで、一番最初に、自己評価のところで書いてあるんだけれども、基本財産の運用益が低金利で見込めないということで、そういうことで、もっと工夫をしなければいけないというふうに書いてあるんです。そこのところは何か言っていますか。","respondent":"濱野助役","answer":"それは利子が稼げなければ、その分の自主的な事業は縮小せざるを得ませんし、ですから、基本財産収入が減った、したがって，区のほうが補助金を云々という、そういう関係にはないというふうに思っております。","id":"exchange-086"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私、そこのところが一つの背景になっているんじゃないかと思うんですけれども、そこのところはどういうふうに感じているのか。当事者、前副理事長と証券会社の方との間の話というのもここには書いてないんですけれども、先ほどのマージンの差額の問題が出ておりましたけれども、ここのところは調査されたのかどうか。そこのところをお聞かせいただきたいと思います。","respondent":"中尾根企画部長","answer":"ただ、それはお聞きして、そういうことには確認をしただけで、別に司法でもないですから、どうだというそれ以上の調査はできません。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"私は推測としては、南米も経済危機というのが平成１１年頃から起きていて、以降ブラジルは相当な通貨危機を受けたんですが、アルゼンチンは、その時点は持ち直しましたが、それ以降徐々に悪くなって、平成１３年度では経済成長率マイナス１１％というような状態になっている中で、よりデフォルト、その前はモラトリアムと言って、一時支払い猶予というような状態に徐々に近づいている時期がこの頃で。","respondent":"中尾根企画部長","answer":"前段３点のご質問につきましては、私どももそういうふうに受け止めて、今後対応をしてまいりたいと思います。最後の部分の付け替えのいきさつの件ですけれども、平成１２年冬に副理事長が知りまして、それから年が明けて春に理事長に報告をした。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問","question":"平成１３年に景気がさらに悪化して、２３日には一時支払い停止で、２７日の報道で、その前なのかもしれませんが、デフォルト、債務不履行の状態に陥った時点で、今回ご報告をいただいている調査会を発足させているということですが、そういう意味では十分危機感が募り始めているのが分かった時点で、８月８日の付け替えの作業を行いながらも、徹底的にデフォルトとなるまで、逆に言うと。","respondent":"濱野助役","answer":"その後、秋から比較的値は戻しております。一時、米国のテロがあって、米国の支援が難しくなるんじゃないかというようなこともあって、乱高下はしておりますけれども、秋口になって戻ってきていたこと。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"調査会の報告を見する中で、１点だけ気になることがあるんですけれども、事実経過の1)の、その後、平成１３年春頃から国際的経済事情に変化が出始めたため、機会を見ながら、アルゼンチン債等の処分をしたということですが、ここで言う「機会を見ながら」という意味が、いろいろな捉え方ができるんですが、これはどういうことなんでしょうか。","respondent":"中尾根企画部長","answer":"先ほど副理事長である助役がご説明しましたとおり、相場のそういう関係の中では、かなり割り込んでいる状況の中ではできない。しかしながら、乱高下をしている。よく見守って、元に戻すチャンスがあるなら、それをやりなさいと。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問","question":"値がつきずらい状態になってしまっただろうと思うんですが、この機会を見る意味合いが、いろいろな見方があったんでしょうが、７月のこういう時点が起きる前に値が付けば幸いだったかと思うんですけれども、逆に、機会を見過ぎてしまったがために、７月の事件が起きた後の処理にならざるを得なかったということはどうなのか、その辺はどうでしょうか。","respondent":"濱野助役","answer":"元本と利息を足して、何とか元本をオーバーになる時点というのは、何とかそういうことが見出せないだろうかということで見守ってきたわけですが、結果としては、１２月に突然暴動が起きなければというようなことでもって、デフォルトになりましたけれども。","id":"exchange-091"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう判断を８月８日の時点でしたと。その答えはちょっと説明不足。もう一度基本的にどういう展開であったのか、基本財産というものはどういうところで、こうあるべきだとされたのか。現実問題、穴があくのは同じなんですから、そういうことに影響するだろうというふうに私どもは考えておりますので、その行為の、どういう考え方でやったんだということをもう一度説明していただきたいと思います。","respondent":"濱野助役","answer":"しかしながら、その後の値動きの状態からすると、基本財産としておくにはふさわしくないということを判断して、運用財産に切り替えたです。これはご納得いただけないということについては、私どもこれ以上ご説明のしようがないんですが、そういう理由で付け替えたです。","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"基本的に財団というのは、通常こういうような考え方で財産を運用し、あるいは事業を運営して利益を上げることを目的としていないわけですから、使用料を取って、何ほどかの事業をやっているということ、そういうスタンダードから、この財団は、区が大きく関与していることにおいてどれだけずれているのかという、そういうことが知りたい。それから、もう１点は、運用の果実があまりにも過大。","respondent":"中尾根企画部長","answer":"したがいまして、運用基準の中でも、基本財産およびその他は全部運用財産という言い方をしております。したがいまして、基本財産は、その財団、事業団の存続する一番基本的な財産であるという認識があります。寄附行為の中でもどういうものかと決められてあります。","id":"exchange-093"},{"speaker":"塚本委員","kind":"意見","question":"そこのところについて心配している。つまり、単純であったのではないかという心配がある。今答えなくていいですけれども、まだ明日もありますし、最後に、財団の運用というものの改善策の中で、その辺が課題ではないかというふうに思いますけれども、指摘をしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"宮崎委員","kind":"質問・要望","question":"特に格付けということも含めて、だれが知っていたのかということをお聞きしたいと思います。ついでに、助役のところでは、事務局長から報告がいったというふうなことを伝え聞いているんですけれども、助役がいつ知ったのか、理事長である区長にいつ報告をしたのか、それを知って、どういうふうな対応をしたのか、そこら辺の事実関係を教えていただきたいと思います。","respondent":"中尾根企画部長","answer":"これは１０月に交代しておりまして、その冬に事業団のほうからいろいろ説明されたときに、その問題も実は抱え込んだということで、報告があって、知ったということです。","id":"exchange-095"},{"speaker":"宮崎委員","kind":"質問","question":"今の内部監査のほうに絞って聞きたいんですけれども、平成１２年のときは見過ごしたというご説明があったんですけれども、平成１３年になると証券会社からの書類が添付されていたから気がついたと。そうすると、平成１２年のときには証券会社からの書類が添付されなかったということですか。","respondent":"中尾根企画部長","answer":"特段に説明もなかったために、監査として分からなかったです。","id":"exchange-096"},{"speaker":"宮崎委員","kind":"確認","question":"確認したいんですけれども、平成１２年のときには書類が添付されていなかったというのは、債券そのものも添付されていなかったということですか。例えば資料の１７ページのアルゼンチン共和国債、これはＢ１とＢ２だよという格付けがあるということですけれども、債券はあったけれども、格付けというのはなかったのか、それとも債券そのものもなかったのか、どっちですか。","respondent":"中尾根企画部長","answer":"したがいまして、このような、１年後の社債登録簿登録証明願というのが次の年にはちゃんと付けて、これは監査のほうに出してありますけれども、そういう行為もそのときにはされていなかったということで、財団側の対応についても、そのことについて問題がありますし。","id":"exchange-097"},{"speaker":"宮崎委員","kind":"確認","question":"驚くような経過だなというふうに思ったんですけれども、それはそれで別に確認したいんですけれども、先ほど助役は、平成１２年の冬に知ったと。実際に知ったのはいつなのか。単に報告したというんですけれども、報告したのはいつだったのか。","respondent":"濱野助役","answer":"これについて財産運用をどういうふうにしたらいいのかということで、事務局長から相談を受けて、従前は高利回りのものを運用するというのが方針であったんだけれどもということで、やはり安全が第一ではないかということで、２月の時点でのものは。","id":"exchange-098"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどアルゼンチンの国情についての、前副理事長はどういうふうに考えているかと質問をしたんですけれども、同じ質問で、助役は、当時はどういうふうにお考えになっておりましたか。","respondent":"濱野助役","answer":"値動き等につきましても、担保割れをしている状態が、かなりすれすれの状態ということだと思いますが、続いておりますので、これは満期到来まで持つのは難しいということで、一定の機会を捉えて処分すべきだという判断で、理事長に報告をしたところです。","id":"exchange-099"},{"speaker":"土井副委員長","kind":"質問","question":"例えば寄附行為の第７条には書いてあるけれども、だけども、これはこういう運用をするんですよという、また別な庶務規程と同じようなものがあれば、それに従って具体的にやっていくという形になるんじゃなかろうかと思うんですけれども、東京都の指導とかという形の中では、建前でなかったらだめだと言うに決まっているのが東京都のやり方だろうと思うんだけれども。","respondent":"中尾根企画部長","answer":"定款の寄附行為の変更ということについては、事業団独自には意思決定は、たとえしてもできませんで、監督官庁が許可しなければできないということですので、今後そういう点について、どうしたらそういうことについてより良い会計処理方法があるのか検討はしてまいりますけれども。","id":"exchange-100"},{"speaker":"林（宏）委員","kind":"質問","question":"今日のところは、皆さんからそれぞれ質疑があったわけですが、さらに続ける場合には、一般質問のフォローという手法もあると思いますが、委員長の運営のしかたにおまかせします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/891081?Template=document&Id=1572#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":93286,"voices":250}},{"id":"h14-20020305-6","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"区民委員会","time":"午前１０時０８分～午後２時２０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"金高委員","kind":"質問","question":"炉のことなんですけれども、説明だと、当初８基ですか。一つスペースがあいているのは、増設するからということなんですけれども、なぜあけておいたんですか。どうせつくるんなら、一緒につくってしまったほうが、需要の問題点も含めてと思うんですけれども、その辺はどうなんでしょうか。","respondent":"宮地区民課長","answer":"炉の数ですが、当初の予定で、人口の予測、それから、高齢化率等を換算しまして、５区の需要等の中では、当分の間、８基でいけるということです。さらにまた先のことを考えますと、どうしても増設はやむを得ないだろうということです。","id":"exchange-001"},{"speaker":"金高委員","kind":"意見","question":"待合室が８室になっていますけれども、増設したら、全部で１０になりますね。そうなったときに、時間調整をしながら使うんでしょうけれども、その辺のところの見通しというのはどんなもんなんでしょうね。","respondent":"宮地区民課長","answer":"２階の平面図の左下のほうに、待合室９というのがあるんです。ちょっと見づらいんですけれども、階段のさらに上のほうにスペースを取ってあります。ピクチャーレールと書いてある下のところに、待合室９と書いてあります。","id":"exchange-002"},{"speaker":"原委員","kind":"意見","question":"先ほど、交通アクセスで、バスのお話を聞かせていただいたんですけれども、こちらが環状７号線ですよね。乗用車で行った場合は、どういう形で入れるのか。大森のほうから行った場合に左折して、あるいは、品川のほうから行ったときには右折してとなると思うんですね。","respondent":"小栗区民生活事業部長","answer":"もう一つは、第一京浜と環状７号線の交差点を通りますと、こっち側に来まして、このまま行きまして、この先のところで左折できますから、水道局と港湾局の縁を通りまして、入っていただく。こういうルートが一般的なルートかと思います。","id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"そうすると、大森のほうから、環状７号線で勝島橋のほうから入ってきて、左折できないんですか。","respondent":"小栗区民生活事業部長","answer":"環状７号線のところを切れないかという交渉をしましたところ、近距離なんで、間が切れないということで、どうしてもできないということです。こちらから入ってきたときには、やむを得ず、１回迂回をしていただくというルートになりますので、ご了解いただきたいと思います。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"今のアクセスですが、じゃあ、敷地内にバス停をつくるんですか、今の話だと。","respondent":"宮地区民課長","answer":"ただ、増発のほうは、何とか調整の余地があると聞いています。この真ん前につくるというのは、ちょっと難しいんではないかと、事務局のほうでは、そう話しております。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"この道路でも、こっちの道路でもどちらでもいいんですが、これは何も品川区だけじゃなくて、５区全部から来る。特に我々は近接地ですから、場所をよく知っていますけど、今回、もしつくってもらわないと、スタジアムのほうのバス停では遠くから来た人は困るんじゃないですか。今のコースで、ちょっと中に入ってもらえばいいだけのことなんだから、そういうことはできないんですかね。","respondent":"宮地区民課長","answer":"ただ、今までのやり取りの中のニュアンスで聞いていますと、新バス停は難しいということと、今あるバス停の中での増発と伺っています。もう一遍、そのあたりの話がどういうふうになっているか、皆様のご意見をまとめまして、伝えるようにいたします。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"当然、どのぐらいの人が利用するかによると思うんですが、１日にバスを利用するであろう人たちの数を出しているのか、どのぐらい見ているのかにもよるんだと思うんですけれども、その辺はどうなんですか、予測は十分に計算しているんですか。","respondent":"宮地区民課長","answer":"ですから、この用事のためだけにどれだけできるかというのは、この需要を見ませんと、バス会社のほうも当然わからないと思いますが、もう１回ちょっと事務局とも、利用者数をどういうふうに把握しているかという話を聞いてみたいと思います。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"品川駅や大森駅それぞれ使えば、関連５区のどこの方々も、交通の便としては非常に使いやすいんではないか。中につくるというのが、私は一番いいと思うんですよ。せっかくここは広い敷地なんですから、私は、敷地の中にバス停をつくって循環させたらどうなのかと思いますので、よろしくお願いしたいと思います。それから、隣の東側はまだ決まってないんですか。","respondent":"宮地区民課長","answer":"将来的には、ちょっとまだわかりません。それから、右側の水道局用地は、水槽６ｔとポンプ場の建設の計画があります。今のところは、すぐに着工の予定ではないんですけれども、そういう計画になっているということです。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"そうすると、この後はコンテナの倉庫みたいな格好で、しばらくは何年か使われるということなんですか。","respondent":"宮地区民課長","answer":"今の段階では、そういうことです。","id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"今の関連でいいですか、申しわけないんですが。横断歩道はどのような形で予定されていますか。バス停を使うのは、大田スタジアムのほかに、環状７号線のこちらにもバス停があるという話をしていましたね。","respondent":"小栗区民生活事業部長","answer":"これは平和島循環のバスがとまるんです。その次が、モノレールの流通センター前なんです。ですから、流通センター前の人は、環状７号線を渡った角ですから、やはりここの横断歩道というと、ここだけですね。","id":"exchange-010"},{"speaker":"原委員","kind":"確認","question":"そうすると、環状７号線のほうには、流通センターまで行かないと特にバス停はないんですか。確認で申しわけないんですけど。","respondent":"小栗区民生活事業部長","answer":"一番近いのは、橋の上に流通センター前のバス停があるんですよ。ですから、そこで降りていただいて、この縁をぐるっと歩いていただいて、ここからお入りいただくという形になります。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"ここを真っ直ぐ渡れるように、横断歩道はつくれないんですか。","respondent":"小栗区民生活事業部長","answer":"横断歩道はないんですね、ここは。","id":"exchange-012"},{"speaker":"原委員","kind":"意見","question":"いずれにしても、この辺を精査していただいて、もうちょっと使い勝手のいいような交通アクセスを考えていただければありがたいと思います。やはり、今のお話ですと、全然数字的なものはわからないというお話なんだけど、やはり建てればそれなりに利用は高まるはずですよね。これからまだ時間があるんだと思うので、交通アクセスをもうちょっとお考えいただければと思いますね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"プラモデルを見ますと、煙突がないんですけれども、今の火葬の仕方を教えていただけますか。","respondent":"宮地区民課長","answer":"煙突はもう全部、環境配慮型ということで、ダイオキシン等も出ないように、こちらの専門のほうで設計をしているそうですので、そのあたり、さらに詳しくはちょっとまた事務局に確認しますけれども、そういうやり方だそうです。","id":"exchange-014"},{"speaker":"菊地委員","kind":"意見","question":"夜に行ったことがないのでよくわからないんですけれども、周辺部分の照明についてはどう考えていられるのか。","respondent":"宮地区民課長","answer":"これから、全体の歩行の運線等を含めまして、考えていくということです。","id":"exchange-015"},{"speaker":"堺委員","kind":"確認","question":"確認をしておきたいんですが、昨年１２月２６日の区民委員会でも、概要を示していただいて、ご説明をいただいたんですが、工期は、その後変更ないということで理解をしていいのか、どうか。たしかあのとき、平成１４年５月着工、平成１６年４月供用開始という説明だったと思うんですが、その辺をまずお尋ねします。","respondent":"宮地区民課長","answer":"組合議会が臨時会を開きまして、そこで本契約をしてから着工ということですので、５月の中旬あたりに組合議会が臨時会を開きます。そこで契約後、準備を含めて、着工するのが６月あたりです。予定どおり、平成１６年４月にはオープンということになっております。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問・要望","question":"あわせて、ぜひ、そう設置していただきたいということを強く要望しておきたいと思います。それについては、２年後に完成するに当たって、こういうところによく出入りする業者と言っていいんですか、式場で待っている間、お清めだとかのためにいろいろ入ってくる業者がありますよね、そういう業者の選定というのもこれからなんですか。もうある程度、ほぼ決まっているのか。その辺のことはどう決まるんですか。","respondent":"宮地区民課長","answer":"全体の運営ということになろうかと思いますけれども、運営につきましては、ちょうどこれから５区の課長会、部長会等の中で検討しているというところです。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"５区で共同してやる関係ですから、５区の中のいろいろな業者の人たちも、それぞれうちを使ってくれということがあるでしょう。大田区の区内業者ということにするのか、隣接する品川区、あるいは、あくまでも５区でやったんだから、５区の人たちを使うのか。これからの検討ということなんですが、参考までにちょっと、イメージがあるかどうか。","respondent":"宮地区民課長","answer":"かなり、飲食関係とか、清掃関係とか分割して委託をするということもありますし、総合でいくか、分割方式でいくか、そこら辺もそれぞれのやり方を出して、メリット、デメリットを挙げて検討していくという段取りになろうかと思います。","id":"exchange-018"},{"speaker":"堺委員","kind":"質問","question":"９月ぐらいということは、ここの料金についても、その時期には出ますという考え方でよろしいんですか。","respondent":"宮地区民課長","answer":"運営に関して、大体、そのスケジュールでということですので、使用料を含めまして、委託の方法とか詰めていく予定になっております。","id":"exchange-019"},{"speaker":"堺委員","kind":"質問","question":"そうすると、利用料については、まだそれ以降ですか。供用開始直前にならないと、料金設定は出ないんですか。","respondent":"宮地区民課長","answer":"委託をする方法にもよりますし、どういった形で運営するかにもよりますので、全部一括して、大体９月までです。ですから、使用料も含めましてです。","id":"exchange-020"},{"speaker":"石田副委員長","kind":"質問","question":"何点か、ちょっとお聞きをします。特にここへ来る方が、１年に１回来るか、２年に１回来るかとかいうことで、しょっちゅう行くところではないわけですから、先ほど行ったように、循環バスとかを全体の中で出していくということを考えていかないと、京急バス会社と話していても、いくら増便しても根本的な解決にはならないのじゃないかという思いがあるので、そこら辺はどうお考えなのかというのが１点です。","respondent":"宮地区民課長","answer":"霊柩車等の回り方を考えますと、なぜ入口がこの幅でこの位置なのかということですけれども、一応、事務局のほうでも専門の技術職が行っておりまして、全体的に研究した結果と伺っておりますので、個々に、設計段階でこちらのほうから。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"一つだけ。職員の配置なんですけれども、当然、昼間の職員の配置から見れば、少なくなるんでしょうけど、その辺の配置の状況で、今考えていらっしゃるところを教えていただければと思います。","respondent":"宮地区民課長","answer":"４、５、６月の繁忙期には、窓口を５時までやっていますと、どうしてもその後の残務整理で職員が残らなければならないということもございまして、当分の間、その中での対応という形になります。","id":"exchange-022"},{"speaker":"原委員","kind":"確認","question":"一つ確認だけさせてください。この場所なんですが、今までも夜間窓口というのがありましたよね。あの場所なのか、要するにどこを考えていらっしゃるんですか。","respondent":"宮地区民課長","answer":"本庁の３階の正面入口から入りまして、日中、それぞれやっているところですから、戸籍住民は戸籍住民課に行っていただく。税務でしたら、日中の税務課のあるカウンターのところに行っていただく。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"そうすると、要するに業務を延長しようというわけですよね。正面玄関を開ける形をとるのか、あるいは、出入口をつくらなきゃいけませんよね。それと、ほかの警備上の問題もいろいろ入ってくるんじゃないかと思うんですけど、その辺はどういうふうに考えていらっしゃるんですか。","respondent":"宮地区民課長","answer":"第３、４火曜日には、保険年金、あるいは税務のほうでも夜間の就労のための窓口ということで、３階の正面から入れるようにしてありますので、それとあわせた形で、同じく第１、２、３火曜日とセッティングしたものです。","id":"exchange-024"},{"speaker":"南委員長","kind":"確認","question":"ほかにいかがでしょうか。ないようなので、私も確認したいんですけれども、３階から入ってということですが、税務課と保険年金課はカウンターが４階ですよね。それが一つ。その辺が二つ。それから、今の説明でちょっとよくわからなかったんですけれども、第３、４火曜日は、今までも夜間は残っていたんですか。その辺の第３、４火曜日の関係も整理して教えてください。","respondent":"宮地区民課長","answer":"ただ、いずれにしましても、これは初めてのやり方ですので、やはり、しっかり見て、今後の対応を考えていきたいと考えております。","id":"exchange-025"},{"speaker":"本田委員","kind":"質問","question":"大変いいことだと思います。ただ、区外の医療機関を利用した場合、これが適用にならないのはなぜなのか。他区は他区の中でやっているのかどうなのか。国民健康保険は全国どこでも使えるわけですけれども、この一時金についても、どこでやっても受けられるものですよね。品川区内の医療機関のみ、委任払いという新しい方式なんですが、他区でもできればなお結構なんだけれども、その辺はなぜできないんですか。","respondent":"太田保険年金課長","answer":"政府管掌のものについては、国が既に昨年７月から貸付制度を実施しているです。区についても、先ほど申し上げましたように、昨年４月から一定の所得基準がありますけれども、そのもとで貸付制度は実施をしてきてあります。","id":"exchange-026"},{"speaker":"本田委員","kind":"質問","question":"わかりました。区として医師会としてよく話をして、こういうことを今回やっていこうとなったのは、大変いいことだと思うし、他区の医療機関を使うというのも、東京都の場合多いわけですから、その辺も他区と共通性が持てれば、なお結構だと思いますので、何かの機会にその辺の話は詰めていただければなと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"そうすると、現実に、退院時にその金額を引いてオーバー分を払うという形ですか。それが１点目。だから、今後の中で十分にお話をしていただきたいと思います。そうすると、組織については、そういった得点は使えないということになってしまうんですか。もちろん、現住所と実家の住所が違うわけだから、なかなか難しい部分があるんだろうと思うんですけれども、その辺、何かお答えがあれば。","respondent":"太田保険年金課長","answer":"実家に帰って出産をされるケースもあるというのは聞いてありますけれども、先ほど申し上げましたように、区内の子育て支援、環境づくりに資するという視点から、今回、医師会、あるいは大学病院等のご協力を得て実施するものですので。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"２７万円でも、申請した方が１００％借りられるんですか。金額じゃなくて、人数的に申請した方は１００％借りられるんですか。","respondent":"太田保険年金課長","answer":"先ほど申し上げましたように、一定の所得基準というものを設定していますが、その資格要件に該当すれば、貸付けは１００％ということが言えるかと思います。","id":"exchange-029"},{"speaker":"堺委員","kind":"提案","question":"私は、昨年の第３回定例会の一般質問のときに、この委任払いについて提案させていただいた記憶があります。特に、実家に帰って出産というケースが非常に多いですから、そういう面では、直感的に該当するのかしないのか、そういう場合は、こういう方法になりますよとか。ですから、その辺も検討を加えて、よりわかりやすい周知の方法ということでお願いしたいと思うんですが、いかがでしょうか。","respondent":"太田保険年金課長","answer":"それ以外の部分で、今後、広報等、あるいは、「国保だより」の中で知らせる場合には、委員の趣旨を踏まえて、わかりやすい形でＰＲを継続的に実施をしていきたいと考えています。","id":"exchange-030"},{"speaker":"堺委員","kind":"確認","question":"もう一度確認ですけれども、母子健康手帳の中でとおっしゃっていましたけれども、これからもらう人については、当然、こういう形でできるだろうと思うんです。既にもらっている人にも、ということでいいんですか。例えばこの３月とか、４月に出産を控えている人で、もう既に昨年のうちに母子健康手帳を持っている人たちにも、それが伝わらないといけない。その辺はどうなんですか。","respondent":"太田保険年金課長","answer":"ご指摘の方の部分については、病院のほうと、来週に最終打合せをする予定です。病院のほうに、今、お手元に配付しているチラシと申請書一式、それから、病院の窓口にポスターを掲示していただくように準備をしています。","id":"exchange-031"},{"speaker":"堺委員","kind":"質問","question":"そうすると、何らかの形で、対象となる人については伝わるようになりますと理解していいんですか。","respondent":"太田保険年金課長","answer":"先ほど申し上げましたように、４月に入ったときに、仮算定のときの賦課通知書を発送いたしますので、その中の「国保だより」、あるいは、「わかりやすい国保」という、大変小さいんですけれども、そういったものも一緒に入れて送付をする予定です。","id":"exchange-032"},{"speaker":"堺委員","kind":"意見","question":"ほんとうに、心配ないように受け取れたんで安心しているんですが、漏れのないように、みんなにわかりやすくきちっと伝わるように、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"石田副委員長","kind":"質問","question":"これを読んでいると、品川区の国民健康保険に加入６カ月以上だけれども、その中に、括弧で「６カ月未満の場合は、他の健康保険から分娩費が支給されない方」と書いてあるんですけれども、実家にお父さんとかお母さんがいらっしゃるわけで、子どもが生まれそうなんで実家に戻ってくると思えば、品川区はこういうことをやっているよと、極論を言うと。","respondent":"太田保険年金課長","answer":"そこの部分は、前に、社会保険に加入をされていて、結婚されて、退職されて、出産をするという場合に、加入期間が６カ月未満であれば、前に入っていた社会保険から出産費が出るんで支給はされませんという部分を言っているところです。","id":"exchange-034"},{"speaker":"石田副委員長","kind":"質問","question":"すみません、そういううがった見方をして。もう１点変なうがった見方をしたいんですけれども、世帯主の印鑑というところで、「シャチハタ印は、不可」と書いてありますが、最近、印鑑というものの見方というのが大分変わってきて、認めという意味合いで、何でもいいですと。法律的にこれはだめだとか、そういうところがあるんですか、現実的に。","respondent":"太田保険年金課長","answer":"今、社会通念上、委員のご指摘の部分はあろうかと思いますが、通常、私どもでシャチハタではなかなか難しいだろうと。それと、会計処理の段階で、シャチハタはまだ認められてないという状況かと思います。","id":"exchange-035"},{"speaker":"石田副委員長","kind":"質問","question":"それというのは、何か法的根拠というのがあるんですか。","respondent":"小栗区民生活事業部長","answer":"例えば印鑑証明なんかでもそうなんですが、継続的に判の確認がまずできないということで、金銭貸借に関係するものについては、今、品川区では、シャチハタは認めてないということです。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"１点だけお伺いしたいんですけれども、これは評価の結論ということで、東京二十三区清掃一部事務組合から出されてきている。先ほど、課長が説明してくださった事後調査の話なんですけれども、事後調査そのものは、４２カ月後に実際に運転が始まってからやることなんでしょうけれども、事後調査そのものを、全く別の、例えば第３者機関が事前調査の結果に基づいてやるのか。","respondent":"金井環境課長、中山清掃リサイクル課長","answer":"基本的には、環境影響評価、見解書、住民の意見、あるいは評価書としていろいろ自治体の意見も入れてつくってきた事業者が、事後も責任を持ってやるということになっています。事業の考え方を、今、環境課長が申し上げておりますが、ご存じのように、平成１７年度末を目途に、清掃工業については、東京二十三区清掃一部事務組合から各区の地域処理を予定しています。","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問","question":"実際に出てきた結論が、もちろん事後評価の中で、違っていた部分とか、そのとおりであった部分とかいろいろ出てくるんでしょうけれども、内容的にも、皆さんに人体に大きな影響を与えませんという部分が明確になるような事後調査であってほしいと思うんです。これは質問じゃないですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"本田委員","kind":"質問・要望","question":"二つ、ちょっとお尋ねします。万一延期というようなことになりますと、どういう責任体制でこの事業が執行されていくのかというのが１点。大気汚染から温室効果ガスまで、当議会でいろいろ議論をしたわけですので、そのことを反映して意見として挙がったわけですが、具体的にどういうふうに最終効果のところで取り入れられているのか、教えていただきたいと思います。","respondent":"中山清掃リサイクル課長、金井環境課長、野本環境清掃事業部長","answer":"万が一といいますか、これに影響する事態が生じた場合は、地域処理の検討の中で、それによってどういう影響があるかというのを、再度。大体吸収されておりますけれども、何と何がどういうふうに変わったかという形には、直接はなかなか難しいんですが、区としての考え方。こういう意見に対しては、機械はこうなっていて、したがってこうですとか、ここについては。","id":"exchange-039"},{"speaker":"本田委員","kind":"質問・要望","question":"区の意見が全評価の中に、どういうふうに入ったのかということについては、確かに、話を伺えば難しいですから、評価書をいただいて、改めて目を通して、事後評価との関係が大事ですから、それはいただきたいなとほんとうに思っております。委員会としていただければ一番いいと思いますので、そういうことでお願いしたいと思いますが、いかがでしょうか。","respondent":"中山清掃リサイクル課長、金井環境課長","answer":"しかしながら、財政調整との関係は、今回の地域処理の枠組みの検討を踏まえて、これはほかでも議論になっておりますが、いわゆる債務も含めた債権の扱い、債務の扱いも含めて、どのようにこれを２３区で負担。委員会として、全員のご要望があれば、その分をお出ししますし、希望者だけということであれば、それなりの配慮をします。いずれにしても、何ら拒否するものではございませんので、言っていただければ、私どもは提出します。","id":"exchange-040"},{"speaker":"本田委員","kind":"質問・要望","question":"わかりました。平成１７年度の東京二十三区清掃一部事務組合の問題については、いろいろな要素が絡んでくるんだろうと思いますが、円滑な清掃事業が、区レベルで執行されていくということが一番大事なわけですから、今、そういう意味では、執行期間ですので、大井工場のプラントだけではなくて、清掃全般の問題にも係わってくることですので、十分、そこのところは円滑に対処していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"石田副委員長","kind":"確認","question":"すみません、今の確認だけさせてください。そういう意味で、解散に対する影響は出てこないと思うんです。もちろん、カウントの違いは出てくると思うんですけれども。だから、そのことがおくれることによって、解散までがおくれてしまうという判断はないと思うんですけれども、そういう判断でいいのか。","respondent":"野本環境清掃事業部長","answer":"今、清掃リサイクル課長が答えたのは一部真理だろうと思うのは、なぜかというと、１５％というのがありますよね。そこに影響があると、区長会なり、東京二十三区清掃一部事務組合の議会が判断をするときに、前提が欠けていると議論が非常に進みにくい。","id":"exchange-042"},{"speaker":"石田副委員長","kind":"質問","question":"１点だけ、これはわからないと思うんですが、わかっている範囲で結構なんですが、住宅地の固定資産税、都市計画税の減免、４００m2というのは、私も新聞でしか読んでないんだけれども、今、もう東京都の議会が始まっていますよね。その中で出てきた動きとか、そういうのを何か把握されているんですか。","respondent":"松崎税務課長","answer":"最初の減免の都市計画税については、２３区である区部だけなんです。今回提案されている新たなものは市部も含みますので、市部の固定資産税に大きく影響する部分があるというのは聞いております。","id":"exchange-043"},{"speaker":"石田副委員長","kind":"質問","question":"もう１点だけいいですか。今の２６０億円に対して、新聞だと１０９億円と書いてあって、それが財調の中で各区にという話が出ていたと思うんですけれども、そこら辺の区としての立場というのは、どうお考えなんですか。","respondent":"松崎税務課長","answer":"おそらく、財調の説明があったのが１月中のはずで、これがまだ決まってない段階で、急に出てきているようですので、その後、財調がどうなるかというのは、おそらく、多分すべてで２６０億円で、財調で回ってくるのはそのうちの５８％ぐらい。","id":"exchange-044"},{"speaker":"本田委員","kind":"質問","question":"３多摩のほうはもろに自分のところの歳入ですから、市長たちも大変怒っている。これは何も３多摩だけじゃなくて、２３区だって、財調財源ですから、区のレベルにそれなりの相談があってしかるべきだと、私は思うんです。都だけじゃなくて、特に財調制度を持っている２３区には大きな影響が来るわけですからね。その辺は、税務課長に聞くのは酷なんですけれども、どうなんですか。","respondent":"松崎税務課長","answer":"１月３０日に税務課長会がございまして、その段階では、税務課長に対する財調の説明がございました。そのときには、全くございませんでした。","id":"exchange-045"},{"speaker":"本田委員","kind":"質問","question":"隠密にぱっとやるというのが好きなようですけれども、しかし、こういう各区、自治体に大きな影響を及ぼす制限ですから、やはりこういう地方分権の時代ですから、何でもいくんだというやり方では、これはやっぱり本筋を外れているんじゃないかなと思うんです。区のほうも、言うべきことはきちっと言ってもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"金高委員","kind":"意見","question":"２８の信用組合、信用金庫、あるいは、都市銀行も含めて、それぞれの格付けのデータというのは、しっかりとお持ちになっているのかということも含めて、これは産業振興課で持っているのかどうかあれなんですけど、そういったことも視野に入れて、この金融機関がどうかというのがやっぱり出てくるような気がするんですけどね。","respondent":"市川産業振興課長","answer":"お尋ねのうち、言わば銀行の経営状態ということで、どう対応しているんだですけれども、特に制度融資の預託金の扱いということで、この間言われております、安心して預けられるところなのかどうかということにつきましては、これまでも預託金の預け入れにつきましては。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問","question":"今、課長のご説明で、制度融資の大半は保証協会ということだったんですけど、言葉尻になっちゃうかもしれないんですけれども、大半じゃなくて、制度融資は１００％保証協会を通さなきゃいけないという感覚だったもので、保証協会がオーケーを出さなくてもいいというような例外が一つでもあるんですか。","respondent":"市川産業振興課長","answer":"大半という言葉は、数字的に申し上げますと、現在、全体の９６％が信用保証協会を利用なさっている。全体というのは、融資の実行がされるうち、９６％が保証協会の保証がつけられている。","id":"exchange-048"},{"speaker":"菊地委員","kind":"質問・要望","question":"一つは、都市銀行は、平成１２年度で３０％未満で、信用金庫のほうが５５％。パーセンテージが変わってくる、その辺についてよくわからないので、教えていただきたい。今、お話しされていた預託金との問題で、課長が先ほど、ペイオフとの関連も勘案して、預託金の預け先を決めてきたというお話だったんですけれども、その中身というか、これをどういう形で決めてこられたかということを、お聞かせ願いたい。","respondent":"市川産業振興課長","answer":"一つだけ、昨年４月、平成１３年度の預託金を預けるときに、収入役室のほうから、一つ注意しなければならない点ということで意識したことは、いわゆる自己資本率という数字がどうなっているかということで、私どもの取り扱い金融機関のそれぞれ。","id":"exchange-049"},{"speaker":"菊地委員","kind":"意見","question":"今の自己資本率のお話なんですけれども、これは当然、都市銀行だろうと信用金庫だろうと、同じ意味なんですね。実際に、区内の中小業者の方が借りようとすれば、信用金庫あたりが主体になるんだと思うんです。基本的には、自己資本比率で考えたときには、当然、都市銀行のほうが高いということですよね、単純に見たときには。","respondent":"市川産業振興課長","answer":"いわゆる都市銀行に適用される自己資本比率のガイドラインと、信用金庫、信用組合に対するものは、８％と４％という違いがあります。絶対値で言ったら全然違いますけれども、率になりますと、そういう設定の違いをされております。","id":"exchange-050"},{"speaker":"菊地委員","kind":"質問","question":"もう１点だけお願いしたいんです。実際に、億というお金を、もし信用金庫や信用組合に預金として入れているのに、引き抜いたという言い方はおかしいですが、引き上げたときに、実際に信用金庫なんかに与える影響は。例えば、きのうの審査でも、小さな数字ですけれども、あれを引き抜いたときの影響というのはどういうふうになるのか。","respondent":"市川産業振興課長","answer":"仮に、預託金を廃止したときにどうなのかというお尋ねですけれども、これは各金融機関、信用金庫なり、信用組合の事業規模と申しましょうか、資本金がどのぐらいの金額になっていて、預かり総額がどのぐらいになっていてという、事業規模によって、影響の大小が出てまいります。","id":"exchange-051"},{"speaker":"原委員","kind":"質問・要望","question":"せっかく、制度融資の話もされましたので、ちょっと現況だけ聞かせていただきたいんです。その銀行が統合されたり、または、つぶれるということもあるわけですけれども、そうしたときに、借りている企業は、例えば、信用保証協会の信用保証の額を書き換えをしろ、あるいは、もし担保を入れているならば、これは直接かもしれませんけれども、担保を増やしてくれとか、現状の中では、そういう話が来ていますか。","respondent":"市川産業振興課長","answer":"ただ、これはうちの区内の話ではございませんが、追加融資を受けるときには、今までの取り引き先の金融機関と同じような条件で受けられるかどうかというのは、ちょっとケース・バイ・ケースによって違ってくるということは、よく言われていることです。","id":"exchange-052"},{"speaker":"原委員","kind":"質問","question":"今、現状の中では、特にはそういったケースは出てきていないんですか。","respondent":"市川産業振興課長","answer":"私どもの制度融資の場合には、比較的融資を受けている金額が小さいということがありますので、委員がご指摘になるようなケースというのは、もう少し大きい案件でよく起こることだと思います。","id":"exchange-053"},{"speaker":"菊地委員","kind":"質問","question":"ちょっともう１点。今、原委員が質問したところで、もし破綻をした場合、みずからの新しい金融機関に入ったときに、当然、今、課長が言われた不良債権とか、そこでまたもう一度吟味をされるという形になるんですか。それとも、受け皿機関そのものが、不良債権は最初から受けないという感じになるんでしょうか。","respondent":"市川産業振興課長","answer":"ですから、営業譲渡を一たん受けた後に、これは不良債権だからといって国の債権回収機構のほうに、後から面倒を見てくれという形で回すことは、制度上ない話です。","id":"exchange-054"},{"speaker":"菊地委員","kind":"意見","question":"ということは、もし信用金庫なり、信用組合なりがつぶれて、その時点では通常に取り引きが行われていたものが、その時点で、不良だと判断されたときには、そこで一括返済なり何なりという、ＲＣＣに送られる状況というのが、形としてできちゃうわけですね。","respondent":"市川産業振興課長","answer":"再度申し上げますと、債権回収機構のほうに回された案件についても、新しい引き受け手の金融機関のほうに回されたものについても、私どもの利子補給は変わらずに両方とも続けてまいります。","id":"exchange-055"},{"speaker":"菊地委員","kind":"質問・要望","question":"飲み屋さんが増えると、商店街としての形が崩れていくようなことも出てくるんですけれども、ジャスコと、コウズのときにはそういう問題があれば、教えていただきたい。今、言われた大型の集客装置という話なんですけれども、私のわかる部分で言うと、大井町駅周辺でこれを考えたときに、どういうものが想定できるのかというのを、ちょっと教えてください。","respondent":"市川産業振興課長","answer":"ジャスコに関するお尋ねですけれども、以前のコウズ品川店のときに、利用なさっているお客様の３割が、大田区、品川区地域居住の方でした。あそこはカード制になっていましたので、そういう意味で、会員の方の比率として説明を受けた経緯があります。","id":"exchange-056"},{"speaker":"菊地委員","kind":"意見","question":"回遊と言っても、ほんとうに商店街としての新しい体制にでもしない限りは、お客さんが回遊しようにもできない、するところがないというのが現実だと思うんです。集客装置としては、これらが考えられるということですが、では、回遊させるために新しい周辺の商店街の魅力づくりというのはどういうふうに。先ほど課長が言われたことのようなことだとは思いますけれども、今ある地域性をどう考えるのか。","respondent":"市川産業振興課長","answer":"このようなもろもろのことがあって、ほかの商店街でも、今後の活性化ということで、まず商店街独自で取り組まなくちゃいけないはありますが、連携できるところは連携して取り組んでいこうという機運があると、私ども見てあります。","id":"exchange-057"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そういう場所、場所に合った展開をぜひ図っていただいて、その中でやっていただきたい。１００人が１００人、こっちの方向でいいということはないわけですから、ある程度の全体の意見を集約したら、そこでほんとうに政策誘導的にやっていただかないと、活性化はできないということだから、そこら辺のところだけは、政策誘導的にやっていただければというのを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"南委員長","kind":"確認","question":"ほかにいかがでしょうか。例えばまちの中にたくさんコンビニエンスストアができていますよね、チェーン店で。そういう点で、大きな資本を投じてチェーン店をいっぱい展開して、そういう商品を展開してくるとなると、品川区内にもその影響が出てくると思うので、その辺で、先ほど申し上げた１,０００m2以下のところが、そういう部分に入るのかどうかというのを、改めて確認しておきたかったんです。","respondent":"市川産業振興課長","answer":"先ほど、私、説明の冒頭で、旧第２種の大型店２８店舗のうち１１件が１,０００m2以下ということで、新しい立地法の対象からは落ちますと申し上げたが、１,０００m2以下といっても、もともとが５００m2を超えている店舗ということです。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/365953?Template=document&Id=2320#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":53235,"voices":177}},{"id":"h14-20020305-7","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"厚生委員会","time":"午前１０時０４分～午後２時２１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"何点かお伺いいたします。支援費、措置から契約へという動きの中で、大筋はわかってきましたが、一つは、サービス利用者の意思の確認、知的の障害者もいらっしゃるでしょうから、場合によってはその方の意思が、本当にその業者と結びたいかどうかわからない場合があります。","respondent":"日下部障害者福祉課長","answer":"ということで、事業者自身の苦情解決への対応、それから、そこで対応できない場合には、これは都道府県の社会福祉協議会が窓口になってというような、そういうこともありますけれども、基本的には市町村が苦情解決について、いろいろ事業者自身で解決できない場合は。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"だから、その辺の整合性をどうとっていくかということで、今成年後見センターの話がありましたけれども、もう少し答弁をいただけませんでしょうか。その意向の確認が、もう少し、区のほうでこうしていきたいとか、難しいことを言ってますけどね、知的障害者の方とか、それから高齢の方もいらっしゃるでしょう。お願いいたします。","respondent":"日下部障害者福祉課長","answer":"そういうことで、各それぞれの施設で、いろいろ準備は進んでおります。ただ、その辺のサービス評価の、もう少し全体的な仕組みのあり方につきまして、今度の地域福祉計画の策定の中で具体的に検討を進めていきたい、このように考えます。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめていきますけど、私たちの会のところにも、団体の方々から、こういう大きな制度変更があるので、例えば議会も間に入った、こういうふうなオンブズマン制度をつくってほしいとか、いろいろ要望が来ているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須藤委員","kind":"確認","question":"そこは我々の、品川区の行政としては、声を出せる場所がどこにあって、この図ができてきたのかなというような感じがしているんですけれども、どこで、品川区行政としては声を出していった場面ができたのかということと、それから、契約によりサービスを提供するようにというような形になりますけれども、今度は措置から変わってきて、サービスの増大というものが何か考えられてくるのか、今までの。","respondent":"日下部障害者福祉課長、小沼福祉事業部長","answer":"ただ、今回の支援費制度の実施に当たりましては、その目標に向けて、やはり国のほうとしても、知的障害者の方の意思の確認、あるいはサービスの選択というのが、確かに現実問題難しいところがあるのは事実です。今、須藤委員のほうからのご質問ですけど、ちょっと補足しますと、基本的なところで、これは従来の措置制度から支援費、あるいは契約制度への移行と、そういうような言葉なり概念で説明されますけれども。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問","question":"最後にもう１点だけ、サービスの増大がありますか、ということをちょっとお聞きしたのは、いわゆる利用者負担が、今度事業者のほうに支払う形になってきますよね。そのほうがいいのかどうかというのは、また今後の検討課題になろうかと思うんだけれども、利用者の負担の支払いというのが増大してくる傾向はあるんですか。それとも、現状のままで行くことになるのか。","respondent":"日下部障害者福祉課長","answer":"結論から申し上げれば、国が明言しておりますのは、公費負担の水準は変えないと。ということは、具体的に利用者負担についても従来どおりの水準を、基本的には変えないということを明言しています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、今の説明をしていただいた、これを見させていただいて、なかなか、仕組みがどうなっていくのかというのがよくわからない部分があるんですけれども、一つは、支給決定の仕組みというところなんですが、これは支援費の支給申請を利用者のほうがすると、市町村が支給決定を行うということなんですが、これは具体的にどういうされ方で支給決定が行われていくのかということをお聞きしたいんですけど。","respondent":"日下部障害者福祉課長","answer":"最初に、地域福祉計画の策定に間するご質問ですけれども、これにつきましては１４年度中に策定をするということで予定をしております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今のお話を聞くと、基本的なところでは厚生労働省のほうからいろいろ示されるけれども、具体的なところでは各自治体がそれぞれ決めていくという、そういう方向なのかなというふうに思うんですけれども、そういうところでは、いろいろと決まり次第、この中にも報告をしていただけるというふうなことだと思うんですが、支給決定のところで言えば、そういうふうな基準が示されて、その基準に基づいて。","respondent":"日下部障害者福祉課長、小沼福祉事業部長","answer":"それから支給の期間、これも国で基準が決められてまいりますけれども、例えば施設であれば、一つの目安、見直しの目安が３年とか、在宅のサービスであれば１年だとか、そういう形で、それぞれかなり具体的なサービスの種類。そこのところを分けて説明しないと、なかなかつかみにくいと思うんですが、施設サービスというのは３ページにあります。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"少しずつちょっとわかってきたかなという感じなんですけど、今の支給決定というふうなところで言えば、介護保険みたいに、上限はここまでの金額にして、そこの中でサービスは自由に選択できますよ、というよりも、もっと区のほうが、この方にとってはこのサービスはこれぐらいまで、このサービスはこれぐらいまで、というふうな形で、決められた形で支給決定がされるということで理解していいんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ご指摘のとおり、個別具体的に決めていくということになります。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、本人が選べるというのは、選択できるというのは、そこの、決められた中での業者の選択というふうな形になってくるんですか。","respondent":"日下部障害者福祉課長","answer":"これは、本人のご希望、これを受けて、それに沿う形で支給の決定を進めていくと、そういうことです。何も本人の意向を全く度外視して決めていくとか、そういうことではございません。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、そこの本人が、支給の申請をした段階で区のほうが、ケアマネジャーじゃないけど、ケアプランのような形の役割を果たして、ある程度のサービスの中身もそこの場で相談をしながら、そして、じゃここら辺までという形で支給決定がされる、そういうふうな仕組みでしょうか。","respondent":"日下部障害者福祉課長","answer":"つまり、それぞれの申請を受けて、本人がこうしたい、ああしたいということで、ただ申請をして、それがいいか悪いかとか、そういう問題以前に、やはりこれは必要なことなんですが、事前に相談に応じていく、情報を提供していくという、事前のしっかりした。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その仕組みが大分わかってきたんですけど、そこの段階で、ある程度区のほうがかなりかかわって相談に乗っていただける、そういうふうなことで、ちょっとわかりました。それで、今度の制度で大きく変わるわけですけれども、区としては、今回の制度の変化で、メリットというのはどういうふうに考えられているかについてちょっとお聞かせいただきたいんです。今回の制度が変わることによってのメリット。","respondent":"日下部障害者福祉課長","answer":"メリットといいますのは、これは利用者の方にとってのメリットですか。これは１ページ、先ほどご説明をさせていただきましたけれども、利用者の方自身の自己決定を尊重するということで、それが反映された仕組みになっていると。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、もう一つちょっとお聞きしたいのは、介護保険の場合では、施設に対して、例えば特別養護老人ホームなんかに対して補助金が東京都から入っていたのが、随分なくなったというふうな、こういう経過があると思うんですけれども、この問題で、障害者の施設に対しての東京都からの補助金とか何かが来ていて、そういうふうなところに対して考えられている部分があるのかどうなのかということを一つと。","respondent":"日下部障害者福祉課長","answer":"１点目の、東京都の負担する費用の問題ですけど、これについては東京都も、この制度の実施に向けてどうするかということで今検討が進められているです。私どものほうとしましても、その具体的な内容については承知はしておりません。","id":"exchange-012"},{"speaker":"船波委員","kind":"質問","question":"今現在の制度だと、サービスを提供する施設や事業者は、東京都から施設認可を受けていて、それが新制度になると、東京都から指定を受けるということになっていますけれども、今現在東京都から施設認可を受けているところは、自動的にというか、そのまま支援費制度でも指定を受けられるということになっているんでしょうか。","respondent":"日下部障害者福祉課長","answer":"実は、現行で今認可を受けているものは、そのままみなし指定ということで、その後は指定に移行するということになっています。","id":"exchange-013"},{"speaker":"船波委員","kind":"質問","question":"今認可を受けているところはそのまま移行できるということですけれども、では、新たに指定を受けられるように申請をしたりするところに関して、その対象となるサービスはいろいろあって、そういったサービスを提供しようというところはいろいろ出てくるかと思うんですけれども、その指定を受けるときに、例えばグループホームの事業者として指定を受けたいとか。","respondent":"日下部障害者福祉課長","answer":"指定の基準につきましては、ついこの間、国のほうから、国としての基準が示されたですけれども、基本的にはいろいろ施設の規模であるとか、あるいは、それに応じた設備であるとか、運営の体制であるとか、そんなには大きく変わっていないということで承知をしております。","id":"exchange-014"},{"speaker":"船波委員","kind":"確認","question":"支給決定について、もう一回確認のためにお伺いしたいんですけど、ある一人の障害者の方にどのようなサービスが提供されるかということを決定する際に、その障害者本人のレベルであるとか、その人を取り巻く状況で、ある程度量や期間が決まるというのはわかりましたけれども、その内容については、例えば、今までずっと利用してきた施設なりサービスがあるんだけれども。","respondent":"日下部障害者福祉課長","answer":"ですから、今のご質問のように、今実はこういうサービスを受けている、ただ、これではなくて、いろいろ状況も変わったから、別のこういうサービスの提供に切りかえたいという場合、それが適当であれば、その辺は変更も可能だと、そういう決定もできるというふうに思います。","id":"exchange-015"},{"speaker":"船波委員","kind":"質問","question":"その適当であればというのは、相談の段階で区の側と本人の側と相談してということですか。","respondent":"日下部障害者福祉課長","answer":"支給決定については、先ほど申し上げました。政省令という国の示した基準に基づいて、市町村が基準を決めます。ですから、その基準に合っていればサービスの変更も当然可能だということです。","id":"exchange-016"},{"speaker":"船波委員","kind":"質問","question":"すいません、なかなか理解力が及ばないようで、いつまでも聞いてしまって何ですけれども、では、その基準というのは、こういったレベルの障害者、あるいはその人といいますか状況を見れば、その人にはデイサービスがいいでしょうとか、そういった内容についての基準があるということなわけですか。","respondent":"小沼福祉事業部長","answer":"ですから、やみくもに、こうだからこうだではなくて、あくまでもその方の障害特性なり、今の行動特性に応じてものを組み立てて、その時点で最適なもののサービスの購入なり、あるいは選択なりと、こういうふうな手続ということで。","id":"exchange-017"},{"speaker":"船波委員","kind":"質問","question":"もちろん今までの、いろんな知識の蓄積があって、そういった基準があるというのも、もちろん障害のある人や、その人を介護する人のために、これくらいがいいだろうというものでしょうから、そういったものを提示してもらって相談して決めるのはいいかと思いますけれども、でも、いろんなケース、たくさんのケースがこれから生じてくると、やはり本人であるとか、周りの人が、相談してみて。","respondent":"日下部障害者福祉課長","answer":"事前の、ちゃんとしたお互いの意思疎通、相談をしっかり受けられる体制をちゃんとつくっておけば、そんなに私は、大きなそごが出てくるということはないんではないかと、このように考えます。","id":"exchange-018"},{"speaker":"嶋委員","kind":"質問","question":"何点かお聞きをしたいと思います。今の、このままの障害者福祉課の担当でいかれるのか、あと、障害者７団体への説明のことなんですが、やはり品川区内でも、この７団体に入っていない障害者の方のほうが大変多いと思います。そういう方たちへの、いわゆる広報、啓発というのは、どのような方法でされていかれるのか、お聞きしたいと思います。","respondent":"日下部障害者福祉課長","answer":"１点目の、私ども障害者福祉課の体制ですけれども、支援費制度の導入、いろいろと作業もふえてまいりますけど、基本的には現在の体制で進めてまいりたいと。","id":"exchange-019"},{"speaker":"嶋委員","kind":"質問","question":"それと、これは居宅、在宅とか、施設訓練、この二つに分けられるというお話しだったんですが、居宅も１年、施設訓練、目安的には３年ということなんですが、これを超えていく部分が、その状況では、障害のいろんな内容が進んでいくと思いますが、そういうときの、先ほどと何回も同じ質問になってしまいますけれども、申請方法が、もう一回し直さなければならないのかということと、それと。","respondent":"日下部障害者福祉課長","answer":"ですから、これは後ほどご報告申し上げますけれども、例えばデイサービスもショートステイも、１６年度の開設を目指して、西大井６丁目に、これから建設に入ってまいりますし、そういうことで区のほうとしても努力をしてまいりたいと、このように考えます。","id":"exchange-020"},{"speaker":"嶋委員","kind":"質問","question":"最後の、この申請なんですが、やはり今までどおり、窓口に来て申請をしなくてはならないのでしょうか。","respondent":"日下部障害者福祉課長","answer":"基本的には窓口に来ていただくということで考えています。","id":"exchange-021"},{"speaker":"鶴副委員長","kind":"質問","question":"今回のこの福祉分野における支援費制度の特徴というのは、これまでの画一的な行政サービスとか、あるいは時代おくれだというふうな、そういう批判にこたえ、是正する形で措置から契約制度に、平成１５年の４月から移行するというのが大きな特徴だろうというふうに思うんですが、制度の大きな変更の際には、それぞれの関係者はわからない部分があって。","respondent":"日下部障害者福祉課長","answer":"関係者の不安ですけれども、先ほどもご説明させていただきましたけれども、準備の期間が非常に短いと。来年の４月スタート、実際の受付は１０月ということで、これからあと半年ぐらいしかございません。","id":"exchange-022"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"今回も、同じようなことが言える部分があるのではないかというふうに思うんですね。その事業者が、障害者が求めるサービスにこたえるだけのサービスを提供する事業者であればいいなというふうに思うんですが、そういう意味では、障害者の団体の方々は、要するにサービス量の上限の撤廃ということが大きな願いであるというふうに思うんですね。事業者なのか、当該市区町村なのか。","respondent":"日下部障害者福祉課長","answer":"そういった意味では、サービスの拡大につきましては、私ども今ご質問の中にもございましたけれども、品川区の場合、障害者の施設関係につきましては、ほかの区に先駆けて、いろいろ、親亡き後の施設の整備も含めて、かなり積極的に進めてまいります。","id":"exchange-023"},{"speaker":"鶴副委員長","kind":"意見","question":"先ほども話題になっておりました、利用者の負担がふえるのではないかというような不安もあるのではないかというふうに思うんですね。この利用者の負担については、平成１１年の１月の障害者関係審議会合同企画分科会がお出しになった意見具申の中に、基本的な考え方が述べられています。その点はどうなっていますか。","respondent":"日下部障害者福祉課長","answer":"ですから、そういう前提の上に立って、国のほうの政省令が示されてくるというふうに、これはもう当然のことですので、私どもは、その辺の基本的な、前提の考え方、これをベースにして準備を、できるだけ、政省令が示されれば、それに基づいて速やかに基準を決められるように。","id":"exchange-024"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"どこに負担能力の判断を求めるかということについて、いわゆる施設サービスの利用者本人と、あるいはその扶養の家族、それから、例えば在宅サービスを受けている本人の場合は、おのずと負担能力の判定方法が異なってくるというふうに思います。要するに、施設サービス本人は、前年度の所得という、扶養家族も前年の所得税額によって負担の割合が現行では行われているんじゃなかったですか。","respondent":"日下部障害者福祉課長","answer":"施設の利用者につきましては、今ご指摘ございました、現行の制度では、まず基本的に、先ほど申し上げました、本人につきましては前年の収入額、一方で、それを補完する形で、どうしても本人負担が難しい場合は、扶養義務者が、これは逆に、一定の金額を控除した所得税額相当分。","id":"exchange-025"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、今回移行したとしても、これまでの施設サービス本人、あるいはその扶養家族については、本人は前年度の収入額ですね。どういうお考えでやられたんですか。","respondent":"日下部障害者福祉課長","answer":"今ご指摘ありました施設、居宅、それぞれのサービスの内容に応じて、今国のほうでは、副委員長がご指摘になったような方向で検討が進められているというふうに、私ども承知しておりまして、そういった意味では、そういう現行の仕組みを前提にした形で。","id":"exchange-026"},{"speaker":"鶴副委員長","kind":"意見","question":"品川区としてはどうするのかという点。品川区は、とても優しい人ばかりだから、突っぱねたりすることはないから、あえてそういうセクションを設けなくても対応できるんですよ、ということであればいいんですけれども、考え方はどうでしょう、基本的に。","respondent":"日下部障害者福祉課長","answer":"私ども区の職員、それから施設のスタッフですね、今のそれぞれの障害者施設のスタッフなんかも、その研修に参加をしているというような状況もありますので、そういった意味では、ケアマネジメントの基本的な考え方を、できるだけ反映できるような。","id":"exchange-027"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"品川区でも、品川区だけで今まで措置をしているわけではなくて、県外に措置をしている人たちもいるわけですが、その人たちが今回の支援費制度で何ら排除されるわけではありませんが、いずれにいたしましても、福祉先進都市と言われる品川区、これまで保育だとか、高齢者福祉の面だけではなくて、障害者の面でも、細やかな対応策がとられてきていることに対して、誇らしげに思っているわけですけれども。","respondent":"小沼福祉事業部長","answer":"今鶴副委員長のほうからお話がございましたけれども、私どもも、そういう期待に背かないような形で、引き続き、これは障害者福祉だけではなくて、今お話が出ましたけど、高齢者、あるいは児童福祉、それから障害者含めてですけれども、これまで営々と諸先輩。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この支援費制度の対象者がそれぞれどれぐらいいらっしゃるのか、その対象者の人数について一つ教えていただきたいのと、それから、先ほどから説明を聞かせていただいていたら、やっぱり利用者側から申し込みがあったときに、区のところの相談に応じるというふうなところがすごく大事な役割を果たすのかなという感じに思ったんですけれども、そこのところの区の体制というか。","respondent":"日下部障害者福祉課長","answer":"ですから、このケースワーカーを中心にして相談に対応していくということで考えております。それから、先ほど申し上げました、今度は生活支援センターがひまわり荘に併設ということでスタートしてまいりますし、そちらのほうにも、これは福栄会のほうで常勤職員を配置いたします。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に、いろいろとまだまだ政省令が出てきていないですとか、これから地域福祉計画をつくっていくだとかというふうな課題が、来年度いろいろとあると思うんですけれども、これから委員会の中に最低こういうふうな形で報告をされていくということでわかっているところがありましたら、具体的に時期と内容というところで、ありましたら教えていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"委員会の報告についての具体的な手順については考えてはございませんけれども、ただ、先ほど申し上げました、国とのいろいろ兼ね合いもありますけれども、今後準備が進んでいきますので、それに応じて適宜適切にご報告をするということで、考えております。","id":"exchange-030"},{"speaker":"嶋委員","kind":"意見","question":"実は今、品川区の中でいろんなところでマンションが相当建っていて、狭いところで何トン車が入ると一斉に車がとめられてしまうことが、大変多くあちこちで品川区内で起きていて、皆さん困っている状況がありますので、ぜひ大型車両を使う場合は、時間帯を考えていただいて、なるべくそこの道路を使う方たちに迷惑がかからないようにしていただけたらと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"鶴副委員長","kind":"意見","question":"普通、エレベーターの表示というのは、小さな文字で張ってありますよね。私も目が見えないのかなと思って、余り小さ過ぎて探したんですが、よくわかりました。それで、ここは新たに整地なさる感じになりますが、今の樹木は、かんべ土地のほうの駐車場のほうと、今までの中庭に相当するところの樹木というのは、どういう運命になりますか。消滅してしまうのか、移設できるものは移設するのかという点です。","respondent":"日下部障害者福祉課長","answer":"大きなもので、どうしても工事の関係で残せないものは、一たん移設をして戻すことが可能かどうか、その辺も含めて、３月中に実施設計の中で設計業者、それから実際のこちらの窓口は施設課になっておりますけれども、その辺も含めて調整していくという予定になっております。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この設計のこととちょっと違うんであれなんですけど、福祉施設の知的障害者の入所施設については、前回ご説明いただいたんですが、この３０名の対象というのがどのように考えられているのかについてお聞かせいただきたいんですけれども、重度の方が入れるのかどうなのかということで、聞かれた部分もあったので、そこら辺の知的障害者の方の３０名の対象者についてお聞かせください。","respondent":"日下部障害者福祉課長","answer":"この入所施設といいますのは、正式に申し上げますと、知的障害者の入所更生施設ということになっておりまして、そういった意味で、比較的重い知的障害をお持ちの方が入所するということで考えております。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、車いすで重度の方とかもこの対象になるということで考えられるんでしょうか。それから、１６年の４月から入居開始というふうなことで、スケジュールが書かれていますけれども、これはいつぐらいにどういう形で、この対象の方が決まっていくのかについてお聞かせください。","respondent":"日下部障害者福祉課長","answer":"入居の開始が１６年４月になりますから、当然その辺の入居のいろんな募集であるとか、そういうものは１５年度には行っていくということになると思います。そういうことで予定しております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"重複障害というふうなことになると思うんですが、車いすの障害者の重度の方がなかなか入れる施設が区内にないというふうなところで、お聞きしているんですが、そういうふうなところでは、そういう方の施設というものの計画についてはどう考えられているかについて、ちょっとここと外れちゃうかもしれないんですが、お聞かせください。","respondent":"日下部障害者福祉課長","answer":"例えば通所関係でまいりますと、今心身障害者福祉会館のほうにそういう重複の方が入ってらっしゃいますし、その辺はそれぞれのケースに応じて、比較的柔軟な対応もしておりますので、そういった意味では、今具体的にどういう計画があるかということではなくて。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"意見","question":"２階の平面図の上のほうの、都営住宅のエレベーターで、例えば２階で災害が起きた場合にこのエレベーターを使って避難するときに、これが当然あいたほうがいいかなと思うんですが、その辺の考え方についてお聞かせいただければありがたいんですが。","respondent":"日下部障害者福祉課長","answer":"そういう形で、いざというときはきちんと避難ができるような、そういう形になっております。失礼しました。入所施設用は北側の部分だけですね。施設の場合は２方向避難と言われていますけれども、そういうことで対応できるような仕組みになっています。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"それはわかります。そういうふうに緊急時には十二分に活用できる仕組みを考えていくと、はじめから閉鎖ということではなくて、通常は使えないけれども、万が一の場合には使えるような仕組みを考えていったらどうですかということを言っておりますので、その辺の検討はいかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"今の緊急時の対応ということで、実は施設の設計に関しましては、私も今回携わってわかったんですが、いろいろ法的な制約条件とかがあります。ということで、今のご指摘を受けまして設計業者のほうにも当たってみたいと思います。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区営住宅のところで、障害者住宅が４戸ありますけれども、ここのところは非常時に車いすで避難できるようなスロープというか、そういうふうな避難路みたいなのは入っているのかどうか教えてください。","respondent":"日下部障害者福祉課長","answer":"こちらにつきましては、特にスロープとかそういうものは設けてございません。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"車いすの方も入れるようにということで全部設計されていると先ほどご説明がありましたけど、非常時の避難についてはどういうふうに。","respondent":"日下部障害者福祉課長","answer":"この障害者世帯向け住宅については、前提として車いす専用の住宅ということではございません。車いす専用ということになりますと、いろいろ条件が厳しくなりまして、例えば原則１階とか、いろいろ制約条件も出てまいります。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ障害者の方が安全に避難できるような体制を検討してつくっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、こういう業務を社会福祉協議会のほうに移す理由なんですけど、土曜日の窓口対応という、拡大するという理由だけで社会福祉協議会のほうに移されるんでしょうか。土曜日をもっと開いてほしいという要望が障害者の方から出されていたのか、そこら辺の理由について１点お聞きしたいのと。","respondent":"日下部障害者福祉課長","answer":"ガイドヘルパーの派遣との関係で申しますと、支援費との関係はどうなんだということなんですが、今のところ２３区の課長会のほうでもその辺の話が出ておりますけれども、これは予算上の補助を受けまして実施をしている事業ということで。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一般的な区民の感覚からすれば、区役所を知らない人はいないと思うんですけど、社会福祉協議会を知らない人はいっぱいいると思うんです。例えばデイサービスとか何かと合わせて使うというふうなこともあるんではないかと思うんですけど、そういう場合も支援費の関係はこちらに申し込み、このことについては向こうに申し込みということになっていくのかどうかを教えていただきたいんですけど。","respondent":"日下部障害者福祉課長","answer":"社会福祉協議会が身近なところかどうかというご指摘ですけれども、私どもとしましては、社会福祉協議会、この間のいろんなサービス提供への取り組みというのはかなり幅広く行っておりまして、そういった意味では区民の皆さん方にとっては。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"知的障害者のことで言えば、申し込みの時点で区に来た上に、なおかつ向こうにも行かなきゃいけないのかと。今までだったら区の窓口１カ所で全部済んでいたものが、区の窓口に来ながら、なおかつ向こうにも行かなきゃいけないのかということがあるのかなと思うんですけれども。","respondent":"日下部障害者福祉課長","answer":"それよりも、むしろ先ほどのお話にもありましたように、土曜日の窓口での対応とか、そちらのウエートのほうが高くなるんではないか、このように判断をしております。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は頻繁にということではなくて、はじめにそういう支援費制度についてでもそんなに頻繁に来るものではありませんから、そのときにこちらにも来、そちらにも行きというのがないように１カ所で済むというほうがよりいいのではないかなと思って、この問題だけで申し込むという方はそちらに行くということがあったにしても、一つの窓口で全部対応できるようにということもぜひ考えていただきたいなと思います。","respondent":"日下部障害者福祉課長","answer":"ということで、当面はこの３事業について移行するということで進めてまいりたい、このように考えています。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうところからいっても、これから障害者施策もつくっていくというふうなこともありますし、ぜひこれは区から離さないで、区民が見えるというところ、障害者の方が直接見えるというところからもぜひ区でやるべき事業なんではないかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"鶴副委員長","kind":"質問","question":"より便利で利用しやすいサービスということで社会福祉協議会ということに、この三つの事業を移行するということでございました。ところで、この申請に当たって、電子申請というのはどうなのですか。","respondent":"日下部障害者福祉課長","answer":"ただ、今年の４月の時点では、まだそこまではいっておりませんので、今後、これは私どもの障害者福祉関係だけではなくて、ほかの業務についての電子申請、国のほうでも、それから私ども区のほうでも、ｅ区役所ですか。","id":"exchange-046"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"わかりました。できるだけ社会福祉協議会自身も、皆さんにより便利な方策というものを導入をしていただきたいなというふうに思っているわけですが、例えばこの白いつえとかＴ字型のつえの交付ですね。この仕組みを教えていただけませんか。これはどういうふうになるのか。","respondent":"日下部障害者福祉課長","answer":"そうしましたら、特段、つえの交付についてはそれ以上の要件はございませんので、視覚障害の方であるか、それとも肢体不自由の方であるか、それから再交付の場合は、最初に交付させていただいてから５年以上たっているか、それを手帳に記載するようになっていますので。","id":"exchange-047"},{"speaker":"鶴副委員長","kind":"質問","question":"高齢者が補助用具としてつえを必要とする場合に、社会福祉協議会が窓口になっていますね。これはどちらかというとすごく面倒です。仕組みはどうなっていますか。要するに、どういうことかというと、まず地域の民生委員に申請をする。その承諾書みたいなのをもらったら、認知証というんでしょうかね。そしてつえを借り受けると、こういう仕組みになっているんではないですかね。","respondent":"高橋総務部副参事","answer":"それで、敬老杖につきましては、７５歳以上の高齢者で虚弱ということで歩けない方、それで私どもで窓口を民生委員ということでお願いしているものにつきましては、社会福祉協議会の窓口まで取りに来ていただくのも大変ですので。","id":"exchange-048"},{"speaker":"鶴副委員長","kind":"意見","question":"そうすると、今度は初めてこの白いつえだとかＴ字の交付を受ける人の扱いはどうなりますか。今までは最高５年間で１度、高度障害者の件ですね。先ほどの敬老のつえは、来る人が大変だから民生委員に申請して、民生委員が社会福祉協議会の窓口に来て、それで当該の希望された方のおうちに届けるんですよと、こういうふうなご説明でしたね。ここで言う白いつえとＴ字型のつえというのは行かなきゃいけない。","respondent":"日下部障害者福祉課長","answer":"障害者のＴ字と白杖につきましては、窓口に来ていただくことになります。ただし、手帳を提示していただければその場でお渡しをする、そういう仕組みになっています。","id":"exchange-049"},{"speaker":"鶴副委員長","kind":"質問","question":"そういう高齢者の敬老杖と障害者用の補助器具についての差というのが出てくるわけです。極端な例ですけど、目の不自由な方に、別のつえもなしに取りに来てくださいということになるのですかと。極端な言い方をすると、その人にだれかに一緒に連れてきてもらいなさいとか、あるいは一人で頑張っていらっしゃいということになるのですか。いや、そうじゃなかったらそうじゃないというふうに言ってほしいんです。","respondent":"日下部障害者福祉課長","answer":"それで、障害者の方につきましては、ほかのサービスも含めて基本的には手帳の交付の問題なんかもありますから、窓口に来ていただくということで、一応すべての仕組みを統一して実施をしておりますけれども、４月以降につきましては。","id":"exchange-050"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"心配になるのは、民間だからといって区が口を差し挟む余地はないのかもしれませんが、社会福祉協議会の代表の方が来ているから、社会福祉協議会の体制のほうはどうなんですか。ちゃんとそういう配慮は社会福祉協議会の中で案件として検討されて体制は万全なのかどうか、そこあたりわかる範囲で結構ですが、どちらでも結構です。","respondent":"日下部障害者福祉課長","answer":"今後は、先ほどの前段の報告の中でもご説明させていただきましたけど、来年度地域福祉計画の策定ということにも取りかかってまいりますけれども、この中におきましても、社会福祉協議会の地域福祉を推進する上での役割。","id":"exchange-051"},{"speaker":"鶴副委員長","kind":"質問","question":"計画の中に盛り込みたいというのは、その人員の体制を含めての話ですか。","respondent":"日下部障害者福祉課長","answer":"体制の問題につきましては、今も区としても最大限できる限りの体制をとっているわけですけれども、計画の中で今後の社会福祉協議会の役割、体制がどうあるべきかという基本的な方向性をまずしっかりと形づくってまいります。","id":"exchange-052"},{"speaker":"鶴副委員長","kind":"質問","question":"そうすると、現在の社会福祉協議会の体制という中で、中枢の職員体制というのはちなみに何人ですか。","respondent":"高橋総務部副参事、小沼福祉事業部長","answer":"各係に係長が４名、それと職員ということで、大体３５名の運営でなっております。そういう点でこういうものを移行したことによって社会福祉協議会事務にいびつさが出るということはないというふうに私どもでは考えてあります。","id":"exchange-053"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"つえ一つといえども、これから検討するということですが、民生委員にお願いする、お願いしないは別問題として、ローテーションというのがあるから何百人といらっしゃるわけではないと思うけど、このところは社会福祉協議会の職員にお願いすることになるかもしれないけれども、１年間にどのくらいの申請があるかわかりませんが、届けてあげるというような配慮を含めて前向きにぜひ検討をしていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"嶋委員","kind":"質問・要望","question":"車っていろんなことをしているんですから。そこら辺のこともお聞かせいただきたいと思います。それから、２階に上がってから入り口もそうですけど、ドア、ドア、ドアで大変重たいドアなんです。ですので、そこら辺のことも予算もあると思いますので、すぐにはできないと思いますけど、将来的に向けて社会福祉協議会がもうちょっと使いやすいような建物になるといいなと思います。","respondent":"日下部障害者福祉課長","answer":"場所の問題とかエレベーターの問題が出ました。場所の問題についても、まごつかないように表示とか案内をしっかりしていくということも含めてできる限りの対応はしていきたいと思っています。","id":"exchange-055"},{"speaker":"嶋委員","kind":"質問","question":"すみません。体制のことは先ほどお話がありましたように、今３５人いらっしゃるということにびっくりしたんですが、何度かお伺いをさせていただいていますが、受付がどこかはっきりわからない。","respondent":"高橋総務部副参事","answer":"窓口対応ですが、人数が少ない中でできる限りやっておりますが、来庁者によくできた窓口と言われるように努力してまいりたいと思いますのでよろしくお願いいたします。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今のいろいろ論議を聞いていて、ますますなぜ社会福祉協議会なのかというふうなところがよくわからないんですけれども、この福祉タクシー券にしても、それからこの利用申し込みにしても、つえにしても、窓口としてはそんなには大変な業務ではないんではないかなと思うんですけど、こういうところは社会福祉協議会でもできるけれども、区の窓口でもできると。","respondent":"日下部障害者福祉課長","answer":"先ほど申し上げましたように、今回の窓口の移行につきましては、基本的に行政と、それから社会福祉協議会という地域福祉の推進のかなめになるところ、その辺の役割分担を進めていこうと、そういう一環でもありますし。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう点で言えば、多分区の窓口に来るのは手帳の問題もありますし、ケースワーカーへの相談のこともありますし、そういうふうなところで何回も窓口を訪れるということはあると思うんです。そういうふうなときに、じゃ、つえというときになったら、つえは向こうというんだったら、本当に大変じゃないかなと思うんですけど、そこら辺のところはどう考えられているんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ですから、そういった意味では、最初については社会福祉協議会の窓口のほうへ行っていただくということになりますけれども、ただ、それ以降は５年に１遍でもありますので、大きな負担になるということでは私どもでは受けとめておりません。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが大変だと、わざわざ何でということになると思うんです。だから、そこら辺のところはもう一回ご検討いただきたいなと思います。それから、今回社会福祉協議会に移行するというふうなことで、業務委託ということになるのかな思うんですけど、そこの委託費についてはどの程度になるのかを教えてください。","respondent":"日下部障害者福祉課長","answer":"利用者への周知の問題につきましては、先ほどもご説明させていただきました広報誌での周知、それからホームページ、団体への案内、そういうことも含めましてＰＲについては混乱しないように徹底してまいりたいと考えています。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"移行期間は設けられないということなんですが、多分もうこれだけの周知で周知徹底というのは難しいと思うんです。だから、本当に区に来ちゃう方というのはないとは言えないのではないのかなと思うんですけれども、障害を持った方にわざわざ向こうまで行っていただくということがないような方向でぜひご検討いただきたいと思うんです。","respondent":"日下部障害者福祉課長","answer":"移行期間の問題につきましては、とにかくサービスの低下を招くようなことになってはいけませんので、それについては混乱のないように私どもなりにしっかりと対応してまいりたいと考えています。","id":"exchange-060"},{"speaker":"須藤委員","kind":"質問","question":"さきにあった支援費制度というのも、これからはそこの関連が来るんじゃないかなという予想をしていますので、事業者とか云々と。ですから、意見としては、今後そういった状況、社会福祉協議会自体のありようと介護福祉、障害者福祉と両方連携をとっていく絵をしっかりつくっていかないと、今後いろんな問題点が出てこうようかと思うので、その辺を考えてお願いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"私ども本当に利用者の方に一番いいような形で進めていくということが基本ですので、最大限頑張っていきたいと思います。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問","question":"今いろいろ議論がありました。だから、こういうようなことを具体的に始めていくわけですから、須藤委員の意見にも重なってくるんですけど、少なくともここが社会福祉協議会であるということの看板とか、それから、大井町駅からのアクセスの方法とか、看板の表示とか、同じように品川区役所からのアクセスの表示とか、そういうふうにハード面でも考えていく必要があるんではないでしょうか。","respondent":"日下部障害者福祉課長","answer":"改めて今ご指摘いただきました。表示の問題、あるいはアクセスについてのしっかりした対応、それから、道路条件の問題も含めましてしっかりやるべきというご指摘をいただきました。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほども、他に社会福祉協議会の窓口が移っていくことがあるのかというふうなことでお聞きしたんですが、先ほど出ましたように、支援費の窓口が社会福祉協議会のほうに変わっていくということも将来考えられることってあるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ただ、これから地域福祉の展開の中で、支援費制度ということではなくて、地域福祉を進めていく上で行政とそういう社会福祉協議会とのいろんな役割分担ということも含めて、これからはその辺の整理をしっかりやっていく必要があるだろう、そういうことです。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、もう一点は、この介護支援センターを整備するのに当たっては、施設整備の予算というのは、国のほうからとかも補助金が出るのかなというふうに思うんですけれども、ここら辺の補助金と、それから介護支援センターに対しての運営費補助というのが、国と都と区のそこら辺のところがどうなっているのかを教えてください。","respondent":"早津高齢福祉課長","answer":"さらに中長期のことでいえば、ちょっとわかりかねる面もありますけれども、民間の事業者等々の分担等も含めて検討をしてまいりたいというふうに考えているところです。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"運営費補助は、基本的に国から４分の３ということですが、区からとかは全く入ってなくて、国から運営費の４分の３が入るということなんでしょうか。この総額が、一在宅介護支援センター当たり、およそどれぐらいの運営費補助が出ているのかをちょっと教えていただきたいと思います。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"支援センターの運営費、基本と申しますと、私、補助金のような形を言いましたけれども、介護報酬です。介護報酬以外の事柄につきましては、４分の３の補助が国から出るという形で、区の持ち出しが１カ所について、大体３００……。１カ所当たり在宅介護支援センターは、通常の居宅支援以外の業務を行うということで、１カ所３６０万円ぐらいが定額です。それの４分の３が国、都から補助で出て、４分の１を区が負担すると、そういう関係です。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今後はとりあえずは１９カ所で、あとは民間事業所の分担も考えているということですので、ぜひこのところでは、民間の居宅介護支援事業者は区内にたくさんあるので、そちらのほうにもケアプランが平等に回るような仕組みの方向にぜひ変えていただきたいなというふうに思います。","respondent":"早津高齢福祉課長","answer":"現在ですと１７カ所です。９月現在で申しますと、７２名です。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのことを一つ確認をお願いしたいのと、それとこの介護支援センター、先ほどもありましたように、介護保険だけでなくて介護予防ですとか、介護保険が必要だけれども、なかなか受けていない方の掘り起こしだとか、そういうふうなところでの仕事の中身というものも介護支援センターの中には求められていると思うんですけれども、そこら辺のところで、地域介護予防生活支援システムというふうなところで。","respondent":"早津高齢福祉課長","answer":"地域ケア会議には、さまざまな形での開催というものが考えられるわけですが、品川区でとりわけ重点的に行っておりますのは、地域ごとでのケースを題材としました、ケースの検討会議です。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません。なかなかこういう報告のときがないので、いろいろ聞いちゃってあれなんですけれども。この地域ケア会議のメンバーについて教えていただきたいんですけれども。","respondent":"早津高齢福祉課長","answer":"基本的には支援センターのケアマネジャーと、私ども高齢福祉課が統括支援センターという形になってありますので、その保健婦及び地区担当の職員がメンバーです。","id":"exchange-068"},{"speaker":"鶴副委員長","kind":"質問","question":"この２つ目、委託する大崎ホームヘルプサービスでしたか、それから日本福祉サービスですね。ここは言うところの大手とか中とか小とか、どのランクに入るんですか。","respondent":"早津高齢福祉課長","answer":"大崎ホームヘルプサービスのほうは、地元の従来からホームヘルプサービスを業としていた会社の中の一社です。それから日本福祉サービスは、一応全国展開をしている会社ということになります。日本福祉サービスのほうは、こういう業界の中では大手ということになります。","id":"exchange-069"},{"speaker":"鶴副委員長","kind":"質問","question":"そうすると、よくどこかの政党が言うように、すべて大手だというようなことではないということですね。品川区は居宅サービス事業者を含めて大手ばっかしという、しょっちゅうどこかの政党から聞くんですけれども。大崎ホームヘルプサービスが今度東品川あたりの在宅介護支援センターを担当するということは、そういうことが言えるのではないかと思いますが、いかがですか。","respondent":"早津高齢福祉課長","answer":"在宅介護支援センター、今回で１９カ所目ということになりますが、地元の事業者は２つ目です。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270319?Template=document&Id=3012#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":61143,"voices":182}},{"id":"h14-20020305-8","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"建設委員会","time":"午前１０時０５分～午後１２時３５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","topics":[{"id":"topic-01","title":"平成１４年請願第１号 大崎駅東口・西口自転車等駐車場に関する請願","agenda":"平成１４年請願第１号 大崎駅東口・西口自転車等駐車場に関する請願","exchanges":[{"speaker":"上山委員","kind":"質問","question":"特に大崎第二自転車駐車場は今までは屋根があったりとか、今度東口だとか西口第三などは高架下になっていて、それなりの場所ですからいいかもしれませんけれども、使う方から見れば大崎第二などはどうしてもモニターがあるにしてもかなり離れたところですし、人がいるところからすればね。何とか工夫ができるんじゃないかと思うんですけれども。こういうのは工夫があればなと思います。","respondent":"中村交通安全担当課長","answer":"今の電磁ロック等の関係ですけれども、いろいろ防犯上の対策があろうかと思いますが、ただ電磁ロックにした場合に何が防げるかといいますと、自転車そのものを持っていかれないということがありますけれども、ただパンクをさせられるとか、部品を持っていかれるとか。","id":"exchange-001"},{"speaker":"辻委員","kind":"質問・要望","question":"一つは、請願項目の１番目に問題については、防犯という観点から見たときに工夫する必要があると思うんです。ですから、防犯といっても、盗難という防犯、自転車に対していらずらという防犯もあるわけですけれども、もう一つはやはり女性に対する犯罪的なもので工夫しないといけない。これは地元の方ですから、それを当然わかった上で言ってくれているんだと思いますので、その辺をお願いしたいと思います。","respondent":"中村交通安全担当課長","answer":"今、ご質問がありました関係ですけれども、防犯対策は照度等を含め、またパトロール等をできる限りの部分を対応していかなければいけないと考えております。ただ、先ほどお話のありました電磁ロックにつきましては、料金徴収のための部分もかなりあります。","id":"exchange-002"},{"speaker":"辻委員","kind":"質問","question":"今度は逆に定期利用の方はどうなのかなと、その辺の状況を見て、がらがらにあいている、今電磁ロックになっているものを取り外せというのは大変な話ですから、例えばもし定期の人がいっぱいあふれていて断るような形になっていて、一時利用があいているのならもう少し、１０７台のうち何割か、例えば定期利用の２７９台があふれている状況によっては。","respondent":"中村交通安全担当課長","answer":"西口の定期利用はいっぱいの状況で、当日利用もすぐいっぱいになっているという状況です。この辺のところは、何らかの対策が必要なのかなということで、現在西口第三がスペース的に余裕があるということで、こちらのほうに当日利用を設けられないかということで、現在検討中です。","id":"exchange-003"},{"speaker":"本間委員","kind":"意見","question":"「防犯という部分についてはあまりよく聞かないんだけれども、前よりうんとよくなっているように思うけれども、有料駐輪場になってからどうかね」という話を尋ねてまいりましたら、これまでにひと月に一、二件あるかないかというような自転車事情でした。したがいまして、始めてまだ１年も経っておりませんし、推移を見守りながら、これからの検討課題にしていくべきものかなというふうに考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"今日、現地を見させていただいて、有料駐輪場ということで整然と並んでいたりして、随分いいことだなと思いました。質問としては、防犯上の問題で、防犯カメラをつけたということですけれども、これはかなり高価なものなのかどうかという費用的な面が一つ。それから、７日間で撤去ということが書いてありましたけれども、撤去をするような状況が有料駐輪場をつけてからどの程度あるのかということ。","respondent":"中村交通安全担当課長、中谷まちづくり事業部長","answer":"今、７日間で撤去という関係ですけれども、これで考えられるのは一時利用でだれかが人のものを乗ってきて、そこに放っておかれるということが考えられるということで、これまでにも無料駐輪場で運営していた中で。私のほうから今までの経過も含めまして、補足します。防犯カメラの値段は把握しておりませんので、後ほど調べましてお知らせしますが、私の記憶では、１００万円もするような高いものではなかったような気がいたします。","id":"exchange-005"},{"speaker":"築舘委員","kind":"質問","question":"個人的には一家に３台ということで、家計が厳しいわけですけれども、しかしお金を払って、責任を持って秩序正しいものを自分の責任でやっていくということが大切なことですから、ただにするということではなくて、使用料減免ということも考慮に入れながらやっていくということも、私としてはいいことではないかというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"それをあえて無料だったものを有料にするわけですから、確かに整然となっていますから、利用者の受益というものはもちろんあることは認めるんですけれども、なるべく低廉にすべきだという思いが一つあります。そういう中で、２１世紀を支える人たちに対する温情というか、温かい心があってしかるべきではないか。意見表明と質問がごちゃごちゃになってしまいましたけれども、最初の点だけお願いします。","respondent":"中村交通安全担当課長","answer":"ただ、こういうものは全体のあれもありますので、大崎だけ電磁ロックでほかのところはという問題になりますと、ほかのところも電磁ロックになりますと、大井町はスイングラック式ということで間隔を非常に狭めて、できるだけ多くの台数が止められるようにしていますので。","id":"exchange-007"},{"speaker":"沢田委員","kind":"意見","question":"私、買ったばかりのバイクを奪われて、結局出てこないんです。そういう点からすると、やっぱり照明を明るくする問題と、防犯的に盗難は絶対にないようなシステムを取るべきではないのかなと思います。この請願はいろいろありましたけれども、うちの党としては賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"全体に賛成の方向ですから、あえていいんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"築舘委員","kind":"意見","question":"先ほど言ったんですけれども、この請願は有料駐輪場というのは認めていて、ただし今後の問題として防犯上の対策、学生に対する使用料の減額ということですので、実際上は防犯もよくされていると思います。学生に対する使用料減額に関しても、総体的に見ていかなければいけない問題だと思いますが、趣旨としては賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"辻委員","kind":"意見","question":"先ほども言いましたように、請願の趣旨に賛成という形でお願いしたいと思います。特に、防犯については取り組みがなされている。そういう中で考える大きな課題でもあると思うんです。私は今回の請願を一つの大きなきっかけにして、今後の課題とするということで、趣旨採択でやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は採択でいいのではないかと思います。防犯上の問題はさっき出ました。それから、学生に対する使用料の減額の問題は、この問題だけではなくて２１世紀の若い人たちは、定職にもつけないさまざまな問題を抱えているわけです。ですから、ぜひこれは区内全域に対して検討を加えていただきたいと思います。皆さんが趣旨採択であれば、趣旨でもかまいません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"本間委員","kind":"質問・要望","question":"特に、端っこのほうにバイクだとか置いてある場合には、結構野ざらしに近い状態で、非常に雨風をおうことがあるものですから、将来的には屋根つきと屋根つきではなくて、両方とも屋根がつくような形のものに統一していただければいいのかなと、それこそ費用対利用料との問題もありますので、できるだけそういう部分は屋根があるなら屋根つきということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"平成１４年陳情第５号、ゲートボール場新設の陳情","agenda":"平成１４年陳情第５号、ゲートボール場新設の陳情","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"「天然芝で決めています」と言ったときに、ゲートボール協会の方は何と言っておられたんでしょうか、「わかりました」と言ったんですか。","respondent":"岩田管理工事課長","answer":"そのときは「ゲートボールを競技する場所に困っておられるので、人工芝に何とか変えられないか」ということを再三おっしゃっておられましたけれども、区として「非常に、現在のところは難しいです」というふうにお答え申し上げました。","id":"exchange-014"},{"speaker":"沢田委員","kind":"意見","question":"この陳情の扱いというか、考え方が多目的で天然芝でもゲートボールができるんだからというと、最後の多目的広場にゲートボールができるようにというのはオーケーになるんですけれども、天然芝ではだめなんだということになると、陳情の趣旨とはどうなのかなと大変迷うんですけれども、これを課長に聞くのも何か変な話になってしまうのかなと。","respondent":"岩田管理工事課長","answer":"ここは多目的でお使いになるということを想定しておりますので、やはりボールの転がり具合とか、いろいろ人工芝と比べるとかなり違うことは事実ですけれども、現在協会の方々もいろんな区立の公園の広場で競技を行っておられるわけですので。","id":"exchange-015"},{"speaker":"沢田委員","kind":"意見","question":"昨日の屋上緑化の話ではないですけれども、それを地上緑化で、私は人工芝より天然芝を拡大したいなというふうに思います。ただ、これはこの陳情と全然違ってしまうとなると大変悩むんですけれども、少し難しいかなという気がするんですけれども、態度を決めかねています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"辻委員","kind":"質問・要望","question":"この多目的広場が完成したら、どういう時間帯、午前中何時頃から貸し出すというふうになるのか。要するに、これは多目的ですから、ゲートボールも利用しても結構ですよというような形になるんですね。日曜日はどうかわからないですけれども、高齢者は大体ウイークデイの早朝にやっているわけですから、ここを３面でも４面でも使えれば大いに利用していただければいいかなと。","respondent":"岩田管理工事課長","answer":"そういった利用ニーズに合わせた形で、コマ割とか、そういったものを考えていかなければいけませんし、また町会とか青少年団体とか、そういう方たちに対する減免措置はどうするのかとか。","id":"exchange-017"},{"speaker":"辻委員","kind":"質問","question":"多目的でこれだけ全体的な中央公園ですから、大勢の子どもが常に遊んだり、場合によってはちょっとしたシートをもってきて寝ころがったりとか、子どもを連れていっぱい来ると思うんです。人工芝でなくて天然芝ですから。もう一つ、西大井の公園でゲートボールをやるときに、利用料は無料なのかどうなのか。今回やるときに、ゲートボールの使用を考えたときに、無料、有料を考えるとどうなんですか。","respondent":"岩田管理工事課長","answer":"ただ、団体とは別に一般の個々の方が来られて、空いているときにこの中に入って遊んでいただくことになると思いますけれども、そういったときは当然のことながら無料として開放することになるだろうと思うんですが、ある特定団体が独占的にお使いになる場合は。","id":"exchange-018"},{"speaker":"辻委員","kind":"質問・要望","question":"ここの使用方法等については、具体的に決まったら教えていただきたい。この辺は請願代表者を含めて、さまざまな使用グループが出てくるかと思うんですけれども、そこに対しては周知して、きちっとしたルール作りが必要かなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"築舘委員","kind":"質問","question":"ですから、基本的にはいろんなスポーツ団体が楽しくそれぞれの地域の方が公園を使ってやるということは大切なことなので、あとはそこの取り決めをしっかりと、ゲートボールの場合は早朝が多いので、早朝にうまく利用できるような、場所的にゲートボールにも使える、ドッジボールも使えるとか、いろいろ何種類か使えるような場所として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"本間委員","kind":"質問・要望","question":"「もしくは多目的グランドでもゲートボール競技ができるように」というような部分は、先ほどもお話がありましたように天然芝でも可というような部分は、この協会の方たちもご理解いただいていると思いますし、現に私どももグラウンドとか公園でやっているところも実際に見ておりますので、十分この趣旨が得られるようなものにしていただけるのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"築舘委員","kind":"質問・要望","question":"先ほども言いましたように、今後のことですので、この中央公園がみんな楽しく地元の方がそれぞれのスポーツをして、また楽しい１日が過ごせるようにという部分で工夫をしていただきたいということで、この趣旨には賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"辻委員","kind":"質問・要望","question":"趣旨に賛同いたします。そういう意味で、ここはゲートボールに使えるんだという、多目的広場の中の説明書の文書の中に、そういった形を入れ込んだ形でやっていただければ、この性格というのは達成されたと思いますので、それは陳情に対して受けたという形になると思いますので、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"平成１３年請願第５号 住友不動産による「仮称大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","agenda":"平成１３年請願第５号 住友不動産による「仮称大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","exchanges":[{"speaker":"上山委員","kind":"確認","question":"一つだけ確認ですけれども、１２月１０日に東京都へ総合設計の何をしたと言われたんですか。","respondent":"浜脇住環境整備課長","answer":"１２月１０日に総合設計の許可がおりました。それに対する審査請求です。","id":"exchange-024"},{"speaker":"上山委員","kind":"意見","question":"現地でも説明がありましたけれども、土壌を排出したりして、囲いもできて、囲むような感じでやっているんですけれども、たまたま都営住宅の皆さんの説明会に出たんですが、地元のほうでも全体としてはしようがないと。工事協定を結ぶ調整中と聞いていますので、もうちょっと様子を見たらどうかと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"辻委員","kind":"質問","question":"私も継続でお願いしたいなと。今、工事協定書とかいろいろ話がありますし。例えば費用の問題とか、そういうのは話し合いで。風の問題はどこにどうしたらいいというか、非常に古くて新しい課題だなという感じがしたんです。その辺の傾向をどうお考えになっているのか、ちょっとお聞きしたい。この問題に関係ないかもわからないけれども、ただ非常に大きな課題になりつつあるなという印象を持ったものですから。","respondent":"浜脇住環境整備課長","answer":"今後とも、やはりそういったものに対しては、通常１０階ぐらいまではあまり変わらないけれども、やっぱり３０階となりますと影響が出てくるというのが、この例を見てもわかりますので、その辺については今後、私どものほうがそういうものに対して勉強したものを伝えられれば。","id":"exchange-026"},{"speaker":"辻委員","kind":"質問・要望","question":"説明の中で、総合設計制度の中の風害等については、敷地内に２カ所風速計、風力計というのを置かなければいけないとか言っているわけです。住民側には自分たちが住んでいる路地とかそういうことで普段でも風は強いというのは、どういう実態になっているのかと心配しているわけです。これは検討をお願いしたいと、要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/923086?Template=document&Id=3714#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":27483,"voices":79}},{"id":"h14-20020305-9","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"文教委員会","time":"午前１０時０５分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"その目的と、それからこの評価項目、学校の評価に対して、基礎学力、社会性云々という、この上の三つの部分というのはかなり主観的なものというのでしょうか、客観性ということよりも、かなり主観的な評価、例えば基礎学力というと、後段のこれにかかわってくるかわかりませんけれども、どういうふうに評価の項目と目的との関係というのはちょっとよくわからないんですね。どういうふうに公表をするのか。","respondent":"青木指導課長","answer":"こういうところを今年度は改善していきたい、こういうところに力を入れていきたいという形で説明をすることをもって公表していきたいというふうに考えております。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、そこはどうなのかというようなことをもう一回聞きたいんです。最後に条件整備の話は、そういう意味合いではなくて、当然こういう評価をしていく上での教育委員会としての条件整備のやっぱり計画的に持っていくというか、今ももちろん計画的な部分もあるけれども、より強化をしていくとならば、もっと積極的に条件整備を確実にやっていくというのが私は前提だと思うんですけれども、それはどうですか。","respondent":"若月教育長","answer":"したがって、それを少しでも改善するために、どんな方法があるだろうかということを考えたその中で、例えば８名なら８名、１０名なら１０名と、その学校によって多少人の人数は規模によって変わってきますが、その中で、例えば。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"１点だけちょっと、質問じゃなくて要望です。自主性と自律性。開かれたという点では、だからいろいろな意見を聞くという、そのことはいいんですけれども、もう一方では教育の自主性、自律性という問題と外部評価委員が教育、そうしたことについての研修というと大げさなんですけれども、考え方のところはきっちりしていくことが学校の自主性、自律性を尊重していくという、そこを強調したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/207072?Template=document&Id=4432#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":9611,"voices":16}}]);
